function Get-WinToolFontDocument {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Fonts"))
}

function Get-WinToolOhMyPoshDocument {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "OmpThemes"))
}

function Select-WinToolFont {
    param(
        $Font,
        [string]$Query,
        [bool]$NerdOnly = $false,
        [bool]$PlainOnly = $false
    )
    $matched = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Font)) {
        $isNerd = $false
        if ($null -ne $item.PSObject.Properties["nerd"] -and $item.nerd) {
            $isNerd = $true
        }
        if ($NerdOnly -and -not $isNerd) {
            continue
        }
        if ($PlainOnly -and $isNerd) {
            continue
        }
        $haystack = (([string]$item.name) + " " + ([string]$item.face) + " " + ([string]$item.id))
        if (Test-WinToolTextMatch -Haystack $haystack -Query $Query) {
            $matched.Add($item)
        }
    }
    return $matched.ToArray()
}

function Get-WinToolOhMyPoshThemeFile {
    param(
        [string]$PromptStyle
    )
    $themeFile = "jandedobbeleer.omp.json"
    if (-not [string]::IsNullOrWhiteSpace($PromptStyle)) {
        if ($PromptStyle.EndsWith(".omp.json")) {
            $themeFile = $PromptStyle
        }
        else {
            $themeFile = $PromptStyle + ".omp.json"
        }
    }
    return $themeFile
}

function Get-WinToolPromptScript {
    param(
        [Parameter(Mandatory = $true)][string]$PromptId,
        [bool]$TerminalIcons = $true,
        [string]$PromptStyle = "",
        [bool]$PsReadLine = $false,
        [bool]$Zoxide = $false
    )
    # The same text goes into the Windows PowerShell 5.1 and PowerShell 7
    # profiles. Every block is wrapped so a missing tool, an old module, or a
    # missing variable never prints an error when a terminal opens.
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add("# Added by WinTool. Delete this block, or run WinTool again, to change it.")
    if ($TerminalIcons) {
        $lines.Add('try {')
        $lines.Add('    if (Get-Module -ListAvailable -Name Terminal-Icons) {')
        $lines.Add('        Import-Module Terminal-Icons -ErrorAction Stop')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    if ($PsReadLine) {
        # Windows PowerShell 5.1 ships PSReadLine 2.0, which has neither
        # option. PredictionSource came in 2.1 and PredictionViewStyle in 2.2.
        # Predictions also refuse to start when output is redirected.
        $lines.Add('try {')
        $lines.Add('    $wintoolReadLine = $null')
        $lines.Add('    if (-not [Console]::IsOutputRedirected) { $wintoolReadLine = Get-Command -Name Set-PSReadLineOption -ErrorAction Ignore }')
        $lines.Add('    if ($null -ne $wintoolReadLine -and $wintoolReadLine.Parameters.ContainsKey("PredictionSource")) {')
        $lines.Add('        Set-PSReadLineOption -PredictionSource History -ErrorAction Stop -WarningAction SilentlyContinue')
        $lines.Add('    }')
        $lines.Add('    if ($null -ne $wintoolReadLine -and $wintoolReadLine.Parameters.ContainsKey("PredictionViewStyle")) {')
        $lines.Add('        Set-PSReadLineOption -PredictionViewStyle ListView -ErrorAction Stop -WarningAction SilentlyContinue')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    if ($Zoxide) {
        $lines.Add('try {')
        $lines.Add('    if (Get-Command -Name zoxide -ErrorAction Ignore) {')
        $lines.Add('        Invoke-Expression (& { (zoxide init powershell | Out-String) })')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    if ($PromptId -eq "starship") {
        $lines.Add('try {')
        $lines.Add('    $wintoolStarship = Get-Command -Name starship -CommandType Application -ErrorAction Ignore | Select-Object -First 1')
        $lines.Add('    if ($null -eq $wintoolStarship) {')
        $lines.Add('        foreach ($wintoolPath in @(([string]$env:ProgramFiles + "\starship\bin\starship.exe"), ([string]$env:LOCALAPPDATA + "\Programs\starship\bin\starship.exe"))) {')
        $lines.Add('            if (Test-Path -LiteralPath $wintoolPath) { $wintoolStarship = Get-Command -Name $wintoolPath -ErrorAction Ignore; break }')
        $lines.Add('        }')
        $lines.Add('    }')
        $lines.Add('    if ($null -ne $wintoolStarship) {')
        $lines.Add('        Invoke-Expression (& $wintoolStarship.Source init powershell | Out-String)')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    elseif ($PromptId -eq "oh-my-posh") {
        $themeFile = Get-WinToolOhMyPoshThemeFile -PromptStyle $PromptStyle
        # POSH_THEMES_PATH is not set by newer Oh My Posh builds, so WinTool
        # saves the theme under %LOCALAPPDATA%\WinTool\themes during setup and
        # also looks in the older theme folders.
        $lines.Add('try {')
        $lines.Add('    $wintoolPosh = Get-Command -Name oh-my-posh -CommandType Application -ErrorAction Ignore | Select-Object -First 1')
        $lines.Add('    if ($null -eq $wintoolPosh) {')
        $lines.Add('        foreach ($wintoolPath in @(([string]$env:LOCALAPPDATA + "\Programs\oh-my-posh\bin\oh-my-posh.exe"), ([string]$env:ProgramFiles + "\oh-my-posh\bin\oh-my-posh.exe"))) {')
        $lines.Add('            if (Test-Path -LiteralPath $wintoolPath) { $wintoolPosh = Get-Command -Name $wintoolPath -ErrorAction Ignore; break }')
        $lines.Add('        }')
        $lines.Add('    }')
        $lines.Add('    if ($null -ne $wintoolPosh) {')
        $lines.Add('        $wintoolTheme = $null')
        $lines.Add('        foreach ($wintoolFolder in @([string]$env:POSH_THEMES_PATH, ([string]$env:LOCALAPPDATA + "\WinTool\themes"), ([string]$env:LOCALAPPDATA + "\Programs\oh-my-posh\themes"))) {')
        $lines.Add('            if ([string]::IsNullOrWhiteSpace($wintoolFolder)) { continue }')
        $lines.Add('            $wintoolCandidate = Join-Path $wintoolFolder "' + $themeFile + '"')
        $lines.Add('            if (Test-Path -LiteralPath $wintoolCandidate) { $wintoolTheme = $wintoolCandidate; break }')
        $lines.Add('        }')
        $lines.Add('        if ($null -ne $wintoolTheme) {')
        $lines.Add('            (& $wintoolPosh.Source init pwsh --config $wintoolTheme | Out-String) | Invoke-Expression')
        $lines.Add('        }')
        $lines.Add('        else {')
        $lines.Add('            (& $wintoolPosh.Source init pwsh | Out-String) | Invoke-Expression')
        $lines.Add('        }')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    elseif ($PromptId -eq "powerline-go") {
        $lines.Add('function global:prompt {')
        $lines.Add('    $wintoolExit = $LASTEXITCODE')
        $lines.Add('    try {')
        $lines.Add('        $tool = [string]$env:LOCALAPPDATA + "\WinTool\bin\powerline-go.exe"')
        $lines.Add('        if (Test-Path -LiteralPath $tool) {')
        $lines.Add('            return ((& $tool -error $wintoolExit -shell bare) -join "")')
        $lines.Add('        }')
        $lines.Add('    }')
        $lines.Add('    catch { $null = $_ }')
        $lines.Add('    return "PS $($executionContext.SessionState.Path.CurrentLocation)> "')
        $lines.Add('}')
    }
    else {
        $lines.Add("# The prompt for this setup runs inside WSL, not in this PowerShell profile.")
    }
    return ($lines -join "`r`n")
}

function Update-WinToolManagedBlock {
    param(
        [AllowEmptyString()][string]$Text,
        [Parameter(Mandatory = $true)][string]$Begin,
        [Parameter(Mandatory = $true)][string]$End,
        [Parameter(Mandatory = $true)][string]$Body
    )
    $block = $Begin + "`r`n" + $Body.Trim() + "`r`n" + $End
    $pattern = "(?s)" + [regex]::Escape($Begin) + ".*?" + [regex]::Escape($End)
    if ($Text -match $pattern) {
        $evaluator = [System.Text.RegularExpressions.MatchEvaluator]{
            param($found)
            if ($null -eq $found) {
                return $block
            }
            return $block
        }.GetNewClosure()
        return [regex]::Replace($Text, $pattern, $evaluator)
    }
    $prefix = [string]$Text
    if ($prefix.Length -gt 0 -and -not $prefix.EndsWith("`n")) {
        $prefix += "`r`n"
    }
    if ($prefix.Length -gt 0) {
        $prefix += "`r`n"
    }
    return $prefix + $block + "`r`n"
}

function Get-WinToolShellProfilePath {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("powershell", "pwsh")][string]$HostName
    )
    $documents = [Environment]::GetFolderPath("MyDocuments")
    if ($HostName -eq "pwsh") {
        return (Join-Path $documents "PowerShell/Microsoft.PowerShell_profile.ps1")
    }
    return (Join-Path $documents "WindowsPowerShell/Microsoft.PowerShell_profile.ps1")
}

function Get-WinToolTerminalSettingsPath {
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        return $null
    }
    $candidates = @(
        (Join-Path $env:LOCALAPPDATA "Packages/Microsoft.WindowsTerminal_8wekyb3d8bbwe/LocalState/settings.json"),
        (Join-Path $env:LOCALAPPDATA "Microsoft/Windows Terminal/settings.json")
    )
    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate) {
            return $candidate
        }
    }
    $directories = @(
        (Join-Path $env:LOCALAPPDATA "Packages/Microsoft.WindowsTerminal_8wekyb3d8bbwe/LocalState"),
        (Join-Path $env:LOCALAPPDATA "Microsoft/Windows Terminal")
    )
    foreach ($directory in $directories) {
        if (Test-Path -LiteralPath $directory) {
            return (Join-Path $directory "settings.json")
        }
    }
    return $null
}

function ConvertTo-WinToolFontFace {
    param(
        [Parameter(Mandatory = $true)][string]$RegistryName
    )
    $face = $RegistryName -replace '\s*\((TrueType|OpenType)\)\s*$', ''
    return $face.Trim()
}

function Add-WinToolTerminalFont {
    param(
        [Parameter(Mandatory = $true)]$Settings,
        [Parameter(Mandatory = $true)][string]$Face,
        [int]$Size = 12
    )
    if ($null -eq $Settings.PSObject.Properties["profiles"]) {
        $Settings | Add-Member -NotePropertyName "profiles" -NotePropertyValue ([pscustomobject]@{})
    }
    $profiles = $Settings.profiles
    if ($null -eq $profiles.PSObject.Properties["defaults"]) {
        $profiles | Add-Member -NotePropertyName "defaults" -NotePropertyValue ([pscustomobject]@{})
    }
    $defaults = $profiles.defaults
    $font = [pscustomobject]@{
        face = $Face
        size = $Size
    }
    if ($null -eq $defaults.PSObject.Properties["font"]) {
        $defaults | Add-Member -NotePropertyName "font" -NotePropertyValue $font
    }
    else {
        $defaults.font = $font
    }
    if ($null -eq $defaults.PSObject.Properties["fontFace"]) {
        $defaults | Add-Member -NotePropertyName "fontFace" -NotePropertyValue $Face
    }
    else {
        $defaults.fontFace = $Face
    }
    return $Settings
}

$script:WinToolSchemeColorKeys = @("black", "red", "green", "yellow", "blue", "purple", "cyan", "white", "brightBlack", "brightRed", "brightGreen", "brightYellow", "brightBlue", "brightPurple", "brightCyan", "brightWhite")

function Add-WinToolTerminalScheme {
    param(
        [Parameter(Mandatory = $true)]$Settings,
        [Parameter(Mandatory = $true)]$Scheme
    )
    # Windows Terminal ignores a scheme that lacks any of the 16 table colors,
    # so the full palette is written before a profile points at the name.
    $fields = [ordered]@{
        name = [string]$Scheme.name
        background = [string]$Scheme.background
        foreground = [string]$Scheme.foreground
        cursorColor = [string]$Scheme.cursor
        selectionBackground = [string]$Scheme.selection
    }
    $palette = Get-WinToolNote -Object $Scheme -Name "palette"
    foreach ($key in $script:WinToolSchemeColorKeys) {
        $value = [string](Get-WinToolNote -Object $palette -Name $key -Default "")
        if ([string]::IsNullOrWhiteSpace($value)) {
            throw ("The color scheme " + [string]$Scheme.name + " has no " + $key + " color.")
        }
        $fields[$key] = $value
    }
    $entry = [pscustomobject]$fields
    $existing = @()
    if ($null -ne $Settings.PSObject.Properties["schemes"] -and $null -ne $Settings.schemes) {
        $existing = @($Settings.schemes)
    }
    $kept = New-Object System.Collections.Generic.List[object]
    foreach ($item in $existing) {
        if ([string]$item.name -ne [string]$entry.name) {
            $kept.Add($item)
        }
    }
    $kept.Add($entry)
    if ($null -eq $Settings.PSObject.Properties["schemes"]) {
        $Settings | Add-Member -NotePropertyName "schemes" -NotePropertyValue ($kept.ToArray())
    }
    else {
        $Settings.schemes = $kept.ToArray()
    }
    if ($null -eq $Settings.PSObject.Properties["profiles"]) {
        $Settings | Add-Member -NotePropertyName "profiles" -NotePropertyValue ([pscustomobject]@{})
    }
    if ($null -eq $Settings.profiles.PSObject.Properties["defaults"]) {
        $Settings.profiles | Add-Member -NotePropertyName "defaults" -NotePropertyValue ([pscustomobject]@{})
    }
    if ($null -eq $Settings.profiles.defaults.PSObject.Properties["colorScheme"]) {
        $Settings.profiles.defaults | Add-Member -NotePropertyName "colorScheme" -NotePropertyValue ([string]$entry.name)
    }
    else {
        $Settings.profiles.defaults.colorScheme = [string]$entry.name
    }
    return $Settings
}

function Save-WinToolOhMyPoshTheme {
    param(
        [Parameter(Mandatory = $true)][string]$ThemeFile
    )
    # Keeps a copy of the theme where the profile can always find it.
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        return $null
    }
    $folder = Join-Path $env:LOCALAPPDATA "WinTool\themes"
    $target = Join-Path $folder $ThemeFile
    try {
        if (-not (Test-Path -LiteralPath $folder)) {
            New-Item -ItemType Directory -Path $folder -Force | Out-Null
        }
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
        $url = "https://raw.githubusercontent.com/JanDeDobbeleer/oh-my-posh/main/themes/" + [uri]::EscapeDataString($ThemeFile)
        Invoke-WebRequest -Uri $url -OutFile $target -UseBasicParsing -TimeoutSec 30
        Write-WinToolLog -Message "Saved the Oh My Posh theme to $target" -Level "ok"
        return $target
    }
    catch {
        if (Test-Path -LiteralPath $target) {
            Write-WinToolLog -Message "Could not refresh the Oh My Posh theme, so the saved copy is kept. $($_.Exception.Message)" -Level "warn"
            return $target
        }
        Write-WinToolLog -Message "Could not download the Oh My Posh theme $ThemeFile, so the default theme will be used. $($_.Exception.Message)" -Level "warn"
        return $null
    }
}

function Write-WinToolShellProfile {
    param(
        [Parameter(Mandatory = $true)][string]$PromptId,
        [bool]$TerminalIcons = $true,
        [string]$PromptStyle = "",
        [bool]$PsReadLine = $false,
        [bool]$Zoxide = $false
    )
    if ($PromptId -eq "oh-my-posh") {
        Save-WinToolOhMyPoshTheme -ThemeFile (Get-WinToolOhMyPoshThemeFile -PromptStyle $PromptStyle) | Out-Null
    }
    $body = Get-WinToolPromptScript -PromptId $PromptId -TerminalIcons $TerminalIcons -PromptStyle $PromptStyle -PsReadLine $PsReadLine -Zoxide $Zoxide
    $paths = @(
        (Get-WinToolShellProfilePath -HostName "powershell"),
        (Get-WinToolShellProfilePath -HostName "pwsh")
    )
    foreach ($path in $paths) {
        $directory = Split-Path -Parent $path
        if (-not (Test-Path -LiteralPath $directory)) {
            New-Item -ItemType Directory -Path $directory -Force | Out-Null
        }
        $existing = ""
        if (Test-Path -LiteralPath $path) {
            $existing = [System.IO.File]::ReadAllText($path)
        }
        $updated = Update-WinToolManagedBlock -Text $existing -Begin $script:WinToolProfileBegin -End $script:WinToolProfileEnd -Body $body
        Write-WinToolUtf8File -Path $path -Text $updated
        Write-WinToolLog -Message "Updated $path" -Level "ok"
    }
}

function ConvertTo-WinToolFontToken {
    param(
        [AllowEmptyString()][string]$Text
    )
    return ([string]$Text).ToLowerInvariant().Replace(" ", "").Replace("-", "").Replace("_", "")
}

function Find-WinToolInstalledFontFile {
    param(
        [Parameter(Mandatory = $true)][string]$Token,
        [object[]]$Entry
    )
    # Entries are registry font values: Name like "CaskaydiaCoveNerdFont-Regular
    # (TrueType)", Data the file. The regular style is preferred, and the
    # proportional Nerd Font variant is skipped when another one exists.
    if ($null -eq $Entry) {
        $Entry = @(Get-WinToolRegisteredFont)
    }
    $want = ConvertTo-WinToolFontToken -Text $Token
    if ([string]::IsNullOrWhiteSpace($want)) {
        return $null
    }
    $hits = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Entry)) {
        $name = ConvertTo-WinToolFontToken -Text ([string]$item.Name)
        $file = ConvertTo-WinToolFontToken -Text ([System.IO.Path]::GetFileName([string]$item.Data))
        if ($name.Contains($want) -or $file.Contains($want)) {
            $hits.Add($item)
        }
    }
    if ($hits.Count -eq 0) {
        return $null
    }
    $best = $null
    $bestScore = -1
    foreach ($item in $hits) {
        $text = ConvertTo-WinToolFontToken -Text ([string]$item.Name)
        $score = 0
        if ($text.Contains("regular")) { $score += 2 }
        if (-not $text.Contains("propo")) { $score += 1 }
        if ($score -gt $bestScore) {
            $best = $item
            $bestScore = $score
        }
    }
    return $best
}

function Get-WinToolRegisteredFont {
    if (-not (Test-WinToolWindows)) {
        return @()
    }
    $list = New-Object System.Collections.Generic.List[object]
    $sources = @(
        @{ Key = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts"; Folder = (Join-Path $env:windir "Fonts") },
        @{ Key = "HKCU:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts"; Folder = (Join-Path $env:LOCALAPPDATA "Microsoft\Windows\Fonts") }
    )
    foreach ($source in $sources) {
        if (-not (Test-Path -LiteralPath $source.Key)) {
            continue
        }
        $item = Get-Item -LiteralPath $source.Key
        foreach ($name in @($item.GetValueNames())) {
            if ([string]::IsNullOrWhiteSpace([string]$name)) {
                continue
            }
            $data = [string]$item.GetValue($name)
            if (-not [string]::IsNullOrWhiteSpace($data) -and -not [System.IO.Path]::IsPathRooted($data)) {
                $data = Join-Path $source.Folder $data
            }
            $list.Add([pscustomobject]@{ Name = [string]$name; Data = $data })
        }
    }
    return $list.ToArray()
}

function Get-WinToolFontFamilyName {
    param(
        [string]$Path
    )
    # The family name inside the file is what Terminal needs in "face".
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) {
        return $null
    }
    try {
        Add-Type -AssemblyName PresentationCore
        $glyph = New-Object System.Windows.Media.GlyphTypeface ([uri]$Path)
        $names = $glyph.Win32FamilyNames
        $english = [System.Globalization.CultureInfo]::GetCultureInfo("en-US")
        if ($names.ContainsKey($english)) {
            return [string]$names[$english]
        }
        foreach ($value in $names.Values) {
            return [string]$value
        }
    }
    catch {
        $null = $_.Exception.Message
    }
    return $null
}

function Resolve-WinToolInstalledFontFace {
    param(
        [Parameter(Mandatory = $true)][string]$Face,
        [string]$Match
    )
    # Returns the face to write into Terminal settings, or $null (with a
    # warning) when the font is not installed.
    $chosen = $Face
    if (-not [string]::IsNullOrWhiteSpace($Match) -and (Test-WinToolWindows)) {
        $found = Find-WinToolInstalledFontFile -Token $Match
        if ($null -eq $found) {
            Write-WinToolLog -Message ("{0} is not installed, so the Windows Terminal font was left as it is. Run terminal setup again after the font installs." -f $Face) -Level "warn"
            return $null
        }
        $family = Get-WinToolFontFamilyName -Path ([string]$found.Data)
        if (-not [string]::IsNullOrWhiteSpace($family)) {
            $chosen = $family
        }
        if ($chosen -ne $Face) {
            Write-WinToolLog -Message "Using the installed font name: $chosen" -Level "info"
        }
    }
    return $chosen
}

function Invoke-WinToolTerminalFont {
    param(
        [Parameter(Mandatory = $true)][string]$Face,
        [string]$Match
    )
    $chosen = Resolve-WinToolInstalledFontFace -Face $Face -Match $Match
    if ($null -eq $chosen) {
        return
    }
    $path = Get-WinToolTerminalSettingsPath
    if ([string]::IsNullOrWhiteSpace($path)) {
        Write-WinToolLog -Message "Windows Terminal settings were not found. Open Terminal once, then run terminal setup again to set the font." -Level "warn"
        return
    }
    $settings = [pscustomobject]@{}
    if (Test-Path -LiteralPath $path) {
        $backup = $path + ".wintool-backup"
        if (-not (Test-Path -LiteralPath $backup)) {
            Copy-Item -LiteralPath $path -Destination $backup -Force
            Write-WinToolLog -Message "Saved a backup of Terminal settings next to settings.json." -Level "info"
        }
        $raw = [System.IO.File]::ReadAllText($path)
        if (-not [string]::IsNullOrWhiteSpace($raw)) {
            $settings = ConvertFrom-WinToolJsonText -Text $raw
        }
    }
    Add-WinToolTerminalFont -Settings $settings -Face $chosen -Size 12 | Out-Null
    $json = ConvertTo-WinToolJsonText -Value $settings
    Write-WinToolUtf8File -Path $path -Text ($json + "`n")
    Write-WinToolLog -Message "Set the Windows Terminal font to $chosen. Comments in settings.json are not kept." -Level "ok"
}

function Invoke-WinToolTerminalScheme {
    param(
        [Parameter(Mandatory = $true)][string]$SchemeId
    )
    $scheme = $null
    foreach ($item in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "schemes" -Default @())) {
        if ([string]$item.id -eq $SchemeId) {
            $scheme = $item
            break
        }
    }
    if ($null -eq $scheme) {
        Write-WinToolLog -Message "Unknown color scheme '$SchemeId'." -Level "warn"
        return
    }
    $path = Get-WinToolTerminalSettingsPath
    if ([string]::IsNullOrWhiteSpace($path)) {
        Write-WinToolLog -Message "Windows Terminal settings were not found, so the color scheme was skipped." -Level "warn"
        return
    }
    $settings = [pscustomobject]@{}
    if (Test-Path -LiteralPath $path) {
        $raw = [System.IO.File]::ReadAllText($path)
        if (-not [string]::IsNullOrWhiteSpace($raw)) {
            $settings = ConvertFrom-WinToolJsonText -Text $raw
        }
    }
    Add-WinToolTerminalScheme -Settings $settings -Scheme $scheme | Out-Null
    Write-WinToolUtf8File -Path $path -Text ((ConvertTo-WinToolJsonText -Value $settings) + "`n")
    Write-WinToolLog -Message "Set the Windows Terminal color scheme to $($scheme.name)." -Level "ok"
}

function Invoke-WinToolStarshipPreset {
    param(
        [Parameter(Mandatory = $true)][string]$Preset
    )
    Sync-WinToolProcessPath
    $command = Get-Command -Name "starship" -ErrorAction SilentlyContinue
    if ($null -eq $command) {
        Write-WinToolLog -Message "Starship is not on PATH yet, so the preset was skipped." -Level "warn"
        return
    }
    $directory = Join-Path $env:USERPROFILE ".config"
    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    $destination = Join-Path $directory "starship.toml"
    & $command.Source preset $Preset -o $destination
    Write-WinToolLog -Message "Wrote the Starship preset to $destination." -Level "ok"
}

function Get-WinToolFontInstallStep {
    param(
        [Parameter(Mandatory = $true)]$Font
    )
    # Nerd Fonts come from the official ryanoasis/nerd-fonts release. Plain
    # fonts come from their own GitHub releases, or from winget only when the
    # id was checked in winget-pkgs (fonts.json keeps just those).
    $name = [string]$Font.name
    $wingetId = [string](Get-WinToolNote -Object $Font -Name "wingetId" -Default "")
    $asset = [string](Get-WinToolNote -Object $Font -Name "asset" -Default "")
    $github = Get-WinToolNote -Object $Font -Name "github"
    if (-not [string]::IsNullOrWhiteSpace($asset)) {
        $release = [string](Get-WinToolNote -Object $Font -Name "release" -Default "")
        if ([string]::IsNullOrWhiteSpace($release)) {
            $release = [string](Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "nerdFontsRelease" -Default "v3.5.1")
        }
        return @([pscustomobject]@{ Type = "font-download"; Label = ("Download " + $name); Release = $release; Asset = $asset; Face = [string]$Font.face })
    }
    if ($null -ne $github) {
        return @([pscustomobject]@{ Type = "font-download"; Label = ("Download " + $name); Repo = [string]$github.repo; AssetPattern = [string]$github.asset; Files = @($github.files); Face = [string]$Font.face })
    }
    if (-not [string]::IsNullOrWhiteSpace($wingetId)) {
        return @([pscustomobject]@{ Type = "winget"; Label = ("Install " + $name); WingetId = $wingetId; Scope = "" })
    }
    return @()
}

function Get-WinToolFontDownloadScript {
    param(
        [Parameter(Mandatory = $true)]$Step
    )
    # Two kinds of source: a Nerd Fonts release zip (fixed release and file
    # name), or the latest release of a font's own GitHub repository, found
    # by a file name pattern. Fonts go to the user's font folder and are
    # registered for the user, then loaded so Terminal sees them right away.
    $url = ""
    $release = [string](Get-WinToolNote -Object $Step -Name "Release" -Default "")
    $asset = [string](Get-WinToolNote -Object $Step -Name "Asset" -Default "")
    if (-not [string]::IsNullOrWhiteSpace($asset)) {
        $url = "https://github.com/ryanoasis/nerd-fonts/releases/download/" + $release + "/" + $asset
    }
    $repo = [string](Get-WinToolNote -Object $Step -Name "Repo" -Default "")
    $pattern = [string](Get-WinToolNote -Object $Step -Name "AssetPattern" -Default "")
    if ([string]::IsNullOrWhiteSpace($url) -and ([string]::IsNullOrWhiteSpace($repo) -or [string]::IsNullOrWhiteSpace($pattern))) {
        throw "The font download needs a Nerd Fonts asset or a GitHub repository and file pattern."
    }
    $files = @(Get-WinToolNote -Object $Step -Name "Files" -Default @())
    $fileText = (@($files | ForEach-Object { ConvertTo-WinToolSingleQuoted -Text ([string]$_) })) -join ", "
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('$ErrorActionPreference = "Stop"')
    $lines.Add('[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12')
    $lines.Add('Add-Type -AssemblyName System.IO.Compression.FileSystem')
    $lines.Add('$url = ' + (ConvertTo-WinToolSingleQuoted -Text $url))
    $lines.Add('$repo = ' + (ConvertTo-WinToolSingleQuoted -Text $repo))
    $lines.Add('$pattern = ' + (ConvertTo-WinToolSingleQuoted -Text $pattern))
    $lines.Add('$wanted = @(' + $fileText + ')')
    $body = @'
if ([string]::IsNullOrWhiteSpace($url)) {
    $latest = Invoke-RestMethod -Uri ("https://api.github.com/repos/" + $repo + "/releases/latest") -Headers @{ "User-Agent" = "WinTool" } -UseBasicParsing
    $match = @($latest.assets | Where-Object { [string]$_.name -like $pattern })
    if ($match.Count -eq 0) {
        throw ("The latest " + $repo + " release has no file named like " + $pattern + ".")
    }
    $url = [string]$match[0].browser_download_url
    Write-Output ("Downloading " + [string]$match[0].name + " from " + $repo + " " + [string]$latest.tag_name)
}
else {
    Write-Output ("Downloading " + $url)
}
$name = [IO.Path]::GetFileName(([uri]$url).AbsolutePath)
$zip = Join-Path $env:TEMP ("WinTool-" + $name)
$folder = Join-Path $env:TEMP ("WinTool-" + [IO.Path]::GetFileNameWithoutExtension($name))
Invoke-WebRequest -Uri $url -OutFile $zip -UseBasicParsing
if (Test-Path -LiteralPath $folder) { Remove-Item -LiteralPath $folder -Recurse -Force }
[IO.Compression.ZipFile]::ExtractToDirectory($zip, $folder)
$all = @(Get-ChildItem -LiteralPath $folder -Recurse -File | Where-Object { @(".ttf", ".otf", ".ttc") -contains $_.Extension.ToLowerInvariant() })
$picked = @{}
foreach ($file in $all) {
    $take = ($wanted.Count -eq 0)
    foreach ($want in $wanted) {
        if ($file.Name -like $want) { $take = $true }
    }
    if ($take -and -not $picked.ContainsKey($file.Name.ToLowerInvariant())) {
        $picked[$file.Name.ToLowerInvariant()] = $file
    }
}
if ($picked.Count -eq 0) {
    throw ("No font files were found in " + $name + ".")
}
if (-not ("WinToolFontLoader" -as [type])) {
    Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class WinToolFontLoader { [DllImport("gdi32.dll", CharSet = CharSet.Unicode)] public static extern int AddFontResource(string file); }'
}
$dest = Join-Path $env:LOCALAPPDATA "Microsoft\Windows\Fonts"
if (-not (Test-Path -LiteralPath $dest)) { New-Item -ItemType Directory -Path $dest -Force | Out-Null }
$key = "HKCU:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts"
if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force | Out-Null }
foreach ($file in $picked.Values) {
    $target = Join-Path $dest $file.Name
    Copy-Item -LiteralPath $file.FullName -Destination $target -Force
    $label = [IO.Path]::GetFileNameWithoutExtension($file.Name) + " (TrueType)"
    New-ItemProperty -LiteralPath $key -Name $label -Value $target -PropertyType String -Force | Out-Null
    $null = [WinToolFontLoader]::AddFontResource($target)
}
Remove-Item -LiteralPath $zip -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $folder -Recurse -Force -ErrorAction SilentlyContinue
Write-Output ("Installed " + $picked.Count + " font files from " + $name)
'@
    $lines.Add($body)
    return ($lines -join [Environment]::NewLine)
}

function Get-WinToolToolDownloadScript {
    param(
        [Parameter(Mandatory = $true)][string]$Url,
        [Parameter(Mandatory = $true)][string]$FileName
    )
    $text = @'
$ErrorActionPreference = "Stop"
$url = "URL"
$name = "FILENAME"
$dest = Join-Path $env:LOCALAPPDATA "WinTool\bin"
if (-not (Test-Path -LiteralPath $dest)) { New-Item -ItemType Directory -Path $dest -Force | Out-Null }
$path = Join-Path $dest $name
Invoke-WebRequest -Uri $url -OutFile $path -UseBasicParsing
Write-Output ("Downloaded " + $path)
'@
    return $text.Replace("URL", $Url).Replace("FILENAME", $FileName)
}

function Get-WinToolSimpleTerminalChoice {
    $catalog = Get-WinToolTerminalCatalog
    $simple = Get-WinToolNote -Object $catalog -Name "simple"
    return [pscustomobject]@{
        prompt = [string](Get-WinToolNote -Object $simple -Name "prompt" -Default "oh-my-posh")
        promptStyle = [string](Get-WinToolNote -Object $simple -Name "promptStyle" -Default "jandedobbeleer")
        fontId = [string](Get-WinToolNote -Object $simple -Name "fontId" -Default "cascadiacode-nf")
        schemeId = [string](Get-WinToolNote -Object $simple -Name "schemeId" -Default "wintool-night")
        terminalIcons = [bool](Get-WinToolNote -Object $simple -Name "terminalIcons" -Default $true)
        psReadLine = [bool](Get-WinToolNote -Object $simple -Name "psReadLine" -Default $true)
        zoxide = [bool](Get-WinToolNote -Object $simple -Name "zoxide" -Default $false)
        fzf = [bool](Get-WinToolNote -Object $simple -Name "fzf" -Default $false)
    }
}

function Get-WinToolTerminalSummary {
    param(
        [Parameter(Mandatory = $true)]$Selection
    )
    $plan = @(Get-WinToolTerminalPlan -Selection $Selection)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($step in $plan) {
        $lines.Add([string]$step.Label)
    }
    return $lines.ToArray()
}

function Get-WinToolTerminalPlan {
    param(
        [Parameter(Mandatory = $true)]$Selection
    )
    $catalog = Get-WinToolTerminalCatalog
    $promptId = [string](Get-WinToolNote -Object $Selection -Name "prompt" -Default "")
    if ([string]::IsNullOrWhiteSpace($promptId)) {
        $promptId = [string](Get-WinToolNote -Object $Selection -Name "Prompt" -Default "oh-my-posh")
    }
    $promptStyle = [string](Get-WinToolNote -Object $Selection -Name "promptStyle" -Default "")
    $fontId = [string](Get-WinToolNote -Object $Selection -Name "fontId" -Default "")
    if ([string]::IsNullOrWhiteSpace($fontId)) {
        $fontId = [string](Get-WinToolNote -Object $Selection -Name "FontId" -Default "")
    }
    $schemeId = [string](Get-WinToolNote -Object $Selection -Name "schemeId" -Default "")
    $icons = Get-WinToolNote -Object $Selection -Name "terminalIcons"
    if ($null -eq $icons) { $icons = $true }
    $psReadLine = Get-WinToolNote -Object $Selection -Name "psReadLine"
    if ($null -eq $psReadLine) { $psReadLine = $false }
    $zoxide = Get-WinToolNote -Object $Selection -Name "zoxide"
    if ($null -eq $zoxide) { $zoxide = $false }
    $fzf = Get-WinToolNote -Object $Selection -Name "fzf"
    if ($null -eq $fzf) { $fzf = $false }
    $wsl = Get-WinToolNote -Object $Selection -Name "wsl"
    if ($null -eq $wsl) { $wsl = $false }
    $zsh = Get-WinToolNote -Object $Selection -Name "zsh"
    if ($null -eq $zsh) { $zsh = $false }

    $prompt = $null
    foreach ($item in @(Get-WinToolNote -Object $catalog -Name "prompts" -Default @())) {
        if ([string]$item.id -eq $promptId) {
            $prompt = $item
            break
        }
    }
    if ($null -eq $prompt) {
        throw "Unknown terminal prompt '$promptId'."
    }
    $shellKind = [string](Get-WinToolNote -Object $prompt -Name "shell" -Default "powershell")
    if ($shellKind -like "wsl-*") {
        $wsl = $true
        $zsh = $true
    }

    $font = $null
    # Fonts added by the online refresh live in $script:WinToolExtraFont.
    $fontRows = @(Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "fonts" -Default @()) + @($script:WinToolExtraFont | Where-Object { $null -ne $_ })
    foreach ($item in $fontRows) {
        if ([string]$item.id -eq $fontId) {
            $font = $item
            break
        }
    }
    if ($null -eq $font) {
        throw "Unknown terminal font '$fontId'."
    }
    $scheme = $null
    foreach ($item in @(Get-WinToolNote -Object $catalog -Name "schemes" -Default @())) {
        if ([string]$item.id -eq $schemeId) {
            $scheme = $item
            break
        }
    }

    $components = Get-WinToolNote -Object $catalog -Name "components"
    $steps = New-Object System.Collections.Generic.List[object]
    [void]$steps.Add([pscustomobject]@{ Type = "winget"; Label = "Install Windows Terminal"; WingetId = [string]$components.windowsTerminal; Scope = "" })
    [void]$steps.Add([pscustomobject]@{ Type = "winget"; Label = "Install PowerShell 7"; WingetId = [string]$components.powerShell; Scope = "" })
    $promptWinget = [string](Get-WinToolNote -Object $prompt -Name "wingetId" -Default "")
    if (-not [string]::IsNullOrWhiteSpace($promptWinget)) {
        [void]$steps.Add([pscustomobject]@{ Type = "winget"; Label = ("Install " + [string]$prompt.name); WingetId = $promptWinget; Scope = "" })
    }
    foreach ($fontStep in @(Get-WinToolFontInstallStep -Font $font)) {
        [void]$steps.Add($fontStep)
    }
    [void]$steps.Add([pscustomobject]@{ Type = "font"; Label = ("Set the Windows Terminal font to " + [string]$font.name); Face = [string]$font.face; Match = [string]$font.match })
    if ($null -ne $scheme) {
        [void]$steps.Add([pscustomobject]@{ Type = "scheme"; Label = ("Set the Windows Terminal color scheme to " + [string]$scheme.name); SchemeId = [string]$scheme.id })
    }
    if ($promptId -eq "starship" -and -not [string]::IsNullOrWhiteSpace($promptStyle)) {
        [void]$steps.Add([pscustomobject]@{ Type = "starship-preset"; Label = ("Apply the Starship preset " + $promptStyle); Preset = $promptStyle })
    }
    if ($promptId -eq "powerline-go") {
        [void]$steps.Add([pscustomobject]@{ Type = "tool-download"; Label = "Download powerline-go"; Url = [string](Get-WinToolNote -Object $prompt -Name "downloadUrl" -Default ""); FileName = "powerline-go.exe" })
    }
    foreach ($extra in @(Get-WinToolNote -Object $catalog -Name "extras" -Default @())) {
        $extraId = [string]$extra.id
        $enabled = $false
        if ($extraId -eq "terminal-icons") { $enabled = [bool]$icons }
        elseif ($extraId -eq "psreadline") { $enabled = [bool]$psReadLine }
        elseif ($extraId -eq "zoxide") { $enabled = [bool]$zoxide }
        elseif ($extraId -eq "fzf") { $enabled = [bool]$fzf }
        if ($enabled -and [string]$extra.kind -eq "winget") {
            [void]$steps.Add([pscustomobject]@{ Type = "winget"; Label = ("Install " + [string]$extra.name); WingetId = [string]$extra.wingetId; Scope = "" })
        }
    }
    if ([bool]$icons) {
        [void]$steps.Add([pscustomobject]@{ Type = "module"; Label = "Install Terminal-Icons for Windows PowerShell"; Host = "powershell" })
        [void]$steps.Add([pscustomobject]@{ Type = "module"; Label = "Install Terminal-Icons for PowerShell 7"; Host = "pwsh" })
    }
    if ([bool]$psReadLine) {
        # 5.1 ships PSReadLine 2.0, too old for history predictions.
        [void]$steps.Add([pscustomobject]@{ Type = "module"; Label = "Update PSReadLine for Windows PowerShell"; Host = "powershell"; Module = "PSReadLine" })
    }
    [void]$steps.Add([pscustomobject]@{ Type = "profile"; Label = "Update PowerShell profiles"; Prompt = $promptId; PromptStyle = $promptStyle; TerminalIcons = [bool]$icons; PsReadLine = [bool]$psReadLine; Zoxide = [bool]$zoxide })
    if ([bool]$wsl) {
        $distro = [string](Get-WinToolNote -Object $Selection -Name "wslDistro" -Default "Ubuntu")
        $withShell = ([bool]$zsh -or $shellKind -like "wsl-*")
        foreach ($wslStep in @(Get-WinToolWslStep -Distro $distro -PromptId $promptId -PromptStyle $promptStyle -Font $font -Install $true -Shell $withShell)) {
            [void]$steps.Add($wslStep)
        }
    }
    return $steps.ToArray()
}
# endregion

# region src/Private/Wsl.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# WSL shell setup. It works on a distro that already exists: nothing is
# reinstalled, the Linux part runs as root through wsl.exe (no sudo password),
# and the default shell is changed with chsh as root.

function Get-WinToolWslDistroName {
    param($Step)
    $name = [string](Get-WinToolNote -Object $Step -Name "Distro" -Default "Ubuntu")
    if ([string]::IsNullOrWhiteSpace($name)) {
        $name = "Ubuntu"
    }
    if ($name -notmatch '^[A-Za-z0-9._-]+$') {
        throw "Unexpected WSL distro name '$name'."
    }
    return $name
}

function ConvertTo-WinToolShellWord {
    param(
        [AllowEmptyString()][string]$Text
    )
    # Values that reach bash: letters, digits, and . _ / - only.
    return ([string]$Text -replace '[^A-Za-z0-9._/-]', '')
}

function Get-WinToolWslSetupText {
    param(
        [Parameter(Mandatory = $true)]$Step
    )
    $bash = Get-WinToolPayloadText -Name "Wsl"
    $bash = $bash -replace "`r`n", "`n" -replace "`r", "`n"
    $variant = ConvertTo-WinToolShellWord -Text ([string](Get-WinToolNote -Object $Step -Name "Variant" -Default ""))
    $style = ConvertTo-WinToolShellWord -Text ([string](Get-WinToolNote -Object $Step -Name "PromptStyle" -Default ""))
    $omzTheme = ConvertTo-WinToolShellWord -Text ([string](Get-WinToolNote -Object $Step -Name "OmzTheme" -Default ""))
    if ([string]::IsNullOrWhiteSpace($omzTheme)) { $omzTheme = "robbyrussell" }
    $header = "export WINTOOL_SHELL_PROMPT='" + $variant + "'`nexport WINTOOL_PROMPT_STYLE='" + $style + "'`nexport WINTOOL_OMZ_THEME='" + $omzTheme + "'`n"
    if ($bash.StartsWith("#!")) {
        $cut = $bash.IndexOf("`n")
        return $bash.Substring(0, $cut + 1) + $header + $bash.Substring($cut + 1)
    }
    return $header + $bash
}

function Get-WinToolWslLookupText {
    return @'
$ErrorActionPreference = "Continue"
$env:WSL_UTF8 = "1"
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { $null = $_ }
function Get-WinToolWslEntry {
    param([string]$Name)
    foreach ($key in @(Get-ChildItem -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Lxss" -ErrorAction SilentlyContinue)) {
        $item = Get-ItemProperty -LiteralPath $key.PSPath -ErrorAction SilentlyContinue
        if ($null -ne $item -and [string]$item.DistributionName -eq $Name) {
            return $item
        }
    }
    return $null
}
function Write-WinToolWslOutput {
    process {
        $text = ([string]$_).Replace([string][char]0, "")
        if (-not [string]::IsNullOrWhiteSpace($text)) { Write-Output $text.TrimEnd() }
    }
}
$wsl = Join-Path $env:SystemRoot "System32\wsl.exe"
'@
}

function Get-WinToolWslInstallScript {
    param(
        [Parameter(Mandatory = $true)][string]$Distro
    )
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add((Get-WinToolWslLookupText))
    $lines.Add('$distro = ' + (ConvertTo-WinToolSingleQuoted -Text $Distro))
    $lines.Add(@'
if ($null -ne (Get-WinToolWslEntry -Name $distro)) {
    Write-Output ("WSL already has " + $distro + ", so it is kept as it is.")
    exit 0
}
if (-not (Test-Path -LiteralPath $wsl)) {
    Write-Output "wsl.exe was not found. WSL needs Windows 10 2004 or later."
    exit 1
}
& $wsl --install -d $distro --no-launch 2>&1 | Write-WinToolWslOutput
$code = $LASTEXITCODE
if ($code -eq 0) {
    Write-Output ("Open " + $distro + " once from the Start menu to create your Linux user, then run the shell setup again.")
}
exit $code
'@)
    return ($lines -join [Environment]::NewLine)
}

function Get-WinToolWslShellScript {
    param(
        [Parameter(Mandatory = $true)][string]$Distro,
        [Parameter(Mandatory = $true)][string]$ScriptPath
    )
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add((Get-WinToolWslLookupText))
    $lines.Add('$distro = ' + (ConvertTo-WinToolSingleQuoted -Text $Distro))
    $lines.Add('$script = ' + (ConvertTo-WinToolSingleQuoted -Text $ScriptPath))
    $lines.Add(@'
$entry = Get-WinToolWslEntry -Name $distro
if ($null -eq $entry) {
    Write-Output ("WSL has no distro named " + $distro + ". If it was just installed, open it once from the Start menu to create your Linux user, then run the shell setup again.")
    exit 3
}
if (-not (Test-Path -LiteralPath $wsl)) {
    Write-Output "wsl.exe was not found."
    exit 1
}
$uid = 0
if ($null -ne $entry.PSObject.Properties["DefaultUid"]) { $uid = [int64]$entry.DefaultUid }
$unix = ""
$converted = & $wsl -d $distro -u root -- wslpath -a $script 2>$null
foreach ($line in @($converted)) {
    $text = ([string]$line).Replace([string][char]0, "").Trim()
    if ($text.StartsWith("/")) { $unix = $text }
}
if ([string]::IsNullOrWhiteSpace($unix)) {
    $unix = "/mnt/" + $script.Substring(0, 1).ToLowerInvariant() + $script.Substring(2).Replace("\", "/")
}
Write-Output ("Running the shell setup in " + $distro + " as root for uid " + $uid + ".")
& $wsl -d $distro -u root -- env ("WINTOOL_UID=" + $uid) bash $unix 2>&1 | Write-WinToolWslOutput
exit $LASTEXITCODE
'@)
    return ($lines -join [Environment]::NewLine)
}

function Set-WinToolWslProfileFont {
    param(
        [Parameter(Mandatory = $true)]$Settings,
        [Parameter(Mandatory = $true)][string]$Distro,
        [Parameter(Mandatory = $true)][string]$Face
    )
    # Sets the font on the distro's own Terminal profile, so an older
    # per-profile font cannot hide the Nerd Font. Returns how many changed.
    $profiles = Get-WinToolNote -Object $Settings -Name "profiles"
    $list = @(Get-WinToolNote -Object $profiles -Name "list" -Default @())
    $count = 0
    foreach ($item in $list) {
        $name = [string](Get-WinToolNote -Object $item -Name "name" -Default "")
        $source = [string](Get-WinToolNote -Object $item -Name "source" -Default "")
        $isWsl = $source -match '(?i)wsl'
        if (-not ($name -eq $Distro -or ($isWsl -and $name.StartsWith($Distro, [System.StringComparison]::OrdinalIgnoreCase)))) {
            continue
        }
        $font = Get-WinToolNote -Object $item -Name "font"
        if ($null -eq $font) {
            $item | Add-Member -NotePropertyName "font" -NotePropertyValue ([pscustomobject]@{ face = $Face }) -Force
        }
        elseif ($null -eq $font.PSObject.Properties["face"]) {
            $font | Add-Member -NotePropertyName "face" -NotePropertyValue $Face
        }
        else {
            $font.face = $Face
        }
        if ($null -ne $item.PSObject.Properties["fontFace"]) {
            $item.PSObject.Properties.Remove("fontFace")
        }
        $count++
    }
    return $count
}

function Invoke-WinToolWslTerminalProfile {
    param(
        [Parameter(Mandatory = $true)][string]$Distro,
        [string]$Face,
        [string]$Match
    )
    if ([string]::IsNullOrWhiteSpace($Face)) {
        return
    }
    $chosen = Resolve-WinToolInstalledFontFace -Face $Face -Match $Match
    if ($null -eq $chosen) {
        return
    }
    $path = Get-WinToolTerminalSettingsPath
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) {
        Write-WinToolLog -Message "Windows Terminal settings were not found, so the $Distro profile font was not set." -Level "warn"
        return
    }
    $raw = [System.IO.File]::ReadAllText($path)
    if ([string]::IsNullOrWhiteSpace($raw)) {
        Write-WinToolLog -Message "Windows Terminal settings are empty, so the $Distro profile font was not set." -Level "warn"
        return
    }
    $settings = ConvertFrom-WinToolJsonText -Text $raw
    $count = Set-WinToolWslProfileFont -Settings $settings -Distro $Distro -Face $chosen
    if ($count -eq 0) {
        Write-WinToolLog -Message "Windows Terminal has no $Distro profile yet. It will use the default font, $chosen, when it appears." -Level "info"
        return
    }
    Write-WinToolUtf8File -Path $path -Text ((ConvertTo-WinToolJsonText -Value $settings) + "`n")
    Write-WinToolLog -Message "Set the $Distro profile font in Windows Terminal to $chosen." -Level "ok"
}

function Get-WinToolWslStep {
    param(
        [string]$Distro = "Ubuntu",
        [string]$PromptId = "oh-my-zsh",
        [string]$PromptStyle = "",
        $Font,
        [bool]$Install = $true,
        [bool]$Shell = $true
    )
    $steps = New-Object System.Collections.Generic.List[object]
    if ($Install) {
        [void]$steps.Add([pscustomobject]@{ Type = "wsl-install"; Label = "Install WSL with $Distro (kept if it already exists)"; Distro = $Distro })
    }
    if ($Shell) {
        $label = "Install zsh and Oh My Zsh in $Distro"
        if ($PromptId -eq "tide") { $label = "Install Fish and Tide in $Distro" }
        elseif ($PromptId -eq "powerlevel10k") { $label = "Install Powerlevel10k in $Distro" }
        elseif ($PromptId -eq "pure") { $label = "Install Pure in $Distro" }
        elseif ($PromptId -eq "spaceship") { $label = "Install Spaceship in $Distro" }
        elseif ($PromptId -eq "oh-my-zsh") { $label = "Install the Oh My Zsh theme in $Distro" }
        elseif ($PromptId -eq "oh-my-posh") { $label = "Install zsh and Oh My Posh in $Distro" }
        elseif ($PromptId -eq "starship") { $label = "Install zsh and Starship in $Distro" }
        [void]$steps.Add([pscustomobject]@{ Type = "wsl-shell"; Label = $label; Distro = $Distro; Variant = $PromptId; PromptStyle = $PromptStyle; OmzTheme = $PromptStyle })
    }
    if ($null -ne $Font) {
        [void]$steps.Add([pscustomobject]@{ Type = "wsl-profile"; Label = ("Use " + [string]$Font.name + " in the $Distro Terminal profile"); Distro = $Distro; Face = [string]$Font.face; Match = [string]$Font.match })
    }
    return $steps.ToArray()
}

function Get-WinToolWslShellPlan {
    param(
        [string]$Distro = "Ubuntu",
        [string]$PromptId = "oh-my-posh",
        [string]$PromptStyle = "jandedobbeleer",
        [string]$FontId = "cascadiacode-nf",
        [switch]$Install
    )
    # Only the WSL part of terminal setup: no Windows packages, profiles, or
    # color schemes. Without -Install an existing distro is required.
    $font = $null
    if (-not [string]::IsNullOrWhiteSpace($FontId)) {
        foreach ($item in @(Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "fonts" -Default @())) {
            if ([string]$item.id -eq $FontId) {
                $font = $item
                break
            }
        }
        if ($null -eq $font) {
            throw "Unknown terminal font '$FontId'."
        }
    }
    return @(Get-WinToolWslStep -Distro $Distro -PromptId $PromptId -PromptStyle $PromptStyle -Font $font -Install ([bool]$Install) -Shell $true)
}

function Invoke-WinToolWslShellSetup {
    param(
        [string]$Distro = "Ubuntu",
        [string]$PromptId = "oh-my-posh",
        [string]$PromptStyle = "jandedobbeleer",
        [string]$FontId = "cascadiacode-nf",
        [switch]$Install
    )
    $plan = @(Get-WinToolWslShellPlan -Distro $Distro -PromptId $PromptId -PromptStyle $PromptStyle -FontId $FontId -Install:$Install)
    Invoke-WinToolPlan -Step $plan
}
# endregion

# region src/Private/Updates.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Resolve-WinToolGpuVendor {
    param(
        [string]$Name,
        $Vendor
    )
    if ([string]::IsNullOrWhiteSpace($Name)) {
        return $null
    }
    foreach ($item in @($Vendor)) {
        foreach ($token in @(Get-WinToolNote -Object $item -Name "match" -Default @())) {
            if ($Name.IndexOf([string]$token, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                return $item
            }
        }
    }
    return $null
}

function Get-WinToolGpuInfo {
    if (-not (Test-WinToolWindows)) {
        return @()
    }
    $rows = New-Object System.Collections.Generic.List[object]
    try {
        $items = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop)
    }
    catch {
        return @()
    }
    foreach ($item in $items) {
        if ([string]::IsNullOrWhiteSpace([string]$item.Name)) {
            continue
        }
        $rows.Add([pscustomobject]@{
            Name = [string]$item.Name
            DriverVersion = [string]$item.DriverVersion
        })
    }
    return $rows.ToArray()
}

function Get-WinToolUpdateSearchScript {
    $scriptText = @'
param($Sync, $Criteria)
$ErrorActionPreference = "Stop"
try {
    $session = New-Object -ComObject Microsoft.Update.Session
    $searcher = $session.CreateUpdateSearcher()
    $result = $searcher.Search($Criteria)
    $lines = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -lt $result.Updates.Count; $i++) {
        $update = $result.Updates.Item($i)
        $isDriver = $false
        foreach ($category in @($update.Categories)) {
            if ([string]$category.Name -match "Driver") {
                $isDriver = $true
            }
        }
        $kind = "update"
        if ($isDriver) { $kind = "driver" }
        $title = ([string]$update.Title) -replace "[\r\n\t]", " "
        $lines.Add($kind + "`t" + $title)
    }
    $Sync.Lines = $lines.ToArray()
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolUpdateInstallScript {
    $scriptText = @'
param($Sync, $Criteria, $TitleText)
$ErrorActionPreference = "Stop"
try {
    $wanted = @{}
    foreach ($title in @(([string]$TitleText) -split "`n")) {
        if (-not [string]::IsNullOrWhiteSpace([string]$title)) {
            $wanted[[string]$title] = $true
        }
    }
    $session = New-Object -ComObject Microsoft.Update.Session
    $searcher = $session.CreateUpdateSearcher()
    $result = $searcher.Search($Criteria)
    $toInstall = New-Object -ComObject Microsoft.Update.UpdateColl
    for ($i = 0; $i -lt $result.Updates.Count; $i++) {
        $update = $result.Updates.Item($i)
        if ($wanted.ContainsKey([string]$update.Title)) {
            if (-not $update.EulaAccepted) {
                $update.EulaAccepted = $true
            }
            [void]$toInstall.Add($update)
        }
    }
    if ($toInstall.Count -eq 0) {
        $Sync.Ok = $true
        $Sync.Count = 0
        $Sync.Reboot = $false
        $Sync.Done = $true
        return
    }
    $downloader = $session.CreateUpdateDownloader()
    $downloader.Updates = $toInstall
    [void]$downloader.Download()
    $installer = $session.CreateUpdateInstaller()
    $installer.Updates = $toInstall
    $installResult = $installer.Install()
    $Sync.Ok = $true
    $Sync.Count = [int]$toInstall.Count
    $Sync.Reboot = [bool]$installResult.RebootRequired
    $Sync.ResultCode = [int]$installResult.ResultCode
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Open-WinToolUri {
    param(
        [Parameter(Mandatory = $true)][string]$Uri
    )
    Start-Process -FilePath $Uri | Out-Null
}
# endregion

# region src/Private/UpdateModes.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# Windows Update modes from data/updates.json. A mode is a set of policy
# values under HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate plus a
# startup type for the update services. Applying a mode first clears every
# policy value any mode knows about, so switching modes never stacks, and
# "Default" is the revert.

$script:WinToolUpdatePolicyRoot = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
$script:WinToolServiceStartTypes = @("Manual", "Automatic", "AutomaticDelayed", "Disabled")

function Get-WinToolUpdateMode {
    param(
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    return @(Get-WinToolNote -Object $Catalog -Name "modes" -Default @())
}

function Find-WinToolUpdateMode {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    foreach ($mode in (Get-WinToolUpdateMode -Catalog $Catalog)) {
        if ([string]$mode.id -eq $Id) {
            return $mode
        }
    }
    return $null
}

function Get-WinToolUpdatePolicyKey {
    param(
        [Parameter(Mandatory = $true)]$Policy
    )
    return ([string]$Policy.path + "|" + [string]$Policy.name).ToLowerInvariant()
}

function Get-WinToolManagedUpdatePolicy {
    param(
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    # Every policy value any mode sets, once each.
    $seen = @{}
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($mode in (Get-WinToolUpdateMode -Catalog $Catalog)) {
        foreach ($policy in @(Get-WinToolNote -Object $mode -Name "policies" -Default @())) {
            $key = Get-WinToolUpdatePolicyKey -Policy $policy
            if (-not $seen.ContainsKey($key)) {
                $seen[$key] = $true
                $list.Add([pscustomobject]@{ path = [string]$policy.path; name = [string]$policy.name })
            }
        }
    }
    return $list.ToArray()
}

function Get-WinToolUpdateModeChange {
    param(
        [Parameter(Mandatory = $true)][string]$ModeId,
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    $mode = Find-WinToolUpdateMode -Id $ModeId -Catalog $Catalog
    if ($null -eq $mode) {
        throw "Unknown update mode '$ModeId'."
    }
    $set = New-Object System.Collections.Generic.List[object]
    foreach ($policy in @(Get-WinToolNote -Object $mode -Name "policies" -Default @())) {
        $set.Add([pscustomobject]@{ path = [string]$policy.path; name = [string]$policy.name; value = [int]$policy.value })
    }
    $services = New-Object System.Collections.Generic.List[object]
    foreach ($service in @(Get-WinToolNote -Object $mode -Name "services" -Default @())) {
        $services.Add([pscustomobject]@{
            name = [string]$service.name
            startupType = [string]$service.startupType
            stop = [bool](Get-WinToolNote -Object $service -Name "stop" -Default $false)
        })
    }
    return [pscustomobject]@{
        Mode = [string]$mode.id
        Name = [string]$mode.name
        Remove = @(Get-WinToolManagedUpdatePolicy -Catalog $Catalog)
        Set = $set.ToArray()
        Services = $services.ToArray()
    }
}

function Get-WinToolUpdateModeScript {
    param(
        [Parameter(Mandatory = $true)][string]$ModeId,
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    $change = Get-WinToolUpdateModeChange -ModeId $ModeId -Catalog $Catalog
    $json = ConvertTo-Json -InputObject $change -Depth 6 -Compress
    $body = @'
$ErrorActionPreference = "Stop"
$change = ConvertFrom-Json -InputObject '__CHANGE__'
$failed = 0
foreach ($item in @($change.Remove)) {
    if ((Test-Path -LiteralPath $item.path) -and ($null -ne (Get-ItemProperty -LiteralPath $item.path -Name $item.name -ErrorAction SilentlyContinue))) {
        Remove-ItemProperty -LiteralPath $item.path -Name $item.name
        Write-Output ("Removed policy " + $item.name)
    }
}
foreach ($item in @($change.Set)) {
    if (-not (Test-Path -LiteralPath $item.path)) {
        New-Item -Path $item.path -Force | Out-Null
    }
    New-ItemProperty -LiteralPath $item.path -Name $item.name -Value ([int]$item.value) -PropertyType DWord -Force | Out-Null
    Write-Output ("Set policy {0} = {1}" -f $item.name, $item.value)
}
$startNames = @{ Manual = "demand"; Automatic = "auto"; AutomaticDelayed = "delayed-auto"; Disabled = "disabled" }
foreach ($service in @($change.Services)) {
    if ($null -eq (Get-Service -Name $service.name -ErrorAction SilentlyContinue)) {
        Write-Output ("Service {0} is not on this PC." -f $service.name)
        continue
    }
    if ($service.stop) {
        try {
            Stop-Service -Name $service.name -Force -ErrorAction Stop
            Write-Output ("Stopped " + $service.name)
        }
        catch {
            Write-Output ("Could not stop {0}: {1}" -f $service.name, $_.Exception.Message)
        }
    }
    $output = & sc.exe config $service.name start= $startNames[[string]$service.startupType] 2>&1
    if ($LASTEXITCODE -eq 0) {
        Write-Output ("{0} startup is now {1}" -f $service.name, $service.startupType)
    }
    else {
        $failed++
        Write-Output ("Could not change {0}: {1}" -f $service.name, (($output | Out-String).Trim()))
    }
}
Write-Output ("Update mode is now: " + $change.Name)
if ($failed -gt 0) {
    exit 2
}
'@
    return $body.Replace("__CHANGE__", $json.Replace("'", "''"))
}

function Get-WinToolUpdateModePlan {
    param(
        [Parameter(Mandatory = $true)][string]$ModeId,
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    $mode = Find-WinToolUpdateMode -Id $ModeId -Catalog $Catalog
    if ($null -eq $mode) {
        throw "Unknown update mode '$ModeId'."
    }
    return @([pscustomobject]@{
        Type = "inline-script"
        Label = "Set Windows Update to: " + [string]$mode.name
        Name = "update-mode"
        Text = (Get-WinToolUpdateModeScript -ModeId $ModeId -Catalog $Catalog)
    })
}

function Get-WinToolUpdateModeSnapshot {
    param(
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    $values = @{}
    foreach ($policy in (Get-WinToolManagedUpdatePolicy -Catalog $Catalog)) {
        $item = Get-ItemProperty -LiteralPath $policy.path -Name $policy.name -ErrorAction SilentlyContinue
        if ($null -ne $item) {
            $values[(Get-WinToolUpdatePolicyKey -Policy $policy)] = [int]$item.($policy.name)
        }
    }
    $services = @{}
    foreach ($name in @("wuauserv", "UsoSvc")) {
        $service = Get-Service -Name $name -ErrorAction SilentlyContinue
        if ($null -ne $service) {
            $services[$name] = [string]$service.StartType
        }
    }
    return [pscustomobject]@{ Values = $values; Services = $services }
}

function Resolve-WinToolUpdateMode {
    param(
        [hashtable]$Values = @{},
        [hashtable]$Services = @{},
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    # The current mode is the one whose policies are all in place and whose
    # disabled services really are disabled. Leftover values from another
    # tool show as "custom" so nothing gets mislabeled as Default.
    foreach ($mode in (Get-WinToolUpdateMode -Catalog $Catalog)) {
        $policies = @(Get-WinToolNote -Object $mode -Name "policies" -Default @())
        if ($policies.Count -eq 0) {
            continue
        }
        $match = $true
        foreach ($policy in $policies) {
            $key = Get-WinToolUpdatePolicyKey -Policy $policy
            if (-not $Values.ContainsKey($key) -or [int]$Values[$key] -ne [int]$policy.value) {
                $match = $false
            }
        }
        if ($match -and $Values.Count -eq $policies.Count) {
            return [string]$mode.id
        }
    }
    foreach ($name in @($Services.Keys)) {
        if ([string]$Services[$name] -eq "Disabled") {
            return "custom"
        }
    }
    if ($Values.Count -gt 0) {
        return "custom"
    }
    return "default"
}

function Test-WinToolUpdateModeCatalog {
    param(
        [Parameter(Mandatory = $true)]$Catalog,
        $Errors
    )
    $modes = @(Get-WinToolUpdateMode -Catalog $Catalog)
    $ids = @{}
    foreach ($mode in $modes) {
        $id = [string](Get-WinToolNote -Object $mode -Name "id" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or $ids.ContainsKey($id)) {
            $Errors.Add("An update mode has a missing or repeated id '$id'.")
            continue
        }
        $ids[$id] = $true
        foreach ($field in @("name", "description")) {
            if ([string]::IsNullOrWhiteSpace([string](Get-WinToolNote -Object $mode -Name $field -Default ""))) {
                $Errors.Add("Update mode '$id' needs a $field.")
            }
        }
        foreach ($policy in @(Get-WinToolNote -Object $mode -Name "policies" -Default @())) {
            if (-not ([string]$policy.path).StartsWith($script:WinToolUpdatePolicyRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
                $Errors.Add("Update mode '$id' writes outside the Windows Update policy key.")
            }
            if ([string]$policy.name -notmatch '^[A-Za-z]+$') {
                $Errors.Add("Update mode '$id' has an invalid policy name '$([string]$policy.name)'.")
            }
        }
        foreach ($service in @(Get-WinToolNote -Object $mode -Name "services" -Default @())) {
            if ($script:WinToolServiceStartTypes -notcontains [string]$service.startupType) {
                $Errors.Add("Update mode '$id' has an unknown startup type for $([string]$service.name).")
            }
            if ([string]$service.name -notmatch '^[A-Za-z]+$') {
                $Errors.Add("Update mode '$id' has an invalid service name.")
            }
        }
    }
    $default = Find-WinToolUpdateMode -Id "default" -Catalog $Catalog
    if ($null -eq $default) {
        $Errors.Add("updates.json needs a 'default' mode to revert to.")
    }
    elseif (@(Get-WinToolNote -Object $default -Name "policies" -Default @()).Count -ne 0) {
        $Errors.Add("The default update mode must not set policies.")
    }
}
# endregion

# region src/Private/System.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# DNS servers per network adapter and the Ultimate Performance power plan,
# both from data/system.json. Changes run as Windows PowerShell scripts through
# the plan runner so they are logged and never block the window.

function Get-WinToolSystemCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "System"))
}

function Get-WinToolDnsProvider {
    param(
        $Catalog = (Get-WinToolSystemCatalog)
    )
    return @(Get-WinToolNote -Object $Catalog -Name "dns" -Default @())
}

function Find-WinToolDnsProvider {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Catalog = (Get-WinToolSystemCatalog)
    )
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $Catalog)) {
        if ([string]$provider.id -eq $Id) {
            return $provider
        }
    }
    return $null
}

function Get-WinToolDnsServerList {
    param(
        [Parameter(Mandatory = $true)]$Provider,
        [bool]$IncludeIpv6 = $true
    )
    $list = New-Object System.Collections.Generic.List[string]
    foreach ($address in @(Get-WinToolNote -Object $Provider -Name "ipv4" -Default @())) {
        $list.Add([string]$address)
    }
    if ($IncludeIpv6) {
        foreach ($address in @(Get-WinToolNote -Object $Provider -Name "ipv6" -Default @())) {
            $list.Add([string]$address)
        }
    }
    return $list.ToArray()
}

function Resolve-WinToolDnsProvider {
    param(
        [string[]]$Server = @(),
        $Catalog = (Get-WinToolSystemCatalog)
    )
    # Name the provider when every IPv4 server an adapter uses belongs to it.
    $ipv4 = @($Server | Where-Object { [string]$_ -match '^\d+\.\d+\.\d+\.\d+$' })
    if ($ipv4.Count -eq 0) {
        return $null
    }
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $Catalog)) {
        $known = @(Get-WinToolNote -Object $provider -Name "ipv4" -Default @())
        if ($known.Count -eq 0) {
            continue
        }
        $all = $true
        foreach ($address in $ipv4) {
            if ($known -notcontains [string]$address) {
                $all = $false
            }
        }
        if ($all) {
            return $provider
        }
    }
    return $null
}

function Get-WinToolDnsAdapter {
    if (-not (Test-WinToolWindows)) {
        return @()
    }
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($adapter in @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { [string]$_.Status -eq "Up" } | Sort-Object -Property Name)) {
        $servers = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @(Get-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -ErrorAction SilentlyContinue)) {
            foreach ($address in @($entry.ServerAddresses)) {
                $servers.Add([string]$address)
            }
        }
        $list.Add([pscustomobject]@{
            Index = [int]$adapter.ifIndex
            Name = [string]$adapter.Name
            Description = [string]$adapter.InterfaceDescription
            Servers = $servers.ToArray()
        })
    }
    return $list.ToArray()
}

function Format-WinToolDnsSummary {
    param(
        [Parameter(Mandatory = $true)]$Adapter,
        $Catalog = (Get-WinToolSystemCatalog)
    )
    $servers = @($Adapter.Servers)
    if ($servers.Count -eq 0) {
        return ("{0}: no DNS servers reported" -f [string]$Adapter.Name)
    }
    $text = "{0}: {1}" -f [string]$Adapter.Name, ($servers -join ", ")
    $provider = Resolve-WinToolDnsProvider -Server $servers -Catalog $Catalog
    if ($null -ne $provider) {
        $text += "  (" + [string]$provider.name + ")"
    }
    return $text
}

function ConvertTo-WinToolSingleQuoted {
    param(
        [AllowEmptyString()][string]$Text
    )
    return "'" + $Text.Replace("'", "''") + "'"
}

function Get-WinToolDnsScript {
    param(
        [Parameter(Mandatory = $true)][int[]]$InterfaceIndex,
        [Parameter(Mandatory = $true)]$Provider,
        [bool]$IncludeIpv6 = $true
    )
    $servers = @(Get-WinToolDnsServerList -Provider $Provider -IncludeIpv6 $IncludeIpv6)
    foreach ($address in $servers) {
        $parsed = $null
        if (-not [System.Net.IPAddress]::TryParse([string]$address, [ref]$parsed)) {
            throw "DNS provider '$([string]$Provider.id)' has an invalid address '$address'."
        }
    }
    $indexText = (@($InterfaceIndex | ForEach-Object { [string][int]$_ })) -join ", "
    $serverText = (@($servers | ForEach-Object { ConvertTo-WinToolSingleQuoted -Text ([string]$_) })) -join ", "
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('$ErrorActionPreference = "Stop"')
    $lines.Add('$failed = 0')
    $lines.Add('$servers = @(' + $serverText + ')')
    $lines.Add('foreach ($index in @(' + $indexText + ')) {')
    $lines.Add('    $name = [string](Get-NetAdapter -InterfaceIndex $index).Name')
    $lines.Add('    try {')
    $lines.Add('        if ($servers.Count -eq 0) {')
    $lines.Add('            Set-DnsClientServerAddress -InterfaceIndex $index -ResetServerAddresses')
    $lines.Add('            Write-Output ($name + ": DNS is automatic again")')
    $lines.Add('        }')
    $lines.Add('        else {')
    $lines.Add('            Set-DnsClientServerAddress -InterfaceIndex $index -ServerAddresses $servers')
    $lines.Add('            Write-Output ($name + ": DNS set to " + ($servers -join ", "))')
    $lines.Add('        }')
    $lines.Add('    }')
    $lines.Add('    catch {')
    $lines.Add('        $failed++')
    $lines.Add('        Write-Output ($name + ": " + $_.Exception.Message)')
    $lines.Add('    }')
    $lines.Add('}')
    $lines.Add('Clear-DnsClientCache')
    $lines.Add('if ($failed -gt 0) { exit 2 }')
    return ($lines -join [Environment]::NewLine)
}

function Get-WinToolDnsPlan {
    param(
        [Parameter(Mandatory = $true)]$Adapter,
        [Parameter(Mandatory = $true)]$Provider,
        [bool]$IncludeIpv6 = $true
    )
    $adapters = @($Adapter)
    if ($adapters.Count -eq 0) {
        throw "Pick a network adapter first."
    }
    $names = (@($adapters | ForEach-Object { [string]$_.Name })) -join ", "
    return @([pscustomobject]@{
        Type = "inline-script"
        Label = ("Set DNS to {0} on {1}" -f [string]$Provider.name, $names)
        Name = "dns"
        Text = (Get-WinToolDnsScript -InterfaceIndex @($adapters | ForEach-Object { [int]$_.Index }) -Provider $Provider -IncludeIpv6 $IncludeIpv6)
    })
}

function ConvertFrom-WinToolPowerList {
    param(
        [string]$Text
    )
    # powercfg /list is translated, so read only the GUID, the name in
    # parentheses, and the trailing * that marks the active plan.
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($line in @($Text -split "`r?`n")) {
        $match = [regex]::Match($line, '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s*\((.*)\)\s*(\*?)\s*$')
        if ($match.Success) {
            $list.Add([pscustomobject]@{
                Guid = $match.Groups[1].Value.ToLowerInvariant()
                Name = $match.Groups[2].Value
                Active = ($match.Groups[3].Value -eq "*")
            })
        }
    }
    return $list.ToArray()
}

function Get-WinToolPowerPlanState {
    param(
        $Scheme = @(),
        $Catalog = (Get-WinToolSystemCatalog)
    )
    $plan = Get-WinToolNote -Object $Catalog -Name "powerPlan"
    $copy = ([string]$plan.copyGuid).ToLowerInvariant()
    $base = ([string]$plan.baseGuid).ToLowerInvariant()
    $state = [pscustomobject]@{ Added = $false; BuiltIn = $false; Active = $false }
    foreach ($item in @($Scheme)) {
        if ([string]$item.Guid -eq $copy) {
            $state.Added = $true
            if ($item.Active) { $state.Active = $true }
        }
        if ([string]$item.Guid -eq $base) {
            $state.BuiltIn = $true
            if ($item.Active) { $state.Active = $true }
        }
    }
    return $state
}

function Format-WinToolPowerPlanStatus {
    param(
        [Parameter(Mandatory = $true)]$State,
        [string]$Name = "Ultimate Performance"
    )
    if ($State.Added) {
        if ($State.Active) { return "$Name is added and active." }
        return "$Name is added but another plan is active."
    }
    if ($State.BuiltIn) {
        if ($State.Active) { return "$Name is built into this Windows and active." }
        return "$Name is built into this Windows. Adding it switches to it."
    }
    return "$Name is not on this PC."
}

function Get-WinToolPowerPlanScript {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("add", "remove")][string]$Action,
        $Catalog = (Get-WinToolSystemCatalog)
    )
    $plan = Get-WinToolNote -Object $Catalog -Name "powerPlan"
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('$base = ' + (ConvertTo-WinToolSingleQuoted -Text ([string]$plan.baseGuid)))
    $lines.Add('$copy = ' + (ConvertTo-WinToolSingleQuoted -Text ([string]$plan.copyGuid)))
    $lines.Add('$fallback = ' + (ConvertTo-WinToolSingleQuoted -Text ([string]$plan.fallbackGuid)))
    $lines.Add('$list = (& powercfg.exe /list | Out-String)')
    if ($Action -eq "add") {
        $lines.Add('if ($list -match $copy) {')
        $lines.Add('    $target = $copy')
        $lines.Add('}')
        $lines.Add('elseif ($list -match $base) {')
        $lines.Add('    $target = $base')
        $lines.Add('}')
        $lines.Add('else {')
        $lines.Add('    & powercfg.exe -duplicatescheme $base $copy')
        $lines.Add('    if ($LASTEXITCODE -ne 0) {')
        $lines.Add('        Write-Output "Windows did not allow the Ultimate Performance plan on this PC. Some laptops with Modern Standby block it."')
        $lines.Add('        exit 2')
        $lines.Add('    }')
        $lines.Add('    $target = $copy')
        $lines.Add('    Write-Output "Added the Ultimate Performance plan."')
        $lines.Add('}')
        $lines.Add('& powercfg.exe -setactive $target')
        $lines.Add('if ($LASTEXITCODE -ne 0) { exit 2 }')
        $lines.Add('Write-Output "Ultimate Performance is now the active plan."')
    }
    else {
        $lines.Add('if ($list -notmatch $copy) {')
        $lines.Add('    Write-Output "WinTool did not add an Ultimate Performance plan, so there is nothing to remove."')
        $lines.Add('    if ($list -match $base) { Write-Output "The built-in copy stays. Pick another plan in Control Panel if you want to stop using it." }')
        $lines.Add('    exit 0')
        $lines.Add('}')
        $lines.Add('$active = (& powercfg.exe /getactivescheme | Out-String)')
        $lines.Add('if ($active -match $copy) {')
        $lines.Add('    & powercfg.exe -setactive $fallback')
        $lines.Add('    Write-Output "Switched back to the Balanced plan."')
        $lines.Add('}')
        $lines.Add('& powercfg.exe -delete $copy')
        $lines.Add('if ($LASTEXITCODE -ne 0) { exit 2 }')
        $lines.Add('Write-Output "Removed the Ultimate Performance plan."')
    }
    return ($lines -join [Environment]::NewLine)
}

function Get-WinToolPowerPlanPlan {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("add", "remove")][string]$Action,
        $Catalog = (Get-WinToolSystemCatalog)
    )
    $label = "Add the Ultimate Performance power plan"
    if ($Action -eq "remove") {
        $label = "Remove the Ultimate Performance power plan"
    }
    return @([pscustomobject]@{
        Type = "inline-script"
        Label = $label
        Name = "power-plan"
        Text = (Get-WinToolPowerPlanScript -Action $Action -Catalog $Catalog)
    })
}

function Test-WinToolSystemCatalog {
    param(
        [Parameter(Mandatory = $true)]$Catalog,
        $Errors
    )
    if ([int](Get-WinToolNote -Object $Catalog -Name "schemaVersion" -Default 0) -ne 1) {
        $Errors.Add("system.json schemaVersion must be 1.")
    }
    $ids = @{}
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $Catalog)) {
        $id = [string](Get-WinToolNote -Object $provider -Name "id" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or $ids.ContainsKey($id)) {
            $Errors.Add("A DNS provider has a missing or repeated id '$id'.")
            continue
        }
        $ids[$id] = $true
        foreach ($family in @("ipv4", "ipv6")) {
            $expected = [System.Net.Sockets.AddressFamily]::InterNetwork
            if ($family -eq "ipv6") {
                $expected = [System.Net.Sockets.AddressFamily]::InterNetworkV6
            }
            foreach ($address in @(Get-WinToolNote -Object $provider -Name $family -Default @())) {
                $parsed = $null
                if (-not [System.Net.IPAddress]::TryParse([string]$address, [ref]$parsed) -or $parsed.AddressFamily -ne $expected) {
                    $Errors.Add("DNS provider '$id' has an invalid $family address '$address'.")
                }
            }
        }
    }
    if (-not $ids.ContainsKey("dhcp")) {
        $Errors.Add("system.json needs a 'dhcp' DNS choice to go back to automatic.")
    }
    $plan = Get-WinToolNote -Object $Catalog -Name "powerPlan"
    foreach ($field in @("baseGuid", "copyGuid", "fallbackGuid")) {
        $value = [string](Get-WinToolNote -Object $plan -Name $field -Default "")
        if ($value -notmatch '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') {
            $Errors.Add("powerPlan.$field must be a lowercase GUID.")
        }
    }
}
# endregion

# region src/Private/Config.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function ConvertTo-WinToolProfile {
    param(
        [string[]]$AppId,
        [string[]]$TweakId,
        $Terminal,
        [string]$Name = "My WinTool profile"
    )
    if ($null -eq $AppId) {
        $AppId = @()
    }
    if ($null -eq $TweakId) {
        $TweakId = @()
    }
    $stamp = [DateTime]::UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ")
    return [pscustomobject]@{
        schemaVersion = 1
        name = $Name
        exportedBy = "WinTool " + $script:WinToolVersion
        exportedAt = $stamp
        apps = @($AppId)
        tweaks = @($TweakId)
        terminal = $Terminal
    }
}

function Read-WinToolProfile {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    if (-not (Test-Path -LiteralPath $Path)) {
        throw "Profile not found: $Path"
    }
    $toolProfile = Read-WinToolJsonFile -Path $Path
    $version = 0
    $versionProperty = $toolProfile.PSObject.Properties["schemaVersion"]
    if ($null -ne $versionProperty -and $null -ne $versionProperty.Value) {
        $version = [int]$versionProperty.Value
    }
    if ($version -ne 1) {
        throw "This file is not a WinTool profile (schema version 1)."
    }
    return $toolProfile
}

function Write-WinToolProfile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)]$Profile
    )
    Write-WinToolJsonFile -Path $Path -Value $Profile
}

function Resolve-WinToolProfileSelection {
    param(
        [Parameter(Mandatory = $true)]$Profile
    )
    $apps = Get-WinToolAppCatalog
    $tweaks = Get-WinToolTweakCatalog
    $knownApps = @{}
    foreach ($category in @(Get-WinToolNote -Object $apps -Name "categories" -Default @())) {
        foreach ($app in @(Get-WinToolNote -Object $category -Name "apps" -Default @())) {
            $knownApps[[string]$app.id] = $app
        }
    }
    $knownTweaks = @{}
    foreach ($tweak in @(Get-WinToolNote -Object $tweaks -Name "tweaks" -Default @())) {
        $knownTweaks[[string]$tweak.id] = $tweak
    }

    $selectedApps = New-Object System.Collections.Generic.List[object]
    $unknownApps = New-Object System.Collections.Generic.List[string]
    foreach ($id in @(Get-WinToolNote -Object $Profile -Name "apps" -Default @())) {
        $key = [string]$id
        if ($knownApps.ContainsKey($key)) {
            $selectedApps.Add($knownApps[$key])
        }
        elseif (-not [string]::IsNullOrWhiteSpace($key)) {
            $unknownApps.Add($key)
        }
    }

    $selectedTweaks = New-Object System.Collections.Generic.List[object]
    $unknownTweaks = New-Object System.Collections.Generic.List[string]
    foreach ($id in @(Get-WinToolNote -Object $Profile -Name "tweaks" -Default @())) {
        $key = [string]$id
        if ($knownTweaks.ContainsKey($key)) {
            $selectedTweaks.Add($knownTweaks[$key])
        }
        elseif (-not [string]::IsNullOrWhiteSpace($key)) {
            $unknownTweaks.Add($key)
        }
    }

    return [pscustomobject]@{
        AppRecords = $selectedApps.ToArray()
        TweakRecords = $selectedTweaks.ToArray()
        UnknownApps = $unknownApps.ToArray()
        UnknownTweaks = $unknownTweaks.ToArray()
    }
}
# endregion

# region src/Private/Theme.ps1
# Copyright (c) 2026 Henrique
