function Get-WinToolModuleScript {
    param(
        [string]$Name = "Terminal-Icons"
    )
    if ($Name -notmatch '^[A-Za-z0-9.-]+$') {
        throw "Unexpected module name '$Name'."
    }
    # PowerShellGet 1.0 (Windows PowerShell 5.1) lacks some switches, so they
    # are only passed when this Install-Module has them.
    $scriptText = @'
$ErrorActionPreference = "Stop"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$nuget = Get-PackageProvider -Name NuGet -ListAvailable -ErrorAction SilentlyContinue
if ($null -eq $nuget) {
    Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force | Out-Null
}
$gallery = Get-PSRepository -Name PSGallery -ErrorAction SilentlyContinue
if ($null -eq $gallery) {
    Register-PSRepository -Default
}
Set-PSRepository -Name PSGallery -InstallationPolicy Trusted
$options = @{ Name = "__MODULE__"; Scope = "CurrentUser"; Force = $true }
$installer = Get-Command -Name Install-Module
if ($installer.Parameters.ContainsKey("AllowClobber")) { $options["AllowClobber"] = $true }
if ($installer.Parameters.ContainsKey("SkipPublisherCheck")) { $options["SkipPublisherCheck"] = $true }
Install-Module @options
$installed = Get-Module -ListAvailable -Name "__MODULE__" | Sort-Object Version -Descending | Select-Object -First 1
Write-Output ("__MODULE__ " + [string]$installed.Version + " installed.")
'@
    return $scriptText.Replace("__MODULE__", $Name)
}

function Get-WinToolWingetStepAction {
    param($Step)
    $action = [string](Get-WinToolNote -Object $Step -Name "Action" -Default "install")
    if ([string]::IsNullOrWhiteSpace($action)) {
        $action = "install"
    }
    return $action
}

function Test-WinToolStepSuccess {
    param(
        [Parameter(Mandatory = $true)]$Step,
        [int]$ExitCode
    )
    $codes = @(Get-WinToolNote -Object $Step -Name "SuccessCodes" -Default @(0))
    foreach ($code in $codes) {
        if ([int]$code -eq $ExitCode) {
            return $true
        }
    }
    return $false
}

function Get-WinToolPlanCommand {
    param(
        [Parameter(Mandatory = $true)]$Step
    )
    $type = [string]$Step.Type
    if (Test-WinToolLocalStepType -Type $type) {
        return $null
    }
    if ($type -eq "winget") {
        return [pscustomobject]@{
            FilePath = Get-WinToolWingetPath
            ArgumentList = @(Get-WinToolWingetArgument -Id ([string]$Step.WingetId) -Scope ([string]$Step.Scope) -Action (Get-WinToolWingetStepAction -Step $Step))
        }
    }
    if ($type -eq "process") {
        return [pscustomobject]@{
            FilePath = [string]$Step.FilePath
            ArgumentList = @($Step.Arguments)
        }
    }
    if ($type -eq "module") {
        $moduleName = [string](Get-WinToolNote -Object $Step -Name "Module" -Default "Terminal-Icons")
        $scriptPath = Join-Path ([System.IO.Path]::GetTempPath()) ("WinTool-module-" + $moduleName + ".ps1")
        Write-WinToolUtf8File -Path $scriptPath -Text (Get-WinToolModuleScript -Name $moduleName)
        $hostPath = $null
        if ([string]$Step.Host -eq "pwsh") {
            Sync-WinToolProcessPath
            $command = Get-Command -Name "pwsh.exe" -ErrorAction SilentlyContinue
            if ($null -ne $command) {
                $hostPath = [string]$command.Source
            }
        }
        else {
            $hostPath = Join-Path $env:SystemRoot "System32/WindowsPowerShell/v1.0/powershell.exe"
        }
        return [pscustomobject]@{
            FilePath = $hostPath
            ArgumentList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $scriptPath)
        }
    }
    if ($type -eq "fix-script") {
        $scriptPath = Join-Path ([System.IO.Path]::GetTempPath()) ("WinTool-fix-" + [string]$Step.Script + ".ps1")
        Write-WinToolUtf8File -Path $scriptPath -Text (Get-WinToolFixScript -Name ([string]$Step.Script))
        return [pscustomobject]@{
            FilePath = (Get-WinToolSystemFile -RelativePath "System32\WindowsPowerShell\v1.0\powershell.exe")
            ArgumentList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $scriptPath)
        }
    }
    if ($type -eq "inline-script") {
        $scriptPath = Join-Path ([System.IO.Path]::GetTempPath()) ("WinTool-" + [string]$Step.Name + ".ps1")
        Write-WinToolUtf8File -Path $scriptPath -Text ([string]$Step.Text)
        return [pscustomobject]@{
            FilePath = (Get-WinToolSystemFile -RelativePath "System32\WindowsPowerShell\v1.0\powershell.exe")
            ArgumentList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $scriptPath)
        }
    }
    if ($type -eq "wsl-install") {
        $distro = Get-WinToolWslDistroName -Step $Step
        $scriptPath = Join-Path ([System.IO.Path]::GetTempPath()) "WinTool-wsl-install.ps1"
        Write-WinToolUtf8File -Path $scriptPath -Text (Get-WinToolWslInstallScript -Distro $distro)
        return [pscustomobject]@{
            FilePath = (Get-WinToolSystemFile -RelativePath "System32\WindowsPowerShell\v1.0\powershell.exe")
            ArgumentList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $scriptPath)
        }
    }
    if ($type -eq "font-download") {
        $scriptPath = Join-Path ([System.IO.Path]::GetTempPath()) "WinTool-font-download.ps1"
        $body = Get-WinToolFontDownloadScript -Step $Step
        Write-WinToolUtf8File -Path $scriptPath -Text $body
        $hostPath = Join-Path $env:SystemRoot "System32/WindowsPowerShell/v1.0/powershell.exe"
        return [pscustomobject]@{
            FilePath = $hostPath
            ArgumentList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $scriptPath)
        }
    }
    if ($type -eq "tool-download") {
        $scriptPath = Join-Path ([System.IO.Path]::GetTempPath()) "WinTool-tool-download.ps1"
        $body = Get-WinToolToolDownloadScript -Url ([string]$Step.Url) -FileName ([string]$Step.FileName)
        Write-WinToolUtf8File -Path $scriptPath -Text $body
        $hostPath = Join-Path $env:SystemRoot "System32/WindowsPowerShell/v1.0/powershell.exe"
        return [pscustomobject]@{
            FilePath = $hostPath
            ArgumentList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $scriptPath)
        }
    }
    if ($type -eq "wsl-shell") {
        $distro = Get-WinToolWslDistroName -Step $Step
        $bashPath = Join-Path ([System.IO.Path]::GetTempPath()) "WinTool-wsl-setup.sh"
        Write-WinToolUtf8File -Path $bashPath -Text (Get-WinToolWslSetupText -Step $Step)
        $scriptPath = Join-Path ([System.IO.Path]::GetTempPath()) "WinTool-wsl-shell.ps1"
        Write-WinToolUtf8File -Path $scriptPath -Text (Get-WinToolWslShellScript -Distro $distro -ScriptPath $bashPath)
        return [pscustomobject]@{
            FilePath = (Get-WinToolSystemFile -RelativePath "System32\WindowsPowerShell\v1.0\powershell.exe")
            ArgumentList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $scriptPath)
        }
    }
    throw "Unknown plan step '$type'."
}

# Steps that run inside WinTool instead of as a separate program. Both the
# window's runner and Invoke-WinToolPlan ask Get-WinToolPlanCommand first; a
# $null answer means "run it here", so every type listed here needs a handler.
$script:WinToolLocalStepHandlers = [ordered]@{
    "font" = "Invoke-WinToolFontStep"
    "profile" = "Invoke-WinToolProfileStep"
    "scheme" = "Invoke-WinToolSchemeStep"
    "starship-preset" = "Invoke-WinToolStarshipPresetStep"
    "wsl-profile" = "Invoke-WinToolWslProfileStep"
}

function Test-WinToolLocalStepType {
    param(
        [string]$Type
    )
    return $script:WinToolLocalStepHandlers.Contains([string]$Type)
}

function Invoke-WinToolFontStep {
    param($Step)
    Invoke-WinToolTerminalFont -Face ([string]$Step.Face) -Match ([string]$Step.Match)
}

function Invoke-WinToolProfileStep {
    param($Step)
    Write-WinToolShellProfile -PromptId ([string]$Step.Prompt) -TerminalIcons ([bool]$Step.TerminalIcons) -PromptStyle ([string]$Step.PromptStyle) -PsReadLine ([bool]$Step.PsReadLine) -Zoxide ([bool]$Step.Zoxide)
}

function Invoke-WinToolSchemeStep {
    param($Step)
    Invoke-WinToolTerminalScheme -SchemeId ([string]$Step.SchemeId)
}

function Invoke-WinToolStarshipPresetStep {
    param($Step)
    Invoke-WinToolStarshipPreset -Preset ([string]$Step.Preset)
}

function Invoke-WinToolWslProfileStep {
    param($Step)
    Invoke-WinToolWslTerminalProfile -Distro (Get-WinToolWslDistroName -Step $Step) -Face ([string]$Step.Face) -Match ([string]$Step.Match)
}

function Invoke-WinToolLocalStep {
    param(
        [Parameter(Mandatory = $true)]$Step
    )
    $type = [string]$Step.Type
    if (-not (Test-WinToolLocalStepType -Type $type)) {
        throw "Step '$type' is not a local step."
    }
    & ([string]$script:WinToolLocalStepHandlers[$type]) -Step $Step
}

function Invoke-WinToolPlan {
    param(
        $Step
    )
    $steps = @($Step)
    $index = 0
    $skipZsh = $false
    foreach ($item in $steps) {
        $index++
        if ([string]$item.Type -eq "wsl-shell" -and $skipZsh) {
            Write-WinToolLog -Message "Zsh setup is waiting on a reboot. Run terminal setup again after Windows restarts." -Level "warn"
            continue
        }
        Write-WinToolLog -Message ("[{0}/{1}] {2}" -f $index, $steps.Count, [string]$item.Label) -Level "info"
        $command = Get-WinToolPlanCommand -Step $item
        if ($null -eq $command) {
            try {
                Invoke-WinToolLocalStep -Step $item
            }
            catch {
                Write-WinToolLog -Message ("{0} failed. {1}" -f [string]$item.Label, $_.Exception.Message) -Level "error"
            }
            continue
        }
        if ([string]::IsNullOrWhiteSpace([string]$command.FilePath) -or -not (Test-Path -LiteralPath ([string]$command.FilePath))) {
            Write-WinToolLog -Message ("Skipped {0} because the program was not found." -f [string]$item.Label) -Level "warn"
            continue
        }
        $result = Invoke-WinToolCapturedProcess -FilePath ([string]$command.FilePath) -ArgumentList @($command.ArgumentList)
        if (-not [string]::IsNullOrWhiteSpace($result.Output)) {
            foreach ($line in ($result.Output -split '\r?\n')) {
                if (-not [string]::IsNullOrWhiteSpace($line)) {
                    Write-WinToolLog -Message $line.Trim() -Level "info"
                }
            }
        }
        if ([string]$item.Type -eq "winget") {
            $outcome = ConvertTo-WinToolWingetResult -ExitCode $result.ExitCode -Output $result.Output
            if ($outcome.Status -eq "Failed") {
                Write-WinToolLog -Message ("{0} failed (exit {1})." -f [string]$item.Label, $result.ExitCode) -Level "error"
            }
            elseif ($outcome.Status -eq "AlreadyInstalled") {
                Write-WinToolLog -Message ("{0}: {1}." -f [string]$item.Label, (Get-WinToolWingetOutcomeText -Action (Get-WinToolWingetStepAction -Step $item) -Status $outcome.Status)) -Level "ok"
            }
            else {
                Write-WinToolLog -Message ("{0}: done." -f [string]$item.Label) -Level "ok"
            }
        }
        elseif (-not (Test-WinToolStepSuccess -Step $item -ExitCode $result.ExitCode)) {
            Write-WinToolLog -Message ("{0} exited with code {1}." -f [string]$item.Label, $result.ExitCode) -Level "error"
        }
        else {
            Write-WinToolLog -Message ("{0}: done." -f [string]$item.Label) -Level "ok"
        }
        if ([string]$item.Type -eq "wsl-install" -and $result.Output -match "(?i)reboot") {
            $skipZsh = $true
            Write-WinToolLog -Message "Windows asked for a reboot before WSL can finish." -Level "warn"
        }
    }
}

function Start-WinToolScriptJob {
    param(
        [Parameter(Mandatory = $true)][string]$ScriptText,
        [object[]]$Argument
    )
    $sync = [hashtable]::Synchronized(@{
        Done = $false
        Ok = $false
        Error = $null
    })
    $runspace = [runspacefactory]::CreateRunspace()
    $runspace.ApartmentState = "STA"
    $runspace.Open()
    $powershell = [powershell]::Create()
    $powershell.Runspace = $runspace
    [void]$powershell.AddScript($ScriptText)
    [void]$powershell.AddArgument($sync)
    foreach ($item in @($Argument)) {
        [void]$powershell.AddArgument($item)
    }
    [void]$powershell.BeginInvoke()
    return [pscustomobject]@{
        PowerShell = $powershell
        Handle = $null
        Sync = $sync
        Runspace = $runspace
    }
}
# endregion

# region src/Private/Elevation.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Test-WinToolAdministrator {
    if (-not (Test-WinToolWindows)) {
        return $false
    }
    $identity = [System.Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object System.Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)
}

function ConvertTo-WinToolLiteral {
    param(
        [AllowEmptyString()][string]$Text
    )
    if ($null -eq $Text) {
        $Text = ""
    }
    return "'" + ($Text.Replace("'", "''")) + "'"
}

function Resolve-WinToolEntryPath {
    param(
        [string]$EntryPath,
        [string]$CommandPath
    )
    if (-not [string]::IsNullOrWhiteSpace($EntryPath)) {
        return $EntryPath
    }
    if (-not [string]::IsNullOrWhiteSpace($CommandPath)) {
        return $CommandPath
    }
    return $null
}

function Get-WinToolPublishedLaunchUrl {
    if (-not [string]::IsNullOrWhiteSpace($env:WINTOOL_URL)) {
        return $env:WINTOOL_URL
    }
    if (-not [string]::IsNullOrWhiteSpace($script:WinToolPublishedUrl)) {
        return $script:WinToolPublishedUrl
    }
    return "https://raw.githubusercontent.com/Hinrikao/WinTool/main/wintool.ps1"
}

function New-WinToolRelaunchScript {
    param(
        [string]$WorkingDirectory,
        [string]$EntryPath,
        [string]$ApplyProfile,
        [bool]$Unattended,
        [string]$LaunchUrl,
        [bool]$Hidden,
        [bool]$ShowConsole
    )
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('$ErrorActionPreference = "Stop"')
    [void]$lines.Add('$env:WINTOOL_PAUSE_ON_ERROR = "1"')
    if ($Hidden) {
        [void]$lines.Add('$env:WINTOOL_HIDDEN = "1"')
    }
    else {
        [void]$lines.Add('$env:WINTOOL_HIDDEN = $null')
    }
    if ($ShowConsole) {
        [void]$lines.Add('$env:WINTOOL_SHOW_CONSOLE = "1"')
    }
    if (-not [string]::IsNullOrWhiteSpace($WorkingDirectory)) {
        [void]$lines.Add("Set-Location -LiteralPath " + (ConvertTo-WinToolLiteral -Text $WorkingDirectory))
    }
    [void]$lines.Add("try {")
    if (-not [string]::IsNullOrWhiteSpace($EntryPath)) {
        $call = "    & " + (ConvertTo-WinToolLiteral -Text $EntryPath)
        if (-not [string]::IsNullOrWhiteSpace($ApplyProfile)) {
            $call += " -ApplyProfile " + (ConvertTo-WinToolLiteral -Text $ApplyProfile)
        }
        if ($Unattended) {
            $call += " -Unattended"
        }
        if ($ShowConsole) {
            $call += " -ShowConsole"
        }
        [void]$lines.Add($call)
    }
    else {
        if ([string]::IsNullOrWhiteSpace($LaunchUrl)) {
            $LaunchUrl = Get-WinToolPublishedLaunchUrl
        }
        $download = "    Invoke-Expression (Invoke-RestMethod -Uri " + (ConvertTo-WinToolLiteral -Text $LaunchUrl) + ")"
        [void]$lines.Add($download)
    }
    [void]$lines.Add("}")
    [void]$lines.Add("catch {")
    [void]$lines.Add('    $text = ($_ | Out-String)')
    if ($Hidden) {
        # Bring the hidden console back so the error and the Enter prompt are visible.
        [void]$lines.Add('    try {')
        [void]$lines.Add('        if ($null -eq ("WinToolConsoleApi" -as [type])) {')
        [void]$lines.Add("            Add-Type -TypeDefinition @'")
        foreach ($sourceLine in ((Get-WinToolConsoleApiSource) -split "`r?`n")) {
            [void]$lines.Add($sourceLine)
        }
        [void]$lines.Add("'@")
        [void]$lines.Add('        }')
        [void]$lines.Add('        $null = [WinToolConsoleApi]::ShowWindow([WinToolConsoleApi]::GetConsoleWindow(), 5)')
        [void]$lines.Add('    }')
        [void]$lines.Add('    catch {')
        [void]$lines.Add('        $null = $_.Exception.Message')
        [void]$lines.Add('    }')
    }
    [void]$lines.Add('    $logDir = Join-Path $env:TEMP "WinTool"')
    [void]$lines.Add('    if (-not (Test-Path -LiteralPath $logDir)) { New-Item -ItemType Directory -Path $logDir -Force | Out-Null }')
    [void]$lines.Add('    $logPath = Join-Path $logDir "wintool.log"')
    [void]$lines.Add('    Add-Content -LiteralPath $logPath -Value ("==== " + (Get-Date).ToString("o") + " ====") -Encoding UTF8')
    [void]$lines.Add('    Add-Content -LiteralPath $logPath -Value $text -Encoding UTF8')
    [void]$lines.Add('    Write-Host $text')
    [void]$lines.Add('    Write-Host ("Log: " + $logPath)')
    [void]$lines.Add("    try {")
    [void]$lines.Add("        Add-Type -AssemblyName PresentationFramework -ErrorAction Stop")
    [void]$lines.Add('        [System.Windows.MessageBox]::Show($text, "WinTool") | Out-Null')
    [void]$lines.Add("    }")
    [void]$lines.Add("    catch {")
    [void]$lines.Add('        Write-Host $_.Exception.Message')
    [void]$lines.Add("    }")
    [void]$lines.Add('    Write-Host "Press Enter to close this window."')
    [void]$lines.Add("    Read-Host | Out-Null")
    [void]$lines.Add("    exit 1")
    [void]$lines.Add("}")
    return ($lines.ToArray() -join "`r`n") + "`r`n"
}

function Get-WinToolHostArgument {
    param(
        [Parameter(Mandatory = $true)][string]$LauncherPath,
        [bool]$Hidden
    )
    $arguments = @("-STA", "-NoProfile", "-ExecutionPolicy", "Bypass")
    if ($Hidden) {
        $arguments += @("-WindowStyle", "Hidden")
    }
    return $arguments + @("-File", $LauncherPath)
}

function Get-WinToolWorkingDirectory {
    try {
        $current = Get-Location
        $path = [string]$current.ProviderPath
        if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path -PathType Container)) {
            return $path
        }
    }
    catch {
        $null = $_.Exception.Message
    }
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE) -and (Test-Path -LiteralPath $env:USERPROFILE)) {
        return $env:USERPROFILE
    }
    return [string]$env:SystemRoot
}

function Start-WinToolRelaunch {
    param(
        [switch]$Elevate
    )
    $executable = Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe"
    $entry = Resolve-WinToolEntryPath -EntryPath $script:WinToolEntryPath -CommandPath ""
    if (-not [string]::IsNullOrWhiteSpace($entry) -and -not (Test-Path -LiteralPath $entry)) {
        $entry = $null
    }
    $directory = Get-WinToolWorkingDirectory
    $showConsole = Test-WinToolShowConsole
    $hidden = -not ($showConsole -or [bool]$script:WinToolUnattended)
    $scriptText = New-WinToolRelaunchScript -WorkingDirectory $directory -EntryPath $entry -ApplyProfile $script:WinToolApplyProfile -Unattended ([bool]$script:WinToolUnattended) -LaunchUrl (Get-WinToolPublishedLaunchUrl) -Hidden $hidden -ShowConsole $showConsole
    $launcherDirectory = Join-Path $env:TEMP "WinTool"
    if (-not (Test-Path -LiteralPath $launcherDirectory)) {
        New-Item -ItemType Directory -Path $launcherDirectory -Force | Out-Null
    }
    $launcherPath = Join-Path $launcherDirectory "relaunch.ps1"
    $encoding = New-Object System.Text.UTF8Encoding $true
    [System.IO.File]::WriteAllText($launcherPath, $scriptText, $encoding)
    $line = ConvertTo-WinToolArgumentLine -ArgumentList @(Get-WinToolHostArgument -LauncherPath $launcherPath -Hidden $hidden)
    $style = "Normal"
    if ($hidden) {
        $style = "Hidden"
    }
    if ($Elevate) {
        Write-Host "WinTool needs administrator approval. Accept the Windows prompt to continue."
        try {
            Start-Process -FilePath $executable -ArgumentList $line -Verb RunAs -WindowStyle $style | Out-Null
        }
        catch {
            Write-Host "WinTool was not started. Administrator approval was declined."
        }
        return
    }
    Write-Host "WinTool is opening in its own window. You can close this terminal."
    Start-Process -FilePath $executable -ArgumentList $line -WindowStyle $style | Out-Null
}

function Request-WinToolAdministrator {
    Start-WinToolRelaunch -Elevate
}

function Request-WinToolStaHost {
    Start-WinToolRelaunch
}
# endregion

# region src/Private/Fixes.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# Fixes are listed in data/fixes.json. A step is either a program under
# %SystemRoot% with fixed arguments, or one of the named scripts below. The
# catalog cannot carry its own script text.

function Get-WinToolFixCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Fixes"))
}

function Get-WinToolSystemRoot {
    if (-not [string]::IsNullOrWhiteSpace($env:SystemRoot)) {
        return $env:SystemRoot
    }
    return "C:\Windows"
}

function Get-WinToolSystemFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath
    )
    return ((Get-WinToolSystemRoot).TrimEnd('\') + "\" + $RelativePath.TrimStart('\'))
}

function Get-WinToolFixScriptName {
    return @("windows-update-reset", "winget-repair")
}

function Get-WinToolFixScript {
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )
    switch ($Name) {
        "windows-update-reset" {
            return @'
$ErrorActionPreference = "Continue"
$services = @("wuauserv", "usosvc", "bits", "cryptsvc", "msiserver")
foreach ($name in $services) {
    $service = Get-Service -Name $name -ErrorAction SilentlyContinue
    if ($null -ne $service -and $service.Status -ne "Stopped") {
        Write-Output ("Stopping " + $name)
        Stop-Service -Name $name -Force -ErrorAction SilentlyContinue
    }
}
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$folders = @(
    (Join-Path $env:SystemRoot "SoftwareDistribution"),
    (Join-Path $env:SystemRoot "System32\catroot2")
)
foreach ($folder in $folders) {
    if (-not (Test-Path -LiteralPath $folder)) {
        continue
    }
    $newName = (Split-Path -Leaf $folder) + ".wintool-" + $stamp
    try {
        Rename-Item -LiteralPath $folder -NewName $newName -ErrorAction Stop
        Write-Output ("Renamed " + $folder + " to " + $newName)
    }
    catch {
        Write-Output ("Could not rename " + $folder + ": " + $_.Exception.Message)
    }
}
foreach ($name in @("cryptsvc", "bits", "wuauserv")) {
    Write-Output ("Starting " + $name)
    Start-Service -Name $name -ErrorAction SilentlyContinue
}
Write-Output "Windows Update components were reset. Restart the PC, then check for updates."
'@
        }
        "winget-repair" {
            return @'
$ErrorActionPreference = "Stop"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
try {
    $nuget = Get-PackageProvider -Name NuGet -ListAvailable -ErrorAction SilentlyContinue
    if ($null -eq $nuget) {
        Write-Output "Installing the NuGet package provider."
        Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force | Out-Null
    }
    Write-Output "Installing the Microsoft.WinGet.Client module."
    Install-Module -Name Microsoft.WinGet.Client -Force -AllowClobber -Scope AllUsers -Repository PSGallery
    Import-Module Microsoft.WinGet.Client
    Write-Output "Repairing winget. This downloads App Installer and its dependencies."
    Repair-WinGetPackageManager -AllUsers -Force -Latest
    Write-Output "winget was repaired."
}
catch {
    Write-Output ("The module repair did not work: " + $_.Exception.Message)
    Write-Output "Registering App Installer again from the copy Windows has."
    Add-AppxPackage -RegisterByFamilyName -MainPackage "Microsoft.DesktopAppInstaller_8wekyb3d8bbwe"
    Write-Output "App Installer was registered again. Open a new window and try winget."
}
'@
        }
        default {
            throw "Unknown fix script '$Name'."
        }
    }
}

function Get-WinToolFixPlan {
    param(
        [Parameter(Mandatory = $true)]$Fix
    )
    $steps = New-Object System.Collections.Generic.List[object]
    foreach ($step in @(Get-WinToolNote -Object $Fix -Name "steps" -Default @())) {
        $type = [string](Get-WinToolNote -Object $step -Name "type" -Default "")
        $label = [string](Get-WinToolNote -Object $step -Name "label" -Default ([string]$Fix.name))
        if ($type -eq "process") {
            $steps.Add([pscustomobject]@{
                Type = "process"
                Label = $label
                FilePath = (Get-WinToolSystemFile -RelativePath ([string]$step.file))
                Arguments = @(Get-WinToolNote -Object $step -Name "args" -Default @())
            })
        }
        elseif ($type -eq "script") {
            $steps.Add([pscustomobject]@{
                Type = "fix-script"
                Label = $label
                Script = [string]$step.script
            })
        }
        else {
            throw "Fix '$([string]$Fix.id)' has an unknown step type '$type'."
        }
    }
    return $steps.ToArray()
}

function Test-WinToolFixCatalog {
    param(
        $Catalog,
        $Errors
    )
    if ([int](Get-WinToolNote -Object $Catalog -Name "schemaVersion" -Default 0) -ne 1) {
        $Errors.Add("fixes.json schemaVersion must be 1.")
    }
    $ids = @{}
    $known = Get-WinToolFixScriptName
    foreach ($fix in @(Get-WinToolNote -Object $Catalog -Name "fixes" -Default @())) {
        $id = [string](Get-WinToolNote -Object $fix -Name "id" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or $ids.ContainsKey($id)) {
            $Errors.Add("A fix is missing an id or uses one twice: '$id'.")
        }
        $ids[$id] = $true
        foreach ($field in @("name", "description")) {
            if ([string]::IsNullOrWhiteSpace([string](Get-WinToolNote -Object $fix -Name $field -Default ""))) {
                $Errors.Add("Fix '$id' needs a $field.")
            }
        }
        $steps = @(Get-WinToolNote -Object $fix -Name "steps" -Default @())
        if ($steps.Count -eq 0) {
            $Errors.Add("Fix '$id' has no steps.")
        }
        foreach ($step in $steps) {
            $type = [string](Get-WinToolNote -Object $step -Name "type" -Default "")
            if ($type -eq "process") {
                $file = [string](Get-WinToolNote -Object $step -Name "file" -Default "")
                if ($file -notmatch '^System32\\[A-Za-z0-9]+\.exe$') {
                    $Errors.Add("Fix '$id' runs '$file'. Use a program under System32.")
                }
            }
            elseif ($type -eq "script") {
                if ($known -notcontains [string](Get-WinToolNote -Object $step -Name "script" -Default "")) {
                    $Errors.Add("Fix '$id' names a script WinTool does not have.")
                }
            }
            else {
                $Errors.Add("Fix '$id' has an unknown step type '$type'.")
            }
        }
    }
    if ($ids.Count -lt 4) {
        $Errors.Add("fixes.json should list the four built-in fixes.")
    }
}
# endregion

# region src/Private/Features.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# Optional Windows features from data/features.json. State is read with
# Get-WindowsOptionalFeature in a background runspace; changes go through
# Dism.exe so each one shows its own progress in the log.

$script:WinToolDismRestartCode = 3010

function Get-WinToolFeatureCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Features"))
}

function Get-WinToolFeatureStateScript {
    $scriptText = @'
param($Sync, $Names)
$ErrorActionPreference = "Stop"
try {
    $states = @{}
    foreach ($name in @($Names)) {
        try {
            $item = Get-WindowsOptionalFeature -Online -FeatureName $name -ErrorAction Stop
            if ($null -eq $item) {
                $states[$name] = "Missing"
            }
            else {
                $states[$name] = [string]$item.State
            }
        }
        catch {
            $states[$name] = "Missing"
        }
    }
    $Sync.States = $states
    $Sync.Ok = $true
}
catch {
    $Sync.Error = $_.Exception.Message
}
finally {
    $Sync.Done = $true
}
'@
    return $scriptText
}

function Get-WinToolFeatureStatus {
    param(
        [Parameter(Mandatory = $true)]$Feature,
        [hashtable]$State
    )
    # A feature counts as on only when every underlying name is enabled.
    $names = @($Feature.names)
    $enabled = 0
    $missing = 0
    foreach ($name in $names) {
        $value = ""
        if ($null -ne $State -and $State.ContainsKey([string]$name)) {
            $value = [string]$State[[string]$name]
        }
        if ($value -eq "Enabled" -or $value -eq "EnablePending") {
            $enabled++
        }
        elseif ($value -eq "Missing" -or [string]::IsNullOrWhiteSpace($value)) {
            $missing++
        }
    }
    if ($missing -gt 0) {
        return "Unavailable"
    }
    if ($enabled -eq $names.Count) {
        return "On"
    }
    if ($enabled -gt 0) {
        return "Partial"
    }
    return "Off"
}

function Get-WinToolFeaturePlan {
    param(
        $Enable,
        $Disable
    )
    $steps = New-Object System.Collections.Generic.List[object]
    $dism = Get-WinToolSystemFile -RelativePath "System32\Dism.exe"
    foreach ($feature in @($Enable)) {
        if ($null -eq $feature) { continue }
        foreach ($name in @($feature.names)) {
            $steps.Add([pscustomobject]@{
                Type = "process"
                Label = ("Turn on {0} ({1})" -f [string]$feature.name, [string]$name)
                FilePath = $dism
                Arguments = @("/Online", "/Enable-Feature", ("/FeatureName:" + [string]$name), "/All", "/NoRestart")
                SuccessCodes = @(0, $script:WinToolDismRestartCode)
            })
        }
    }
    foreach ($feature in @($Disable)) {
        if ($null -eq $feature) { continue }
        $names = @($feature.names)
        # Turn off the parent last, so dependent parts go first.
        [array]::Reverse($names)
        foreach ($name in $names) {
            $steps.Add([pscustomobject]@{
                Type = "process"
                Label = ("Turn off {0} ({1})" -f [string]$feature.name, [string]$name)
                FilePath = $dism
                Arguments = @("/Online", "/Disable-Feature", ("/FeatureName:" + [string]$name), "/NoRestart")
                SuccessCodes = @(0, $script:WinToolDismRestartCode)
            })
        }
    }
    return $steps.ToArray()
}

function Test-WinToolFeatureCatalog {
    param(
        $Catalog,
        $Errors
    )
    if ([int](Get-WinToolNote -Object $Catalog -Name "schemaVersion" -Default 0) -ne 1) {
        $Errors.Add("features.json schemaVersion must be 1.")
    }
    $ids = @{}
    foreach ($feature in @(Get-WinToolNote -Object $Catalog -Name "features" -Default @())) {
        $id = [string](Get-WinToolNote -Object $feature -Name "id" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or $ids.ContainsKey($id)) {
            $Errors.Add("A Windows feature is missing an id or uses one twice: '$id'.")
        }
        $ids[$id] = $true
        if ([string]::IsNullOrWhiteSpace([string](Get-WinToolNote -Object $feature -Name "name" -Default "")) -or [string]::IsNullOrWhiteSpace([string](Get-WinToolNote -Object $feature -Name "description" -Default ""))) {
            $Errors.Add("Windows feature '$id' needs a name and description.")
        }
        $names = @(Get-WinToolNote -Object $feature -Name "names" -Default @())
        if ($names.Count -eq 0) {
            $Errors.Add("Windows feature '$id' has no DISM feature names.")
        }
        foreach ($name in $names) {
            if ([string]$name -notmatch '^[A-Za-z0-9][A-Za-z0-9.-]*$') {
                $Errors.Add("Windows feature '$id' has an invalid DISM name '$name'.")
            }
        }
    }
    if ($ids.Count -lt 8) {
        $Errors.Add("features.json should list the common optional features.")
    }
}
# endregion

# region src/UI/Factory.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Get-WinToolUi {
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )
    $control = $script:WinToolWindow.FindName($Name)
    if ($null -eq $control) {
        throw "WinTool could not find the window control '$Name'."
    }
    return $control
}

function Get-WinToolBrush {
    param(
        [Parameter(Mandatory = $true)][string]$Key
    )
    return $script:WinToolWindow.FindResource($Key)
}

function New-WinToolText {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [int]$Size = 14,
        [string]$Weight = "Normal",
        [string]$Brush = "BrushInk",
        [switch]$Wrap,
        [System.Windows.Thickness]$Margin = ([System.Windows.Thickness]::new(0))
    )
    $block = New-Object System.Windows.Controls.TextBlock
    $block.Text = $Text
    $block.FontSize = $Size
    $weights = [type]"System.Windows.FontWeights"
    $flags = [System.Reflection.BindingFlags]::Public -bor [System.Reflection.BindingFlags]::Static
    $weightProperty = $weights.GetProperty($Weight, $flags)
    if ($null -eq $weightProperty) {
        throw "Unknown font weight '$Weight'."
    }
    $block.FontWeight = $weightProperty.GetValue($null, $null)
    $block.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $Brush)
    $block.Margin = $Margin
    if ($Wrap) {
        $block.TextWrapping = "Wrap"
    }
    return $block
}

function New-WinToolCard {
    $border = New-Object System.Windows.Controls.Border
    $border.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushCard")
    $border.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
    $border.BorderThickness = [System.Windows.Thickness]::new(1)
    $border.CornerRadius = [System.Windows.CornerRadius]::new(12)
    $border.Padding = [System.Windows.Thickness]::new(16)
    $border.Margin = [System.Windows.Thickness]::new(0, 0, 0, 12)
    return $border
}

function New-WinToolBadge {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)][string]$Kind
    )
    $border = New-Object System.Windows.Controls.Border
    $border.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $border.Padding = [System.Windows.Thickness]::new(8, 2, 8, 2)
    $border.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
    $border.VerticalAlignment = "Center"
    $label = New-Object System.Windows.Controls.TextBlock
    $label.Text = $Text
    $label.FontSize = 11
    $label.FontWeight = "SemiBold"
    if ($Kind -eq "caution") {
        $border.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushWarnSoft")
        $label.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushWarn")
    }
    else {
        $border.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushOkSoft")
        $label.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushOk")
    }
    $border.Child = $label
    return $border
}

function New-WinToolColumn {
    param(
        [switch]$Auto
    )
    $column = New-Object System.Windows.Controls.ColumnDefinition
    if ($Auto) {
        $column.Width = [System.Windows.GridLength]::Auto
    }
    else {
        $column.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
    }
    return $column
}

function Sync-WinToolSearchHint {
    param(
        [Parameter(Mandatory = $true)][string]$BoxName,
        [Parameter(Mandatory = $true)][string]$HintName
    )
    $box = Get-WinToolUi -Name $BoxName
    $hint = Get-WinToolUi -Name $HintName
    if ([string]::IsNullOrEmpty($box.Text)) {
        $hint.Visibility = "Visible"
    }
    else {
        $hint.Visibility = "Collapsed"
    }
}

# Event handlers are registered through Register-WinToolUiEvent instead of
# scriptblock.GetNewClosure(). A closure runs in its own dynamic module, so
# $script: inside it does not reach WinTool's state and reads as $null. That is
# what crashed the Terminal tab with "The property 'prompt' cannot be found".
# Per-control values travel in -Data, and every handler runs inside try/catch.
function Register-WinToolUiEvent {
    param(
        [Parameter(Mandatory = $true)]$Control,
        [Parameter(Mandatory = $true)][string]$EventName,
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][scriptblock]$Action,
        $Data
    )
    if ($null -eq $script:WinToolUiHandlers) {
        $script:WinToolUiHandlers = New-Object System.Collections.Generic.List[object]
    }
    $id = $script:WinToolUiHandlers.Count
    $script:WinToolUiHandlers.Add([pscustomobject]@{
            Id = $id
            Name = $Name
            EventName = $EventName
            Control = $Control
            Action = $Action
            Data = $Data
        })
    $dispatch = [scriptblock]::Create(('Invoke-WinToolUiEvent -Id {0} -Source $args[0] -EventData $args[1]' -f $id))
    $method = "add_" + $EventName
    $null = $Control.$method($dispatch)
}

function Invoke-WinToolUiEvent {
    param(
        [Parameter(Mandatory = $true)][int]$Id,
        $Source,
        $EventData
    )
    $entry = $script:WinToolUiHandlers[$Id]
    try {
        $null = & $entry.Action $Source $EventData $entry.Data
    }
    catch {
        Write-WinToolUiError -Name ([string]$entry.Name) -ErrorRecord $_
    }
}

function Write-WinToolUiError {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        $ErrorRecord
    )
    if ($null -eq $script:WinToolUiErrors) {
        $script:WinToolUiErrors = New-Object System.Collections.Generic.List[object]
    }
    $message = "Unknown error."
    if ($null -ne $ErrorRecord -and $null -ne $ErrorRecord.Exception) {
        $message = [string]$ErrorRecord.Exception.Message
    }
    $script:WinToolUiErrors.Add([pscustomobject]@{ Name = $Name; Message = $message; Record = $ErrorRecord })
    $logPath = $null
    try {
        $detail = Format-WinToolErrorText -ErrorRecord $ErrorRecord -Title ("A WinTool action failed: " + $Name)
        $logPath = Write-WinToolFailureLog -Text $detail
        Write-WinToolLog -Message ("{0} failed: {1}" -f $Name, $message) -Level "error"
    }
    catch {
        $null = $_.Exception.Message
    }
    if ($script:WinToolUiQuiet) {
        return
    }
    # Show each failing action once, so a repeating event cannot flood the screen.
    if ($null -eq $script:WinToolUiErrorShown) {
        $script:WinToolUiErrorShown = @{}
    }
    if ($script:WinToolUiErrorShown.ContainsKey($Name)) {
        return
    }
    $script:WinToolUiErrorShown[$Name] = $true
    try {
        $text = "Something went wrong in '" + $Name + "'. WinTool is still open.`r`n`r`n" + $message
        if (-not [string]::IsNullOrWhiteSpace($logPath)) {
            $text += "`r`n`r`nDetails: " + $logPath
        }
        [System.Windows.MessageBox]::Show($text, "WinTool") | Out-Null
    }
    catch {
        $null = $_.Exception.Message
    }
}

function Get-WinToolUiError {
    # ToArray() keeps this on object[]; @() around a generic list fails on 5.1.
    if ($null -eq $script:WinToolUiErrors) {
        return , @()
    }
    return , $script:WinToolUiErrors.ToArray()
}
# endregion

# region src/UI/InstallView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolInstallView {
    $catalog = Get-WinToolAppCatalog
    $hostPanel = Get-WinToolUi -Name "AppCategories"
    $hostPanel.Children.Clear()
    $script:WinToolState.AppRows = @()
    $script:WinToolState.CategoryRows = @()

    foreach ($category in @(Get-WinToolNote -Object $catalog -Name "categories" -Default @())) {
        $card = New-WinToolCard
        $stack = New-Object System.Windows.Controls.StackPanel
        $header = New-Object System.Windows.Controls.Grid
        $header.ColumnDefinitions.Add((New-WinToolColumn))
        $header.ColumnDefinitions.Add((New-WinToolColumn -Auto))

        $titleStack = New-Object System.Windows.Controls.StackPanel
        [void]$titleStack.Children.Add((New-WinToolText -Text ([string]$category.name) -Size 18 -Weight "SemiBold"))
        $description = [string](Get-WinToolNote -Object $category -Name "description" -Default "")
        [void]$titleStack.Children.Add((New-WinToolText -Text $description -Size 13 -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 4, 16, 0))))
        [System.Windows.Controls.Grid]::SetColumn($titleStack, 0)
        [void]$header.Children.Add($titleStack)

        $selectAll = New-Object System.Windows.Controls.CheckBox
        $selectAll.Content = "Select all"
        $selectAll.VerticalAlignment = "Center"
        $selectAll.IsThreeState = $true
        [System.Windows.Controls.Grid]::SetColumn($selectAll, 1)
        [void]$header.Children.Add($selectAll)
        [void]$stack.Children.Add($header)

        $appsPanel = New-Object System.Windows.Controls.StackPanel
        $appsPanel.Margin = [System.Windows.Thickness]::new(0, 12, 0, 0)
        $appRows = @()
        foreach ($app in @(Get-WinToolNote -Object $category -Name "apps" -Default @())) {
            $row = New-WinToolAppRow -App $app -CategoryName ([string]$category.name)
            [void]$appsPanel.Children.Add($row.Panel)
            $appRows += $row
        }
        [void]$stack.Children.Add($appsPanel)
        $card.Child = $stack
        [void]$hostPanel.Children.Add($card)

        $categoryRow = [pscustomobject]@{
            Id = [string]$category.id
            Card = $card
            SelectAll = $selectAll
            Apps = $appRows
            Updating = $false
        }
        $script:WinToolState.CategoryRows += $categoryRow
        foreach ($row in $appRows) {
            $script:WinToolState.AppRows += $row
        }

        Register-WinToolUiEvent -Control $selectAll -EventName "Click" -Name "Install: select all in category" -Data $categoryRow -Action {
            param($source, $eventData, $boundCategory)
            $null = $source, $eventData
            Sync-WinToolCategoryFromHeader -CategoryRow $boundCategory
        }
        foreach ($row in $appRows) {
            foreach ($eventName in @("Checked", "Unchecked")) {
                Register-WinToolUiEvent -Control $row.Checkbox -EventName $eventName -Name "Install: tick an app" -Data $categoryRow -Action {
                    param($source, $eventData, $boundCategory)
                    $null = $source, $eventData
                    Sync-WinToolAppToggle -CategoryRow $boundCategory
                }
            }
        }
    }

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppSearch") -EventName "TextChanged" -Name "Install: search" -Action {
        Sync-WinToolSearchHint -BoxName "AppSearch" -HintName "AppSearchHint"
        Update-WinToolAppFilter
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppSelectVisible") -EventName "Click" -Name "Install: select visible" -Action {
        foreach ($row in @($script:WinToolState.AppRows)) {
            if ($row.Panel.Visibility -eq "Visible") {
                $row.Checkbox.IsChecked = $true
            }
        }
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppClear") -EventName "Click" -Name "Install: clear" -Action {
        Sync-WinToolAppCheck -Id @() -OnlyThese
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppInstall") -EventName "Click" -Name "Install: install selected" -Action {
        Invoke-WinToolInstallClick
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppSelectInstalled") -EventName "Click" -Name "Install: select installed" -Action {
        Select-WinToolInstalledApp
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppRefreshInstalled") -EventName "Click" -Name "Install: check installed" -Action {
        Start-WinToolAppDetection
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppUpdate") -EventName "Click" -Name "Install: update selected" -Action {
        Invoke-WinToolAppAction -App @(Get-WinToolCheckedApp) -Action "upgrade"
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppUninstall") -EventName "Click" -Name "Install: uninstall selected" -Action {
        Invoke-WinToolAppAction -App @(Get-WinToolCheckedApp) -Action "uninstall"
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AppUpgradeAll") -EventName "Click" -Name "Install: update all" -Action {
        Invoke-WinToolUpgradeAllClick
    }
    Sync-WinToolAppCount
}

function New-WinToolAppRow {
    param(
        $App,
        [string]$CategoryName
    )
    $tags = @(Get-WinToolNote -Object $App -Name "tags" -Default @()) -join " "
    $panel = New-Object System.Windows.Controls.Grid
    $panel.Margin = [System.Windows.Thickness]::new(0, 0, 0, 12)
    $panel.ColumnDefinitions.Add((New-WinToolColumn -Auto))
    $panel.ColumnDefinitions.Add((New-WinToolColumn))

    $checkbox = New-Object System.Windows.Controls.CheckBox
    $checkbox.VerticalAlignment = "Top"
    $checkbox.Margin = [System.Windows.Thickness]::new(0, 2, 10, 0)
    [System.Windows.Controls.Grid]::SetColumn($checkbox, 0)
    [void]$panel.Children.Add($checkbox)

    $text = New-Object System.Windows.Controls.StackPanel
    $titleLine = New-Object System.Windows.Controls.StackPanel
    $titleLine.Orientation = "Horizontal"
    [void]$titleLine.Children.Add((New-WinToolText -Text ([string]$App.name) -Weight "SemiBold"))
    $installedBadge = New-WinToolBadge -Text "Installed" -Kind "ok"
    $installedBadge.Visibility = "Collapsed"
    [void]$titleLine.Children.Add($installedBadge)
    $updateBadge = New-WinToolBadge -Text "Update available" -Kind "caution"
    $updateBadge.Visibility = "Collapsed"
    [void]$titleLine.Children.Add($updateBadge)
    [void]$text.Children.Add($titleLine)
    [void]$text.Children.Add((New-WinToolText -Text ([string]$App.description) -Size 13 -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 2, 0, 0))))
    [void]$text.Children.Add((New-WinToolText -Text ("winget: " + [string]$App.wingetId) -Size 12 -Brush "BrushMuted" -Margin ([System.Windows.Thickness]::new(0, 2, 0, 0))))
    [System.Windows.Controls.Grid]::SetColumn($text, 1)
    [void]$panel.Children.Add($text)

    $search = (@([string]$App.name, [string]$App.description, [string]$App.wingetId, [string]$App.id, $tags, $CategoryName) -join " ")
    $row = [pscustomobject]@{
        Id = [string]$App.id
        Name = [string]$App.name
        WingetId = [string]$App.wingetId
        DetectNames = @(Get-WinToolNote -Object $App -Name "detectNames" -Default @())
        Scope = [string](Get-WinToolNote -Object $App -Name "scope" -Default "")
        SearchText = $search
        Panel = $panel
        Checkbox = $checkbox
        InstalledBadge = $installedBadge
        UpdateBadge = $updateBadge
        Installed = $false
        UpdateAvailable = $false
    }

    # Right-click an app for a one-off update or uninstall.
    $menu = New-Object System.Windows.Controls.ContextMenu
    foreach ($choice in @(
            [pscustomobject]@{ Header = "Update this app"; Action = "upgrade"; Name = "Install: update one app" },
            [pscustomobject]@{ Header = "Uninstall this app"; Action = "uninstall"; Name = "Install: uninstall one app" }
        )) {
        $item = New-Object System.Windows.Controls.MenuItem
        $item.Header = $choice.Header
        Register-WinToolUiEvent -Control $item -EventName "Click" -Name $choice.Name -Data ([pscustomobject]@{ Row = $row; Action = $choice.Action }) -Action {
            param($source, $eventData, $target)
            $null = $source, $eventData
            Invoke-WinToolAppAction -App @($target.Row) -Action $target.Action
        }
        [void]$menu.Items.Add($item)
    }
    $panel.ContextMenu = $menu
    $panel.Background = [System.Windows.Media.Brushes]::Transparent
    return $row
}

function Sync-WinToolAppBadge {
    param($Row)
    if ($Row.Installed) {
        $Row.InstalledBadge.Visibility = "Visible"
    }
    else {
        $Row.InstalledBadge.Visibility = "Collapsed"
    }
    if ($Row.UpdateAvailable) {
        $Row.UpdateBadge.Visibility = "Visible"
    }
    else {
        $Row.UpdateBadge.Visibility = "Collapsed"
    }
}

$script:WinToolDetectTimeoutSeconds = 300

function Start-WinToolAppDetection {
    if ($null -ne $script:WinToolState.DetectJob) {
        return
    }
    $status = Get-WinToolUi -Name "AppInstalledStatus"
    $candidates = @(Get-WinToolWingetCandidate)
    if ($candidates.Count -eq 0) {
        $status.Text = "winget not found, so installed apps cannot be checked."
        Write-WinToolLog -Message "Installed apps: winget.exe was not found on this PC." -Level "warn" -Diagnostic
        return
    }
    $status.Text = "Checking installed apps..."
    Write-WinToolLog -Message ("Installed apps: checking with winget. Candidates: " + ($candidates -join "; ")) -Level "info" -Diagnostic
    $exportPath = Join-Path ([System.IO.Path]::GetTempPath()) ("WinTool-installed-" + [guid]::NewGuid().ToString("N") + ".json")
    $job = Start-WinToolScriptJob -ScriptText (Get-WinToolAppDetectionScript) -Argument @($candidates, $exportPath)
    $job | Add-Member -NotePropertyName Started -NotePropertyValue ([DateTime]::UtcNow)
    $script:WinToolState.DetectJob = $job
}

function Test-WinToolAppDetectionTimeout {
    $job = $script:WinToolState.DetectJob
    if ($null -eq $job -or $job.Sync.Done) {
        return
    }
    if (([DateTime]::UtcNow - $job.Started).TotalSeconds -lt $script:WinToolDetectTimeoutSeconds) {
        return
    }
    Write-WinToolDetectionLog -Job $job
    Stop-WinToolThread -Job $job
    $script:WinToolState.DetectJob = $null
    (Get-WinToolUi -Name "AppInstalledStatus").Text = "Checking installed apps took too long. Press Refresh to try again."
    Write-WinToolLog -Message ("Installed apps: winget did not finish in {0} seconds, so the check was stopped." -f $script:WinToolDetectTimeoutSeconds) -Level "warn" -Diagnostic
}

function Write-WinToolDetectionLog {
    param($Job)
    if ($null -eq $Job -or $null -eq $Job.Sync.Log) {
        return
    }
    foreach ($line in @($Job.Sync.Log.ToArray())) {
        Write-WinToolLog -Message ("Installed apps: " + [string]$line) -Level "info" -Diagnostic
    }
}

function Complete-WinToolAppDetection {
    $job = $script:WinToolState.DetectJob
    if ($null -eq $job) {
        return
    }
    $ok = [bool]$job.Sync.Ok
    $errorMessage = [string]$job.Sync.Error
    $exportText = [string]$job.Sync.ExportText
    $listText = [string]$job.Sync.ListText
    $upgradeText = [string]$job.Sync.UpgradeText
    $winget = [string]$job.Sync.Winget
    $displayNames = @()
    if ($null -ne $job.Sync.DisplayNames) {
        $displayNames = [string[]]$job.Sync.DisplayNames
    }
    Write-WinToolDetectionLog -Job $job
    Stop-WinToolThread -Job $job
    $script:WinToolState.DetectJob = $null
    $status = Get-WinToolUi -Name "AppInstalledStatus"
    if (-not $ok) {
        $status.Text = "Could not check installed apps. See the log."
        Write-WinToolLog -Message ("Could not check installed apps. {0}" -f $errorMessage) -Level "warn" -Diagnostic
        return
    }
    if (-not [string]::IsNullOrWhiteSpace($winget)) {
        $script:WinToolWingetWorking = $winget
    }
    $installedIds = @()
    try {
        $installedIds = @(ConvertFrom-WinToolWingetExport -Text $exportText)
    }
    catch {
        Write-WinToolLog -Message ("Installed apps: could not read the winget export file. {0}" -f $_.Exception.Message) -Level "warn" -Diagnostic
    }
    Write-WinToolLog -Message ("Installed apps: winget export listed {0} packages." -f $installedIds.Count) -Level "info" -Diagnostic
    $counts = Set-WinToolAppState -InstalledId $installedIds -UpgradeText $upgradeText -ListText $listText -DisplayName $displayNames
    if (@($counts.ByName).Count -gt 0) {
        Write-WinToolLog -Message ("Installed apps: found by name, outside winget: " + (@($counts.ByName) -join ", ")) -Level "info" -Diagnostic
    }
    Write-WinToolLog -Message ("Installed apps: {0} catalog apps installed, {1} with an update." -f $counts.Installed, $counts.Updates) -Level "ok" -Diagnostic
    Write-WinToolLog -Message ("Installed apps: marked installed: " + (@($counts.InstalledIds) -join ", ")) -Level "info" -Diagnostic
    if (@($counts.UpdateIds).Count -gt 0) {
        Write-WinToolLog -Message ("Installed apps: update available: " + (@($counts.UpdateIds) -join ", ")) -Level "info" -Diagnostic
    }
    if ($counts.Installed -eq 0 -and $installedIds.Count -eq 0 -and [string]::IsNullOrWhiteSpace($listText)) {
        $status.Text = "winget returned nothing. See the log."
    }
}

function Set-WinToolAppState {
    param(
        [string[]]$InstalledId,
        [AllowEmptyString()][string]$UpgradeText,
        [AllowEmptyString()][string]$ListText,
        [string[]]$DisplayName = @()
    )
    $catalogIds = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($script:WinToolState.AppRows)) {
        $catalogIds.Add([string]$row.WingetId)
    }
    $state = Resolve-WinToolAppState -CatalogId $catalogIds.ToArray() -InstalledId $InstalledId -UpgradeText $UpgradeText -ListText $ListText
    $byName = New-Object System.Collections.Generic.List[string]
    foreach ($id in @(Find-WinToolAppByName -DisplayName $DisplayName -App @($script:WinToolState.AppRows))) {
        if (-not $state.Installed.ContainsKey($id)) {
            $state.Installed[$id] = $true
            $byName.Add($id)
        }
    }
    $installedCount = 0
    $updateCount = 0
    $installedIds = New-Object System.Collections.Generic.List[string]
    $updateIds = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($script:WinToolState.AppRows)) {
        $row.Installed = $state.Installed.ContainsKey([string]$row.WingetId)
        $row.UpdateAvailable = $state.Updates.ContainsKey([string]$row.WingetId)
        if ($row.Installed) { $installedCount++; $installedIds.Add([string]$row.WingetId) }
        if ($row.UpdateAvailable) { $updateCount++; $updateIds.Add([string]$row.WingetId) }
        Sync-WinToolAppBadge -Row $row
    }
    (Get-WinToolUi -Name "AppInstalledStatus").Text = ("{0} installed, {1} with an update." -f $installedCount, $updateCount)
    return [pscustomobject]@{ Installed = $installedCount; Updates = $updateCount; ByName = $byName.ToArray(); InstalledIds = $installedIds.ToArray(); UpdateIds = $updateIds.ToArray() }
}

function Select-WinToolInstalledApp {
    $ids = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($script:WinToolState.AppRows)) {
        if ($row.Installed) {
            $ids.Add([string]$row.Id)
        }
    }
    if ($ids.Count -eq 0) {
        Write-WinToolLog -Message "No installed catalog apps were found yet. Press Check installed first." -Level "warn"
    }
    Sync-WinToolAppCheck -Id $ids.ToArray() -OnlyThese
}

function Invoke-WinToolAppAction {
    param(
        $App,
        [Parameter(Mandatory = $true)][ValidateSet("upgrade", "uninstall")][string]$Action
    )
    $apps = @($App)
    if ($apps.Count -eq 0) {
        Write-WinToolLog -Message "Select at least one app first." -Level "warn"
        return
    }
    $verb = "Update"
    if ($Action -eq "uninstall") {
        $verb = "Uninstall"
    }
    $names = @($apps | Select-Object -First 8 | ForEach-Object { [string]$_.Name }) -join ", "
    if ($apps.Count -gt 8) {
        $names += ", ..."
    }
    $ok = Request-WinToolConfirmation -Message ("{0} {1} app(s) with winget?`n`n{2}" -f $verb, $apps.Count, $names) -Title ($verb + " apps")
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolAppPlan -App $apps -Action $Action)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage ("{0} finished." -f $verb) -AfterDone "Start-WinToolAppDetection"
}

function Invoke-WinToolUpgradeAllClick {
    $ok = Request-WinToolConfirmation -Message "Update every app that winget can update, including apps that are not in this list?" -Title "Update all apps"
    if (-not $ok) {
        return
    }
    Invoke-WinToolPlanAsync -Step @(Get-WinToolUpgradeAllPlan) -DoneMessage "Update all finished." -AfterDone "Start-WinToolAppDetection"
}

function Sync-WinToolAppToggle {
    param($CategoryRow)
    if ($CategoryRow.Updating) {
        return
    }
    Sync-WinToolCategoryCheck -CategoryRow $CategoryRow
    Sync-WinToolAppCount
}

function Sync-WinToolCategoryFromHeader {
    param($CategoryRow)
    if ($CategoryRow.Updating) {
        return
    }
    $target = $false
    if ($CategoryRow.SelectAll.IsChecked -eq $true) {
        $target = $true
    }
    $CategoryRow.Updating = $true
    foreach ($app in @($CategoryRow.Apps)) {
        if ($app.Panel.Visibility -eq "Visible") {
            $app.Checkbox.IsChecked = $target
        }
    }
    $CategoryRow.Updating = $false
    Sync-WinToolAppCount
}

function Sync-WinToolCategoryCheck {
    param($CategoryRow)
    $visible = @($CategoryRow.Apps | Where-Object { $_.Panel.Visibility -eq "Visible" })
    $CategoryRow.Updating = $true
    if ($visible.Count -eq 0) {
        $CategoryRow.SelectAll.IsChecked = $false
    }
    else {
        $selected = @($visible | Where-Object { $_.Checkbox.IsChecked -eq $true })
        if ($selected.Count -eq 0) {
            $CategoryRow.SelectAll.IsChecked = $false
        }
        elseif ($selected.Count -eq $visible.Count) {
            $CategoryRow.SelectAll.IsChecked = $true
        }
        else {
            $CategoryRow.SelectAll.IsChecked = $null
        }
    }
    $CategoryRow.Updating = $false
}

function Sync-WinToolAppCount {
    $selected = @(Get-WinToolCheckedApp)
    (Get-WinToolUi -Name "AppCount").Text = "{0} selected" -f $selected.Count
}

function Update-WinToolAppFilter {
    $query = [string](Get-WinToolUi -Name "AppSearch").Text
    $any = $false
    foreach ($category in @($script:WinToolState.CategoryRows)) {
        $visible = 0
        foreach ($app in @($category.Apps)) {
            if (Test-WinToolTextMatch -Haystack $app.SearchText -Query $query) {
                $app.Panel.Visibility = "Visible"
                $visible++
                $any = $true
            }
            else {
                $app.Panel.Visibility = "Collapsed"
            }
        }
        if ($visible -eq 0) {
            $category.Card.Visibility = "Collapsed"
        }
        else {
            $category.Card.Visibility = "Visible"
            Sync-WinToolCategoryCheck -CategoryRow $category
        }
    }
    $empty = Get-WinToolUi -Name "AppEmpty"
    if ($any) {
        $empty.Visibility = "Collapsed"
    }
    else {
        $empty.Visibility = "Visible"
    }
}

function Get-WinToolCheckedApp {
    $selected = New-Object System.Collections.Generic.List[object]
    foreach ($row in @($script:WinToolState.AppRows)) {
        if ($row.Checkbox.IsChecked -eq $true) {
            $selected.Add($row)
        }
    }
    return $selected.ToArray()
}

function Sync-WinToolAppCheck {
    param(
        [string[]]$Id,
        [switch]$OnlyThese
    )
    $wanted = @{}
    foreach ($item in @($Id)) {
        if (-not [string]::IsNullOrWhiteSpace($item)) {
            $wanted[$item] = $true
        }
    }
    foreach ($row in @($script:WinToolState.AppRows)) {
        $shouldCheck = $wanted.ContainsKey([string]$row.Id)
        if ($OnlyThese -or $shouldCheck) {
            $row.Checkbox.IsChecked = $shouldCheck
        }
    }
    foreach ($category in @($script:WinToolState.CategoryRows)) {
        Sync-WinToolCategoryCheck -CategoryRow $category
    }
    Sync-WinToolAppCount
}

function Invoke-WinToolInstallClick {
    $apps = @(Get-WinToolCheckedApp)
    if ($apps.Count -eq 0) {
        Write-WinToolLog -Message "Select at least one app first." -Level "warn"
        return
    }
    $ok = Request-WinToolConfirmation -Message ("Install {0} app(s) with winget? Each vendor's license is accepted for you by winget." -f $apps.Count) -Title "Install apps"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolAppPlan -App $apps)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "App install finished. Open a new terminal if a command is not on PATH yet." -AfterDone "Start-WinToolAppDetection"
}
# endregion

# region src/UI/TweaksView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolTweakView {
    $catalog = Get-WinToolTweakCatalog
    $presetPanel = Get-WinToolUi -Name "TweakPresets"
    $presetPanel.Children.Clear()
    foreach ($preset in @(Get-WinToolNote -Object $catalog -Name "presets" -Default @())) {
        $button = New-Object System.Windows.Controls.Button
        $button.Content = [string]$preset.name
        $button.Style = $script:WinToolWindow.FindResource("SecondaryButton")
        $button.Margin = [System.Windows.Thickness]::new(0, 0, 8, 0)
        $button.ToolTip = [string](Get-WinToolNote -Object $preset -Name "description" -Default "")
        Register-WinToolUiEvent -Control $button -EventName "Click" -Name "Tweaks: preset" -Data $preset -Action {
            param($source, $eventData, $boundPreset)
            $null = $source, $eventData
            Select-WinToolPreset -Preset $boundPreset
        }
        [void]$presetPanel.Children.Add($button)
    }

    $hostPanel = Get-WinToolUi -Name "TweakCategories"
    $hostPanel.Children.Clear()
    $script:WinToolState.TweakRows = @()
    $script:WinToolState.TweakGroups = @()
    $groups = @{}
    $order = New-Object System.Collections.Generic.List[string]
    foreach ($tweak in @(Get-WinToolNote -Object $catalog -Name "tweaks" -Default @())) {
        $categoryName = [string](Get-WinToolNote -Object $tweak -Name "category" -Default "Other")
        if ([string]::IsNullOrWhiteSpace($categoryName)) {
            $categoryName = "Other"
        }
        if (-not $groups.ContainsKey($categoryName)) {
            $groups[$categoryName] = New-Object System.Collections.Generic.List[object]
            [void]$order.Add($categoryName)
        }
        [void]$groups[$categoryName].Add($tweak)
    }

    # ToArray() keeps this on object[], which Windows PowerShell 5.1 can enumerate.
    # @() around a generic list throws "Argument types do not match" on 5.1.
    foreach ($categoryName in $order.ToArray()) {
        $card = New-WinToolCard
        $stack = New-Object System.Windows.Controls.StackPanel
        [void]$stack.Children.Add((New-WinToolText -Text $categoryName -Size 18 -Weight "SemiBold" -Margin ([System.Windows.Thickness]::new(0, 0, 0, 10))))
        $rows = @()
        $tweaksInCategory = $groups[$categoryName].ToArray()
        foreach ($tweak in $tweaksInCategory) {
            $row = New-WinToolTweakRow -Tweak $tweak -CategoryName $categoryName
            [void]$stack.Children.Add($row.Panel)
            $rows += $row
            $script:WinToolState.TweakRows += $row
        }
        $card.Child = $stack
        [void]$hostPanel.Children.Add($card)
        $script:WinToolState.TweakGroups += [pscustomobject]@{
            Name = $categoryName
            Card = $card
            Rows = $rows
        }
    }

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TweakSearch") -EventName "TextChanged" -Name "Tweaks: search" -Action {
        Sync-WinToolSearchHint -BoxName "TweakSearch" -HintName "TweakSearchHint"
        Update-WinToolTweakFilter
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TweakClear") -EventName "Click" -Name "Tweaks: clear" -Action {
        Sync-WinToolTweakCheck -Id @() -OnlyThese
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TweakApply") -EventName "Click" -Name "Tweaks: apply selected" -Action {
        Invoke-WinToolTweakClick -Direction "Apply"
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TweakUndo") -EventName "Click" -Name "Tweaks: undo selected" -Action {
        Invoke-WinToolTweakClick -Direction "Undo"
    }
}

function New-WinToolTweakRow {
    param(
        $Tweak,
        [string]$CategoryName
    )
    $panel = New-Object System.Windows.Controls.Grid
    $panel.Margin = [System.Windows.Thickness]::new(0, 0, 0, 12)
    $panel.ColumnDefinitions.Add((New-WinToolColumn -Auto))
    $panel.ColumnDefinitions.Add((New-WinToolColumn))

    $checkbox = New-Object System.Windows.Controls.CheckBox
    $checkbox.VerticalAlignment = "Top"
    $checkbox.Margin = [System.Windows.Thickness]::new(0, 3, 10, 0)
    [System.Windows.Controls.Grid]::SetColumn($checkbox, 0)
    [void]$panel.Children.Add($checkbox)

    $text = New-Object System.Windows.Controls.StackPanel
    $title = New-Object System.Windows.Controls.StackPanel
    $title.Orientation = "Horizontal"
    [void]$title.Children.Add((New-WinToolText -Text ([string]$Tweak.name) -Weight "SemiBold"))
    $risk = [string](Get-WinToolNote -Object $Tweak -Name "risk" -Default "safe")
    $badgeText = "Safe"
    if ($risk -eq "caution") {
        $badgeText = "Caution"
    }
    [void]$title.Children.Add((New-WinToolBadge -Text $badgeText -Kind $risk))
    [void]$text.Children.Add($title)
    [void]$text.Children.Add((New-WinToolText -Text ([string]$Tweak.description) -Size 13 -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 4, 0, 0))))
    [System.Windows.Controls.Grid]::SetColumn($text, 1)
    [void]$panel.Children.Add($text)

    $search = (@([string]$Tweak.name, [string]$Tweak.description, [string]$Tweak.id, $CategoryName) -join " ")
    return [pscustomobject]@{
        Id = [string]$Tweak.id
        SearchText = $search
        Panel = $panel
        Checkbox = $checkbox
        Tweak = $Tweak
    }
}

function Get-WinToolCheckedTweak {
    $selected = New-Object System.Collections.Generic.List[object]
    foreach ($row in @($script:WinToolState.TweakRows)) {
        if ($row.Checkbox.IsChecked -eq $true) {
            $selected.Add($row.Tweak)
        }
    }
    return $selected.ToArray()
}

function Sync-WinToolTweakCheck {
    param(
        [string[]]$Id,
        [switch]$OnlyThese
    )
    $wanted = @{}
    foreach ($item in @($Id)) {
        if (-not [string]::IsNullOrWhiteSpace($item)) {
            $wanted[$item] = $true
        }
    }
    foreach ($row in @($script:WinToolState.TweakRows)) {
        $shouldCheck = $wanted.ContainsKey([string]$row.Id)
        if ($OnlyThese -or $shouldCheck) {
            $row.Checkbox.IsChecked = $shouldCheck
        }
    }
}

function Select-WinToolPreset {
    param($Preset)
    $catalog = Get-WinToolTweakCatalog
    $matched = @(Get-WinToolPresetTweak -Catalog $catalog -PresetId ([string]$Preset.id))
    $ids = New-Object System.Collections.Generic.List[string]
    foreach ($tweak in $matched) {
        $ids.Add([string]$tweak.id)
    }
    Sync-WinToolTweakCheck -Id $ids.ToArray() -OnlyThese
    Write-WinToolLog -Message ("Selected the {0} preset ({1} tweaks)." -f [string]$Preset.name, $ids.Count) -Level "info"
}

function Update-WinToolTweakFilter {
    $query = [string](Get-WinToolUi -Name "TweakSearch").Text
    $any = $false
    foreach ($group in @($script:WinToolState.TweakGroups)) {
        $visible = 0
        foreach ($row in @($group.Rows)) {
            if (Test-WinToolTextMatch -Haystack $row.SearchText -Query $query) {
                $row.Panel.Visibility = "Visible"
                $visible++
                $any = $true
            }
            else {
                $row.Panel.Visibility = "Collapsed"
            }
        }
        if ($visible -eq 0) {
            $group.Card.Visibility = "Collapsed"
        }
        else {
            $group.Card.Visibility = "Visible"
        }
    }
    $empty = Get-WinToolUi -Name "TweakEmpty"
    if ($any) {
        $empty.Visibility = "Collapsed"
    }
    else {
        $empty.Visibility = "Visible"
    }
}

function Invoke-WinToolTweakClick {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("Apply", "Undo")][string]$Direction
    )
    $tweaks = @(Get-WinToolCheckedTweak)
    if ($tweaks.Count -eq 0) {
        Write-WinToolLog -Message "Select at least one tweak first." -Level "warn"
        return
    }
    $verb = "Apply"
    if ($Direction -eq "Undo") {
        $verb = "Undo"
    }
    $ok = Request-WinToolConfirmation -Message ("{0} {1} tweak(s)? WinTool will create a restore point first." -f $verb, $tweaks.Count) -Title "Tweaks"
    if (-not $ok) {
        return
    }
    $script:WinToolState.PendingTweaks = $tweaks
    $script:WinToolState.PendingDirection = $Direction
    $script:WinToolState.PendingRestart = ((Get-WinToolUi -Name "TweakRestartExplorer").IsChecked -eq $true)
    Sync-WinToolBusyState -Busy $true
    Sync-WinToolProgress -Value 0 -Text "Creating a restore point" -Indeterminate $true
    Write-WinToolLog -Message "Creating a restore point. This can take a minute." -Level "info"
    $description = "WinTool before tweaks"
    if ($Direction -eq "Undo") {
        $description = "WinTool before undo"
    }
    $script:WinToolState.RestoreJob = Start-WinToolRestorePointJob -Description $description
}

function Complete-WinToolRestorePoint {
    param(
        [bool]$Ok,
        [string]$ErrorMessage
    )
    if (-not $Ok) {
        $continue = Request-WinToolConfirmation -Message ("A restore point was not created.`n`n{0}`n`nContinue anyway?" -f $ErrorMessage) -Title "Restore point"
        if (-not $continue) {
            Sync-WinToolBusyState -Busy $false
            Sync-WinToolProgress -Value 0 -Text "Ready" -Indeterminate $false
            Write-WinToolLog -Message "Tweaks were not changed." -Level "warn"
            return
        }
        Write-WinToolLog -Message "Continuing without a restore point." -Level "warn"
    }
    else {
        Write-WinToolLog -Message "Restore point created." -Level "ok"
    }
    try {
        Invoke-WinToolTweakChange -Tweak $script:WinToolState.PendingTweaks -Direction $script:WinToolState.PendingDirection -RestartExplorer ([bool]$script:WinToolState.PendingRestart)
        Write-WinToolLog -Message "Tweaks finished." -Level "ok"
        Sync-WinToolProgress -Value 100 -Text "Tweaks finished" -Indeterminate $false
    }
    catch {
        Write-WinToolLog -Message ("Tweaks failed. {0}" -f $_.Exception.Message) -Level "error"
        Sync-WinToolProgress -Value 0 -Text "Ready" -Indeterminate $false
    }
    Sync-WinToolBusyState -Busy $false
}
# endregion

# region src/UI/TerminalView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Get-WinToolActiveFont {
    $rows = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($item in @(Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "fonts" -Default @())) {
        $rows.Add($item)
        $seen[[string]$item.id] = $true
    }
    foreach ($item in @($script:WinToolExtraFont)) {
        if (-not $seen.ContainsKey([string]$item.id)) {
            $rows.Add($item)
        }
    }
    return $rows.ToArray()
}

function Get-WinToolActiveOhMyPoshTheme {
    $rows = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($item in @(Get-WinToolNote -Object (Get-WinToolOhMyPoshDocument) -Name "themes" -Default @())) {
        $rows.Add($item)
        $seen[[string]$item.id] = $true
    }
    foreach ($item in @($script:WinToolExtraOhMyPoshTheme)) {
        if (-not $seen.ContainsKey([string]$item.id)) {
            $rows.Add($item)
        }
    }
    return $rows.ToArray()
}

function Initialize-WinToolTerminalView {
    $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
    $script:WinToolTerminalMode = "simple"
    $script:WinToolExtraFont = @()
    $script:WinToolExtraOhMyPoshTheme = @()
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalModeSimple") -EventName "Checked" -Name "Terminal: Simple mode" -Action {
        $script:WinToolTerminalMode = "simple"
        (Get-WinToolUi -Name "TerminalAdvancedHost").Visibility = "Collapsed"
        (Get-WinToolUi -Name "TerminalSimpleHost").Visibility = "Visible"
        $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
        Update-WinToolTerminalSummary
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalModeAdvanced") -EventName "Checked" -Name "Terminal: Advanced mode" -Action {
        $script:WinToolTerminalMode = "advanced"
        (Get-WinToolUi -Name "TerminalSimpleHost").Visibility = "Collapsed"
        (Get-WinToolUi -Name "TerminalAdvancedHost").Visibility = "Visible"
        Update-WinToolTerminalSummary
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalFontSearch") -EventName "TextChanged" -Name "Terminal: font search" -Action {
        Sync-WinToolSearchHint -BoxName "TerminalFontSearch" -HintName "TerminalFontSearchHint"
        Update-WinToolFontList
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalFontNerdOnly") -EventName "Click" -Name "Terminal: Nerd Fonts only" -Action { Update-WinToolFontList }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalThemeSearch") -EventName "TextChanged" -Name "Terminal: theme search" -Action {
        Sync-WinToolSearchHint -BoxName "TerminalThemeSearch" -HintName "TerminalThemeSearchHint"
        Update-WinToolPromptStyleList
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalRefresh") -EventName "Click" -Name "Terminal: refresh lists" -Action { Update-WinToolTerminalCatalogOnline }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalSetup") -EventName "Click" -Name "Terminal: apply setup" -Action { Invoke-WinToolTerminalClick }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalFontList") -EventName "SelectionChanged" -Name "Terminal: choose font" -Action {
        Update-WinToolFontSample
        Update-WinToolTerminalSummary
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalStyleList") -EventName "SelectionChanged" -Name "Terminal: choose prompt style" -Action {
        Update-WinToolTerminalSummary
    }
    Build-WinToolSimpleTerminalCard
    Build-WinToolPromptCard
    Build-WinToolExtraToggle
    Build-WinToolSchemeCard
    Update-WinToolFontList
    Update-WinToolPromptStyleList
    Update-WinToolTerminalSummary
}

function Build-WinToolSimpleTerminalCard {
    $hostPanel = Get-WinToolUi -Name "TerminalSimpleHost"
    $hostPanel.Children.Clear()
    $card = New-WinToolCard
    $stack = New-Object System.Windows.Controls.StackPanel
    [void]$stack.Children.Add((New-WinToolText -Text "Recommended setup" -Size 18 -Weight "SemiBold"))
    [void]$stack.Children.Add((New-WinToolText -Text "Windows Terminal, PowerShell 7, Oh My Posh with the Jan De Dobbeleer theme, a Nerd Font, file icons, and history suggestions. You can change any of this in Advanced." -Size 13 -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 6, 0, 8))))
    [void]$stack.Children.Add((New-WinToolTerminalPreview -Segments @(
        [pscustomobject]@{ text = "~/src "; color = "#6C9BFF" },
        [pscustomobject]@{ text = "main "; color = "#3DDC97" },
        [pscustomobject]@{ text = ">"; color = "#E8EDF7" }
    )))
    $card.Child = $stack
    [void]$hostPanel.Children.Add($card)
}

function Build-WinToolPromptCard {
    $hostPanel = Get-WinToolUi -Name "TerminalPromptHost"
    $hostPanel.Children.Clear()
    $catalog = Get-WinToolTerminalCatalog
    foreach ($prompt in @(Get-WinToolNote -Object $catalog -Name "prompts" -Default @())) {
        $card = New-WinToolCard
        $card.Margin = [System.Windows.Thickness]::new(0, 0, 12, 12)
        $card.Width = 280
        $card.Cursor = [System.Windows.Input.Cursors]::Hand
        $card.Tag = [string]$prompt.id
        $stack = New-Object System.Windows.Controls.StackPanel
        [void]$stack.Children.Add((New-WinToolText -Text ([string]$prompt.name) -Size 16 -Weight "SemiBold"))
        [void]$stack.Children.Add((New-WinToolText -Text ([string]$prompt.summary) -Size 13 -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 4, 0, 8))))
        $installs = @($prompt.installs) -join ", "
        [void]$stack.Children.Add((New-WinToolText -Text ("Installs: " + $installs) -Size 12 -Brush "BrushMuted" -Wrap))
        $card.Child = $stack
        Register-WinToolUiEvent -Control $card -EventName "MouseLeftButtonUp" -Name "Terminal: choose prompt" -Data ([string]$prompt.id) -Action {
            param($source, $eventData, $promptId)
            $null = $source, $eventData
            Set-WinToolTerminalChoiceValue -Name "prompt" -Value $promptId
            Update-WinToolPromptStyleList
            Update-WinToolTerminalSummary
            Update-WinToolPromptSelection
        }
        [void]$hostPanel.Children.Add($card)
    }
    Update-WinToolPromptSelection
}

function Set-WinToolTerminalChoiceValue {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        $Value
    )
    if ($null -eq $script:WinToolTerminalChoice) {
        $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
    }
    $script:WinToolTerminalChoice.$Name = $Value
}

function Update-WinToolPromptSelection {
    $selected = [string]$script:WinToolTerminalChoice.prompt
    $hostPanel = Get-WinToolUi -Name "TerminalPromptHost"
    for ($index = 0; $index -lt $hostPanel.Children.Count; $index++) {
        $card = $hostPanel.Children[$index]
        if ([string]$card.Tag -eq $selected) {
            $card.BorderThickness = [System.Windows.Thickness]::new(2)
            $card.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushAccent")
        }
        else {
            $card.BorderThickness = [System.Windows.Thickness]::new(1)
            $card.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
        }
    }
}

function Update-WinToolPromptStyleList {
    $list = Get-WinToolUi -Name "TerminalStyleList"
    $list.Items.Clear()
    $prompt = [string]$script:WinToolTerminalChoice.prompt
    $query = [string](Get-WinToolUi -Name "TerminalThemeSearch").Text
    $note = Get-WinToolUi -Name "TerminalStyleNote"
    if ($prompt -eq "oh-my-posh") {
        $note.Text = "Official Oh My Posh themes. Search to narrow the gallery."
        foreach ($theme in @(Get-WinToolActiveOhMyPoshTheme)) {
            $hay = ([string]$theme.name) + " " + ([string]$theme.file)
            if (-not (Test-WinToolTextMatch -Haystack $hay -Query $query)) { continue }
            $item = New-Object System.Windows.Controls.ListBoxItem
            $item.Content = [string]$theme.name
            $item.Tag = [string]$theme.id
            [void]$list.Items.Add($item)
            if ([string]$theme.id -eq [string]$script:WinToolTerminalChoice.promptStyle) {
                $list.SelectedItem = $item
            }
        }
    }
    elseif ($prompt -eq "starship") {
        $note.Text = "Starship presets."
        foreach ($preset in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "starshipPresets" -Default @())) {
            $item = New-Object System.Windows.Controls.ListBoxItem
            $item.Content = [string]$preset.name
            $item.Tag = [string]$preset.id
            [void]$list.Items.Add($item)
            if ([string]$preset.id -eq [string]$script:WinToolTerminalChoice.promptStyle) {
                $list.SelectedItem = $item
            }
        }
    }
    elseif ($prompt -eq "oh-my-zsh") {
        $note.Text = "Themes that ship with Oh My Zsh."
        foreach ($name in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "omzThemes" -Default @())) {
            if (-not (Test-WinToolTextMatch -Haystack ([string]$name) -Query $query)) { continue }
            $item = New-Object System.Windows.Controls.ListBoxItem
            $item.Content = [string]$name
            $item.Tag = [string]$name
            [void]$list.Items.Add($item)
        }
    }
    else {
        $note.Text = "This prompt has its own default look. The font and extras below still apply."
    }
    if ($null -eq $list.SelectedItem -and $list.Items.Count -gt 0) {
        $list.SelectedIndex = 0
    }
}

function Build-WinToolExtraToggle {
    $hostPanel = Get-WinToolUi -Name "TerminalExtrasHost"
    $hostPanel.Children.Clear()
    foreach ($extra in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "extras" -Default @())) {
        $box = New-Object System.Windows.Controls.CheckBox
        $box.Content = ([string]$extra.name) + "  -  " + ([string]$extra.description)
        $box.Margin = [System.Windows.Thickness]::new(0, 0, 0, 8)
        $box.Tag = [string]$extra.id
        $box.IsChecked = $false
        if ([string]$extra.id -eq "terminal-icons" -or [string]$extra.id -eq "psreadline") {
            $box.IsChecked = $true
        }
        Register-WinToolUiEvent -Control $box -EventName "Click" -Name "Terminal: extras" -Action { Update-WinToolTerminalSummary }
        [void]$hostPanel.Children.Add($box)
    }
}

function Build-WinToolSchemeCard {
    $hostPanel = Get-WinToolUi -Name "TerminalSchemeHost"
    $hostPanel.Children.Clear()
    foreach ($scheme in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "schemes" -Default @())) {
        $card = New-WinToolCard
        $card.Width = 180
        $card.Margin = [System.Windows.Thickness]::new(0, 0, 12, 0)
        $card.Cursor = [System.Windows.Input.Cursors]::Hand
        $card.Tag = [string]$scheme.id
        $swatch = New-Object System.Windows.Controls.Border
        $swatch.Height = 36
        $swatch.CornerRadius = [System.Windows.CornerRadius]::new(8)
        $swatchColor = [System.Windows.Media.Color]([System.Windows.Media.ColorConverter]::ConvertFromString([string]$scheme.background))
        $swatch.Background = [System.Windows.Media.SolidColorBrush]::new($swatchColor)
        $swatch.Margin = [System.Windows.Thickness]::new(0, 8, 0, 0)
        $stack = New-Object System.Windows.Controls.StackPanel
        [void]$stack.Children.Add((New-WinToolText -Text ([string]$scheme.name) -Weight "SemiBold"))
        [void]$stack.Children.Add($swatch)
        $card.Child = $stack
        Register-WinToolUiEvent -Control $card -EventName "MouseLeftButtonUp" -Name "Terminal: choose color scheme" -Data ([string]$scheme.id) -Action {
            param($source, $eventData, $schemeId)
            $null = $source, $eventData
            Set-WinToolTerminalChoiceValue -Name "schemeId" -Value $schemeId
            Update-WinToolTerminalSummary
        }
        [void]$hostPanel.Children.Add($card)
    }
}

function Update-WinToolFontList {
    $list = Get-WinToolUi -Name "TerminalFontList"
    $list.Items.Clear()
    $query = [string](Get-WinToolUi -Name "TerminalFontSearch").Text
    $nerdOnly = ((Get-WinToolUi -Name "TerminalFontNerdOnly").IsChecked -eq $true)
    $fonts = @(Select-WinToolFont -Font (Get-WinToolActiveFont) -Query $query -NerdOnly $nerdOnly)
    foreach ($font in $fonts) {
        $item = New-Object System.Windows.Controls.ListBoxItem
        $badge = "Programming font"
        if ($font.nerd) { $badge = "Nerd Font" }
        $item.Content = ([string]$font.name) + "   " + $badge
        $item.Tag = [string]$font.id
        [void]$list.Items.Add($item)
        if ([string]$font.id -eq [string]$script:WinToolTerminalChoice.fontId) {
            $list.SelectedItem = $item
        }
    }
    if ($null -eq $list.SelectedItem -and $list.Items.Count -gt 0) {
        $list.SelectedIndex = 0
    }
    Update-WinToolFontSample
}

function Update-WinToolFontSample {
    $sample = Get-WinToolUi -Name "TerminalFontSample"
    $fontId = [string]$script:WinToolTerminalChoice.fontId
    $list = Get-WinToolUi -Name "TerminalFontList"
    if ($null -ne $list.SelectedItem) {
        $fontId = [string]$list.SelectedItem.Tag
        $script:WinToolTerminalChoice.fontId = $fontId
    }
    $font = $null
    foreach ($item in @(Get-WinToolActiveFont)) {
        if ([string]$item.id -eq $fontId) { $font = $item; break }
    }
    if ($null -eq $font) {
        $sample.Text = "Select a font to preview it."
        return
    }
    $sample.FontFamily = [string]$font.face
    $text = [string](Get-WinToolNote -Object $font -Name "sample" -Default "The quick brown fox jumps over the lazy dog.")
    $sample.Text = $text + "`n" + [string]$font.face
}

function Read-WinToolExtraSelection {
    $hostPanel = Get-WinToolUi -Name "TerminalExtrasHost"
    $flags = @{ terminalIcons = $false; psReadLine = $false; zoxide = $false; fzf = $false }
    for ($index = 0; $index -lt $hostPanel.Children.Count; $index++) {
        $box = $hostPanel.Children[$index]
        $flags[[string]$box.Tag] = ($box.IsChecked -eq $true)
    }
    return $flags
}

function Update-WinToolTerminalSummary {
    if ($script:WinToolTerminalMode -eq "advanced") {
        $list = Get-WinToolUi -Name "TerminalStyleList"
        if ($null -ne $list.SelectedItem) {
            $script:WinToolTerminalChoice.promptStyle = [string]$list.SelectedItem.Tag
        }
        $fonts = Get-WinToolUi -Name "TerminalFontList"
        if ($null -ne $fonts.SelectedItem) {
            $script:WinToolTerminalChoice.fontId = [string]$fonts.SelectedItem.Tag
        }
        $flags = Read-WinToolExtraSelection
        $script:WinToolTerminalChoice.terminalIcons = [bool]$flags["terminal-icons"]
        $script:WinToolTerminalChoice.psReadLine = [bool]$flags["psreadline"]
        $script:WinToolTerminalChoice.zoxide = [bool]$flags["zoxide"]
        $script:WinToolTerminalChoice.fzf = [bool]$flags["fzf"]
    }
    $lines = @(Get-WinToolTerminalSummary -Selection $script:WinToolTerminalChoice)
    (Get-WinToolUi -Name "TerminalSummary").Text = ($lines -join "`n")
}

function New-WinToolTerminalPreview {
    param($Segments)
    $border = New-Object System.Windows.Controls.Border
    $border.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $border.Padding = [System.Windows.Thickness]::new(12)
    $border.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushLog")
    $text = New-Object System.Windows.Controls.TextBlock
    $text.FontFamily = "Consolas"
    $text.FontSize = 13
    $text.TextWrapping = "Wrap"
    foreach ($segment in @($Segments)) {
        $run = New-Object System.Windows.Documents.Run
        $run.Text = [string]$segment.text
        $runColor = [System.Windows.Media.Color]([System.Windows.Media.ColorConverter]::ConvertFromString([string]$segment.color))
        $run.Foreground = [System.Windows.Media.SolidColorBrush]::new($runColor)
        [void]$text.Inlines.Add($run)
    }
    $border.Child = $text
    return $border
}

function Update-WinToolTerminalCatalogOnline {
    Write-WinToolLog -Message "Refreshing Nerd Fonts and Oh My Posh themes from GitHub." -Level "info"
    try {
        $headers = @{ "User-Agent" = "WinTool"; "Accept" = "application/vnd.github+json" }
        $release = Invoke-RestMethod -Uri "https://api.github.com/repos/ryanoasis/nerd-fonts/releases/latest" -Headers $headers
        $known = @{}
        foreach ($font in @(Get-WinToolActiveFont)) {
            $asset = [string](Get-WinToolNote -Object $font -Name "asset" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($asset)) { $known[$asset] = $true }
        }
        $added = New-Object System.Collections.Generic.List[object]
        foreach ($asset in @($release.assets)) {
            $name = [string]$asset.name
            if (-not $name.EndsWith(".zip")) { continue }
            if ($name -eq "FontPatcher.zip" -or $name -eq "NerdFontsSymbolsOnly.zip") { continue }
            if ($known.ContainsKey($name)) { continue }
            $stem = [IO.Path]::GetFileNameWithoutExtension($name)
            $added.Add([pscustomobject]@{
                id = ($stem.ToLower() + "-nf")
                name = ($stem + " Nerd Font")
                face = ($stem + " Nerd Font")
                match = $stem
                nerd = $true
                source = "nerd-fonts"
                release = [string]$release.tag_name
                asset = $name
                sample = "agnoster ~/src main"
            })
        }
        $script:WinToolExtraFont = @($script:WinToolExtraFont) + @($added.ToArray())
        $themes = Invoke-RestMethod -Uri "https://api.github.com/repos/JanDeDobbeleer/oh-my-posh/contents/themes?ref=main" -Headers $headers
        $knownThemes = @{}
        foreach ($theme in @(Get-WinToolActiveOhMyPoshTheme)) { $knownThemes[[string]$theme.file] = $true }
        $extraThemes = New-Object System.Collections.Generic.List[object]
        foreach ($theme in @($themes)) {
            $file = [string]$theme.name
            if (-not $file.EndsWith(".omp.json")) { continue }
            if ($knownThemes.ContainsKey($file)) { continue }
            $id = $file.Substring(0, $file.Length - 9)
            $extraThemes.Add([pscustomobject]@{ id = $id; file = $file; name = $id })
        }
        $script:WinToolExtraOhMyPoshTheme = @($script:WinToolExtraOhMyPoshTheme) + @($extraThemes.ToArray())
        Update-WinToolFontList
        Update-WinToolPromptStyleList
        Write-WinToolLog -Message ("Catalog refresh added " + @($added.ToArray()).Count + " fonts and " + @($extraThemes.ToArray()).Count + " themes.") -Level "ok"
    }
    catch {
        Write-WinToolLog -Message ("Could not refresh the catalogs. The built-in lists are still available. " + $_.Exception.Message) -Level "warn"
    }
}

function Get-WinToolTerminalChoice {
    if ($null -eq $script:WinToolTerminalChoice) {
        $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
    }
    $enabled = $true
    $enabledBox = $script:WinToolWindow.FindName("TerminalEnabled")
    if ($null -ne $enabledBox) {
        $enabled = ($enabledBox.IsChecked -eq $true)
    }
    $choice = $script:WinToolTerminalChoice
    return [pscustomobject]@{
        enabled = $enabled
        prompt = [string]$choice.prompt
        promptStyle = [string]$choice.promptStyle
        fontId = [string]$choice.fontId
        schemeId = [string]$choice.schemeId
        terminalIcons = [bool]$choice.terminalIcons
        psReadLine = [bool]$choice.psReadLine
        zoxide = [bool]$choice.zoxide
        fzf = [bool]$choice.fzf
    }
}

function Sync-WinToolTerminalChoice {
    param($Selection)
    if ($null -eq $Selection) { return }
    if ($null -eq $script:WinToolTerminalChoice) {
        $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
    }
    $prompt = [string](Get-WinToolNote -Object $Selection -Name "prompt" -Default "")
    if (-not [string]::IsNullOrWhiteSpace($prompt)) { $script:WinToolTerminalChoice.prompt = $prompt }
    $style = [string](Get-WinToolNote -Object $Selection -Name "promptStyle" -Default "")
    if (-not [string]::IsNullOrWhiteSpace($style)) { $script:WinToolTerminalChoice.promptStyle = $style }
    $fontId = [string](Get-WinToolNote -Object $Selection -Name "fontId" -Default "")
    if (-not [string]::IsNullOrWhiteSpace($fontId)) { $script:WinToolTerminalChoice.fontId = $fontId }
    $icons = Get-WinToolNote -Object $Selection -Name "terminalIcons"
    if ($null -ne $icons) { $script:WinToolTerminalChoice.terminalIcons = [bool]$icons }
    (Get-WinToolUi -Name "TerminalModeAdvanced").IsChecked = $true
    Update-WinToolFontList
    Update-WinToolPromptStyleList
    Update-WinToolPromptSelection
    Update-WinToolTerminalSummary
}

function Invoke-WinToolTerminalClick {
    $choice = Get-WinToolTerminalChoice
    $summary = @(Get-WinToolTerminalSummary -Selection $choice)
    $preview = ($summary -join "`n")
    $ok = Request-WinToolConfirmation -Message ("Apply this terminal setup?`n`n" + $preview) -Title "Terminal"
    if (-not $ok) { return }
    $steps = @(Get-WinToolTerminalPlan -Selection $choice)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "Terminal setup finished. Open a new terminal window to see the prompt."
}
# endregion

# region src/UI/UpdatesView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolUpdateView {
    $catalog = Get-WinToolUpdateCatalog
    $gpus = @(Get-WinToolGpuInfo)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($gpu in $gpus) {
        $vendor = Resolve-WinToolGpuVendor -Name ([string]$gpu.Name) -Vendor @(Get-WinToolNote -Object $catalog -Name "vendors" -Default @())
        $text = [string]$gpu.Name
        if (-not [string]::IsNullOrWhiteSpace([string]$gpu.DriverVersion)) {
            $text = "{0}  (driver {1})" -f $text, $gpu.DriverVersion
        }
        if ($null -ne $vendor) {
            $text = "{0}  -  {1}" -f $text, [string]$vendor.name
        }
        $lines.Add($text)
    }
    $summary = "Windows did not report a graphics adapter."
    if ($lines.Count -gt 0) {
        $summary = $lines -join [Environment]::NewLine
    }
    (Get-WinToolUi -Name "GpuSummary").Text = $summary

    $panel = Get-WinToolUi -Name "VendorLinks"
    $panel.Children.Clear()
    foreach ($vendor in @(Get-WinToolNote -Object $catalog -Name "vendors" -Default @())) {
        $button = New-Object System.Windows.Controls.Button
        $button.Content = [string]$vendor.name + " downloads"
        $button.Style = $script:WinToolWindow.FindResource("SecondaryButton")
        $button.Margin = [System.Windows.Thickness]::new(0, 0, 8, 8)
        $button.Tag = [string]$vendor.url
        $button.ToolTip = [string](Get-WinToolNote -Object $vendor -Name "note" -Default "")
        Register-WinToolUiEvent -Control $button -EventName "Click" -Name "Updates: vendor downloads" -Data ([string]$vendor.url) -Action {
            param($source, $eventData, $url)
            $null = $source, $eventData
            Open-WinToolUri -Uri $url
        }
        [void]$panel.Children.Add($button)
    }

    Initialize-WinToolUpdateModeView

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ScanDrivers") -EventName "Click" -Name "Updates: scan" -Action { Invoke-WinToolScanClick }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "OpenWindowsUpdate") -EventName "Click" -Name "Updates: open Windows Update" -Action { Open-WinToolUri -Uri "ms-settings:windowsupdate" }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "OpenOptionalUpdates") -EventName "Click" -Name "Updates: open optional updates" -Action { Open-WinToolUri -Uri "ms-settings:windowsupdate-optionalupdates" }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "InstallScannedUpdates") -EventName "Click" -Name "Updates: install scanned updates" -Action { Invoke-WinToolInstallUpdatesClick }
}

function Invoke-WinToolScanClick {
    $criteria = "IsInstalled=0 and Type='Driver'"
    if ((Get-WinToolUi -Name "IncludeSoftwareUpdates").IsChecked -eq $true) {
        $criteria = "IsInstalled=0"
    }
    Sync-WinToolBusyState -Busy $true
    Sync-WinToolProgress -Value 0 -Text "Scanning Windows Update" -Indeterminate $true
    Write-WinToolLog -Message "Scanning Windows Update. This can take a few minutes." -Level "info"
    $script:WinToolState.UpdateJob = Start-WinToolScriptJob -ScriptText (Get-WinToolUpdateSearchScript) -Argument @($criteria)
}

function Complete-WinToolUpdateScan {
    $job = $script:WinToolState.UpdateJob
    $ok = $false
    $errorMessage = ""
    $lines = @()
    if ($null -ne $job) {
        $ok = [bool]$job.Sync.Ok
        $errorMessage = [string]$job.Sync.Error
        $lines = @($job.Sync.Lines)
        Stop-WinToolThread -Job $job
    }
    $script:WinToolState.UpdateJob = $null
    if (-not $ok) {
        Sync-WinToolBusyState -Busy $false
        Sync-WinToolProgress -Value 0 -Text "Ready" -Indeterminate $false
        Write-WinToolLog -Message ("Windows Update scan failed. {0}" -f $errorMessage) -Level "error"
        return
    }

    $list = Get-WinToolUi -Name "UpdateList"
    $list.Items.Clear()
    $records = New-Object System.Collections.Generic.List[object]
    foreach ($line in $lines) {
        $text = [string]$line
        $index = $text.IndexOf("`t")
        if ($index -lt 1) {
            continue
        }
        $kind = $text.Substring(0, $index)
        $title = $text.Substring($index + 1)
        $records.Add([pscustomobject]@{
            Kind = $kind
            Title = $title
        })
        [void]$list.Items.Add(("{0}   {1}" -f $kind, $title))
    }
    $script:WinToolState.Updates = $records.ToArray()
    $empty = Get-WinToolUi -Name "UpdateEmpty"
    if ($records.Count -eq 0) {
        $empty.Text = "Windows Update did not offer anything for this scan."
        $empty.Visibility = "Visible"
        Write-WinToolLog -Message "Scan finished. No updates were offered." -Level "ok"
    }
    else {
        $empty.Visibility = "Collapsed"
        Write-WinToolLog -Message ("Scan finished. {0} update(s) listed." -f $records.Count) -Level "ok"
    }
    Sync-WinToolBusyState -Busy $false
    Sync-WinToolProgress -Value 100 -Text "Scan finished" -Indeterminate $false
}

function Invoke-WinToolInstallUpdatesClick {
    $updates = @($script:WinToolState.Updates)
    if ($updates.Count -eq 0) {
        Write-WinToolLog -Message "Scan for updates before installing them." -Level "warn"
        return
    }
    $ok = Request-WinToolConfirmation -Message ("Download and install {0} Windows Update item(s)? The PC may need a restart." -f $updates.Count) -Title "Install updates"
    if (-not $ok) {
        return
    }
    $titles = New-Object System.Collections.Generic.List[string]
    foreach ($item in $updates) {
        $titles.Add([string]$item.Title)
    }
    $criteria = "IsInstalled=0 and Type='Driver'"
    if ((Get-WinToolUi -Name "IncludeSoftwareUpdates").IsChecked -eq $true) {
        $criteria = "IsInstalled=0"
    }
    Sync-WinToolBusyState -Busy $true
    Sync-WinToolProgress -Value 0 -Text "Installing Windows updates" -Indeterminate $true
    Write-WinToolLog -Message "Downloading and installing the scanned updates." -Level "info"
    $script:WinToolState.InstallJob = Start-WinToolScriptJob -ScriptText (Get-WinToolUpdateInstallScript) -Argument @($criteria, ($titles -join "`n"))
}

function Complete-WinToolUpdateInstall {
    $job = $script:WinToolState.InstallJob
    $ok = $false
    $errorMessage = ""
    $count = 0
    $reboot = $false
    if ($null -ne $job) {
        $ok = [bool]$job.Sync.Ok
        $errorMessage = [string]$job.Sync.Error
        if ($null -ne $job.Sync.Count) { $count = [int]$job.Sync.Count }
        if ($null -ne $job.Sync.Reboot) { $reboot = [bool]$job.Sync.Reboot }
        Stop-WinToolThread -Job $job
    }
    $script:WinToolState.InstallJob = $null
    Sync-WinToolBusyState -Busy $false
    Sync-WinToolProgress -Value 0 -Text "Ready" -Indeterminate $false
    if (-not $ok) {
        Write-WinToolLog -Message ("Update install failed. {0}" -f $errorMessage) -Level "error"
        return
    }
    if ($count -eq 0) {
        Write-WinToolLog -Message "Those updates were no longer offered when the install started." -Level "warn"
        return
    }
    Write-WinToolLog -Message ("Finished installing {0} update(s)." -f $count) -Level "ok"
    if ($reboot) {
        Write-WinToolLog -Message "Windows asked for a restart to finish the updates." -Level "warn"
    }
}

function Initialize-WinToolUpdateModeView {
    $list = Get-WinToolUi -Name "UpdateModeList"
    $list.Children.Clear()
    $radios = New-Object System.Collections.Generic.List[object]
    foreach ($mode in (Get-WinToolUpdateMode)) {
        $radio = New-Object System.Windows.Controls.RadioButton
        $radio.GroupName = "WinToolUpdateMode"
        $radio.Tag = [string]$mode.id
        $radio.Margin = [System.Windows.Thickness]::new(0, 0, 0, 10)
        $content = New-Object System.Windows.Controls.StackPanel
        [void]$content.Children.Add((New-WinToolText -Text ([string]$mode.name) -Weight "SemiBold"))
        [void]$content.Children.Add((New-WinToolText -Text ([string]$mode.description) -Size 13 -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 2, 0, 0))))
        $radio.Content = $content
        Register-WinToolUiEvent -Control $radio -EventName "Checked" -Name "Updates: pick mode" -Data ([string]$mode.id) -Action {
            param($source, $eventData, $modeId)
            $null = $source, $eventData
            $script:WinToolState.UpdateMode = $modeId
        }
        [void]$list.Children.Add($radio)
        $radios.Add($radio)
    }
    $script:WinToolState.UpdateModeRadios = $radios.ToArray()
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ApplyUpdateMode") -EventName "Click" -Name "Updates: apply mode" -Action {
        Invoke-WinToolUpdateModeClick -ModeId ([string]$script:WinToolState.UpdateMode)
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "RevertUpdateMode") -EventName "Click" -Name "Updates: back to default" -Action {
        Invoke-WinToolUpdateModeClick -ModeId "default"
    }
    Sync-WinToolUpdateMode
}

function Sync-WinToolUpdateMode {
    $current = "default"
    if (Test-WinToolWindows) {
        $snapshot = Get-WinToolUpdateModeSnapshot
        $current = Resolve-WinToolUpdateMode -Values $snapshot.Values -Services $snapshot.Services
    }
    $label = "Custom (policies set outside WinTool)"
    $mode = Find-WinToolUpdateMode -Id $current
    if ($null -ne $mode) {
        $label = [string]$mode.name
    }
    (Get-WinToolUi -Name "UpdateModeCurrent").Text = "Current mode: " + $label
    $script:WinToolState.UpdateModeCurrent = $current
    $script:WinToolState.UpdateMode = $current
    foreach ($radio in @($script:WinToolState.UpdateModeRadios)) {
        $radio.IsChecked = ([string]$radio.Tag -eq $current)
    }
}

function Invoke-WinToolUpdateModeClick {
    param(
        [string]$ModeId
    )
    $mode = $null
    if (-not [string]::IsNullOrWhiteSpace($ModeId)) {
        $mode = Find-WinToolUpdateMode -Id $ModeId
    }
    if ($null -eq $mode) {
        Write-WinToolLog -Message "Pick an update mode first." -Level "warn"
        return
    }
    $message = "Set Windows Update to: {0}?`n`n{1}" -f [string]$mode.name, [string]$mode.description
    if ($ModeId -eq "disabled") {
        $message += "`n`nThis is not recommended. Use Back to default to undo it."
    }
    $ok = Request-WinToolConfirmation -Message $message -Title "Update mode"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolUpdateModePlan -ModeId $ModeId)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage ("Windows Update mode set to " + [string]$mode.name + ".") -AfterDone "Sync-WinToolUpdateMode"
}
# endregion

# region src/UI/FixesView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolFixView {
    $hostPanel = Get-WinToolUi -Name "FixList"
    $hostPanel.Children.Clear()
    foreach ($fix in @(Get-WinToolNote -Object (Get-WinToolFixCatalog) -Name "fixes" -Default @())) {
        $card = New-WinToolCard
        $grid = New-Object System.Windows.Controls.Grid
        $grid.ColumnDefinitions.Add((New-WinToolColumn))
        $grid.ColumnDefinitions.Add((New-WinToolColumn -Auto))
        $text = New-Object System.Windows.Controls.StackPanel
        $title = New-Object System.Windows.Controls.StackPanel
        $title.Orientation = "Horizontal"
        [void]$title.Children.Add((New-WinToolText -Text ([string]$fix.name) -Size 16 -Weight "SemiBold"))
        if ([bool](Get-WinToolNote -Object $fix -Name "restart" -Default $false)) {
            [void]$title.Children.Add((New-WinToolBadge -Text "Restart needed" -Kind "caution"))
        }
        [void]$text.Children.Add($title)
        [void]$text.Children.Add((New-WinToolText -Text ([string]$fix.description) -Size 13 -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 4, 16, 0))))
        [System.Windows.Controls.Grid]::SetColumn($text, 0)
        [void]$grid.Children.Add($text)
        $button = New-Object System.Windows.Controls.Button
        $button.Content = "Run"
        $button.Style = $script:WinToolWindow.FindResource("SecondaryButton")
        $button.VerticalAlignment = "Center"
        [System.Windows.Controls.Grid]::SetColumn($button, 1)
        [void]$grid.Children.Add($button)
        Register-WinToolUiEvent -Control $button -EventName "Click" -Name ("Fixes: " + [string]$fix.name) -Data $fix -Action {
            param($source, $eventData, $boundFix)
            $null = $source, $eventData
            Invoke-WinToolFixClick -Fix $boundFix
        }
        Add-WinToolBusyControl -Control $button
        $card.Child = $grid
        [void]$hostPanel.Children.Add($card)
    }
}

function Invoke-WinToolFixClick {
    param(
        [Parameter(Mandatory = $true)]$Fix
    )
    $message = ([string]$Fix.name) + "?`n`n" + ([string]$Fix.description)
    $restart = [bool](Get-WinToolNote -Object $Fix -Name "restart" -Default $false)
    if ($restart) {
        $message += "`n`nRestart the PC when it finishes."
    }
    $ok = Request-WinToolConfirmation -Message $message -Title ([string]$Fix.name)
    if (-not $ok) {
        return
    }
    $done = ([string]$Fix.name) + " finished."
    if ($restart) {
        $done += " Restart the PC to complete it."
    }
    Invoke-WinToolPlanAsync -Step @(Get-WinToolFixPlan -Fix $Fix) -DoneMessage $done
}
# endregion

# region src/UI/FeaturesView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolFeatureView {
    $hostPanel = Get-WinToolUi -Name "FeatureList"
    $hostPanel.Children.Clear()
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($feature in @(Get-WinToolNote -Object (Get-WinToolFeatureCatalog) -Name "features" -Default @())) {
        $panel = New-Object System.Windows.Controls.Grid
        $panel.Margin = [System.Windows.Thickness]::new(0, 0, 0, 12)
        $panel.ColumnDefinitions.Add((New-WinToolColumn -Auto))
        $panel.ColumnDefinitions.Add((New-WinToolColumn))
        $panel.ColumnDefinitions.Add((New-WinToolColumn -Auto))
        $checkbox = New-Object System.Windows.Controls.CheckBox
        $checkbox.VerticalAlignment = "Top"
        $checkbox.Margin = [System.Windows.Thickness]::new(0, 2, 10, 0)
        $checkbox.IsEnabled = $false
        [System.Windows.Controls.Grid]::SetColumn($checkbox, 0)
        [void]$panel.Children.Add($checkbox)
        $text = New-Object System.Windows.Controls.StackPanel
        [void]$text.Children.Add((New-WinToolText -Text ([string]$feature.name) -Weight "SemiBold"))
        [void]$text.Children.Add((New-WinToolText -Text ([string]$feature.description) -Size 13 -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 2, 16, 0))))
        [System.Windows.Controls.Grid]::SetColumn($text, 1)
        [void]$panel.Children.Add($text)
        $state = New-WinToolText -Text "Checking..." -Size 12 -Brush "BrushMuted"
        $state.VerticalAlignment = "Top"
        [System.Windows.Controls.Grid]::SetColumn($state, 2)
        [void]$panel.Children.Add($state)
        [void]$hostPanel.Children.Add($panel)
        $rows.Add([pscustomobject]@{
            Feature = $feature
            Checkbox = $checkbox
            StateText = $state
            Status = "Unknown"
        })
    }
    $script:WinToolState.FeatureRows = $rows.ToArray()
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "FeatureRefresh") -EventName "Click" -Name "Features: refresh state" -Action {
        Start-WinToolFeatureDetection
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "FeatureApply") -EventName "Click" -Name "Features: apply changes" -Action {
        Invoke-WinToolFeatureApplyClick
    }
}

function Start-WinToolFeatureDetection {
    if ($null -ne $script:WinToolState.FeatureJob) {
        return
    }
    if (-not (Test-WinToolWindows)) {
        return
    }
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        $row.StateText.Text = "Checking..."
        $row.Checkbox.IsEnabled = $false
        foreach ($name in @($row.Feature.names)) {
            $names.Add([string]$name)
        }
    }
    (Get-WinToolUi -Name "FeatureStatus").Text = "Reading the current state..."
    $script:WinToolState.FeatureJob = Start-WinToolScriptJob -ScriptText (Get-WinToolFeatureStateScript) -Argument @(, $names.ToArray())
}

function Complete-WinToolFeatureDetection {
    $job = $script:WinToolState.FeatureJob
    if ($null -eq $job) {
        return
    }
    $ok = [bool]$job.Sync.Ok
    $errorMessage = [string]$job.Sync.Error
    $states = $job.Sync.States
    Stop-WinToolThread -Job $job
    $script:WinToolState.FeatureJob = $null
    if (-not $ok) {
        (Get-WinToolUi -Name "FeatureStatus").Text = "Could not read the Windows features."
        Write-WinToolLog -Message ("Could not read the Windows features. {0}" -f $errorMessage) -Level "warn"
        return
    }
    Set-WinToolFeatureState -State $states
}

function Set-WinToolFeatureState {
    param([hashtable]$State)
    $on = 0
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        $status = Get-WinToolFeatureStatus -Feature $row.Feature -State $State
        $row.Status = $status
        switch ($status) {
            "On" { $row.StateText.Text = "On"; $on++ }
            "Off" { $row.StateText.Text = "Off" }
            "Partial" { $row.StateText.Text = "Partly on" }
            default { $row.StateText.Text = "Not available on this PC" }
        }
        $row.Checkbox.IsEnabled = ($status -ne "Unavailable")
        $row.Checkbox.IsChecked = ($status -eq "On")
    }
    (Get-WinToolUi -Name "FeatureStatus").Text = ("{0} of these features are on. Tick or untick, then apply." -f $on)
}

function Get-WinToolFeatureChange {
    $enable = New-Object System.Collections.Generic.List[object]
    $disable = New-Object System.Collections.Generic.List[object]
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        if ($row.Status -eq "Unavailable" -or $row.Status -eq "Unknown") {
            continue
        }
        $wanted = ($row.Checkbox.IsChecked -eq $true)
        if ($wanted -and $row.Status -ne "On") {
            $enable.Add($row.Feature)
        }
        elseif (-not $wanted -and $row.Status -ne "Off") {
            $disable.Add($row.Feature)
        }
    }
    return [pscustomobject]@{
        Enable = $enable.ToArray()
        Disable = $disable.ToArray()
    }
}

function Invoke-WinToolFeatureApplyClick {
    $change = Get-WinToolFeatureChange
    $total = @($change.Enable).Count + @($change.Disable).Count
    if ($total -eq 0) {
        Write-WinToolLog -Message "No Windows feature changes to apply." -Level "warn"
        return
    }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($feature in @($change.Enable)) { $lines.Add("Turn on: " + [string]$feature.name) }
    foreach ($feature in @($change.Disable)) { $lines.Add("Turn off: " + [string]$feature.name) }
    $ok = Request-WinToolConfirmation -Message ("Change these Windows features?`n`n" + ($lines -join "`n") + "`n`nWindows needs a restart to finish.") -Title "Windows features"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolFeaturePlan -Enable $change.Enable -Disable $change.Disable)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "Windows features changed. Restart the PC to finish." -AfterDone "Start-WinToolFeatureDetection"
}
# endregion

# region src/UI/ConfigView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolConfigView {
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "SaveProfile") -EventName "Click" -Name "Config: save profile" -Action { Invoke-WinToolSaveProfile }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "LoadProfile") -EventName "Click" -Name "Config: load profile" -Action { Invoke-WinToolLoadProfile }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ExportWinget") -EventName "Click" -Name "Config: export winget list" -Action { Invoke-WinToolExportWinget }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ImportWinget") -EventName "Click" -Name "Config: import winget list" -Action { Invoke-WinToolImportWinget }
    Initialize-WinToolSystemView
    Update-WinToolProfileSummary
}

function Update-WinToolProfileSummary {
    $apps = @(Get-WinToolCheckedApp)
    $tweaks = @(Get-WinToolCheckedTweak)
    $terminal = Get-WinToolTerminalChoice
    $prompt = "Oh My Posh"
    if ($terminal.prompt -eq "starship") {
        $prompt = "Starship"
    }
    $replay = "Terminal setup is saved with the profile."
    if (-not $terminal.enabled) {
        $replay = "Terminal setup is not included when this profile is replayed."
    }
    $text = "{0} apps selected, {1} tweaks selected. Prompt: {2}. {3}" -f $apps.Count, $tweaks.Count, $prompt, $replay
    (Get-WinToolUi -Name "ProfileSummary").Text = $text
}

function Get-WinToolProfileFromUi {
    $apps = @(Get-WinToolCheckedApp)
    $tweaks = @(Get-WinToolCheckedTweak)
    $appIds = New-Object System.Collections.Generic.List[string]
    foreach ($app in $apps) {
        $appIds.Add([string]$app.Id)
    }
    $tweakIds = New-Object System.Collections.Generic.List[string]
    foreach ($tweak in $tweaks) {
        $tweakIds.Add([string]$tweak.id)
    }
    return (ConvertTo-WinToolProfile -AppId $appIds.ToArray() -TweakId $tweakIds.ToArray() -Terminal (Get-WinToolTerminalChoice) -Name "My WinTool profile")
}

function Import-WinToolProfileToUi {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    $toolProfile = Read-WinToolProfile -Path $Path
    $resolved = Resolve-WinToolProfileSelection -Profile $toolProfile
    foreach ($id in @($resolved.UnknownApps)) {
        Write-WinToolLog -Message "Unknown app id '$id' in the profile." -Level "warn"
    }
    foreach ($id in @($resolved.UnknownTweaks)) {
        Write-WinToolLog -Message "Unknown tweak id '$id' in the profile." -Level "warn"
    }
    $appIds = New-Object System.Collections.Generic.List[string]
    foreach ($app in @($resolved.AppRecords)) {
        $appIds.Add([string]$app.id)
    }
    $tweakIds = New-Object System.Collections.Generic.List[string]
    foreach ($tweak in @($resolved.TweakRecords)) {
        $tweakIds.Add([string]$tweak.id)
    }
    Sync-WinToolAppCheck -Id $appIds.ToArray() -OnlyThese
    Sync-WinToolTweakCheck -Id $tweakIds.ToArray() -OnlyThese
    Sync-WinToolTerminalChoice -Selection (Get-WinToolNote -Object $toolProfile -Name "terminal")
    Update-WinToolProfileSummary
    Write-WinToolLog -Message ("Loaded {0}. Nothing was installed yet." -f $Path) -Level "ok"
}

function Invoke-WinToolSaveProfile {
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Filter = "WinTool profile (*.json)|*.json"
    $dialog.FileName = "wintool-profile.json"
    $dialog.Title = "Save WinTool profile"
    $accepted = $dialog.ShowDialog($script:WinToolWindow)
    if ($accepted -ne $true) {
        return
    }
    $toolProfile = Get-WinToolProfileFromUi
    Write-WinToolProfile -Path $dialog.FileName -Profile $toolProfile
    Write-WinToolLog -Message ("Saved profile to {0}" -f $dialog.FileName) -Level "ok"
}

function Invoke-WinToolLoadProfile {
    $dialog = New-Object Microsoft.Win32.OpenFileDialog
    $dialog.Filter = "WinTool profile (*.json)|*.json"
    $dialog.Title = "Load WinTool profile"
    $accepted = $dialog.ShowDialog($script:WinToolWindow)
    if ($accepted -ne $true) {
        return
    }
    try {
        Import-WinToolProfileToUi -Path $dialog.FileName
    }
    catch {
        Write-WinToolLog -Message ("Could not load that profile. {0}" -f $_.Exception.Message) -Level "error"
    }
}

function Invoke-WinToolExportWinget {
    $winget = Get-WinToolWingetPath
    if ([string]::IsNullOrWhiteSpace($winget)) {
        Write-WinToolLog -Message "winget was not found. Install App Installer from the Microsoft Store, then try again." -Level "warn"
        return
    }
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Filter = "winget package list (*.json)|*.json"
    $dialog.FileName = "winget-packages.json"
    $dialog.Title = "Export winget package list"
    $accepted = $dialog.ShowDialog($script:WinToolWindow)
    if ($accepted -ne $true) {
        return
    }
    $step = [pscustomobject]@{
        Type = "process"
        Label = "Export winget packages"
        FilePath = $winget
        Arguments = @("export", "-o", $dialog.FileName, "--accept-source-agreements")
    }
    Invoke-WinToolPlanAsync -Step @($step) -DoneMessage "winget export finished."
}

function Invoke-WinToolImportWinget {
    $winget = Get-WinToolWingetPath
    if ([string]::IsNullOrWhiteSpace($winget)) {
        Write-WinToolLog -Message "winget was not found. Install App Installer from the Microsoft Store, then try again." -Level "warn"
        return
    }
    $dialog = New-Object Microsoft.Win32.OpenFileDialog
    $dialog.Filter = "winget package list (*.json)|*.json"
    $dialog.Title = "Import winget package list"
    $accepted = $dialog.ShowDialog($script:WinToolWindow)
    if ($accepted -ne $true) {
        return
    }
    $ok = Request-WinToolConfirmation -Message "Ask winget to install every package in this file?" -Title "Import winget list"
    if (-not $ok) {
        return
    }
    $step = [pscustomobject]@{
        Type = "process"
        Label = "Import winget packages"
        FilePath = $winget
        Arguments = @("import", "-i", $dialog.FileName, "--accept-package-agreements", "--accept-source-agreements", "--disable-interactivity")
    }
    Invoke-WinToolPlanAsync -Step @($step) -DoneMessage "winget import finished."
}

function Initialize-WinToolSystemView {
    $catalog = Get-WinToolSystemCatalog
    $providerBox = Get-WinToolUi -Name "DnsProvider"
    $providerBox.Items.Clear()
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $catalog)) {
        $item = New-Object System.Windows.Controls.ComboBoxItem
        $item.Content = [string]$provider.name
        $item.Tag = [string]$provider.id
        $item.ToolTip = [string](Get-WinToolNote -Object $provider -Name "description" -Default "")
        [void]$providerBox.Items.Add($item)
    }
    $providerBox.SelectedIndex = 0
    $plan = Get-WinToolNote -Object $catalog -Name "powerPlan"
    (Get-WinToolUi -Name "PowerPlanDescription").Text = [string]$plan.description

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "DnsAdapter") -EventName "SelectionChanged" -Name "Config: pick adapter" -Action { Sync-WinToolDnsSummary }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "RefreshDns") -EventName "Click" -Name "Config: refresh adapters" -Action { Update-WinToolSystemView }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ApplyDns") -EventName "Click" -Name "Config: apply DNS" -Action { Invoke-WinToolDnsClick }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AddUltimatePlan") -EventName "Click" -Name "Config: add Ultimate Performance" -Action { Invoke-WinToolPowerPlanClick -Action "add" }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "RemoveUltimatePlan") -EventName "Click" -Name "Config: remove Ultimate Performance" -Action { Invoke-WinToolPowerPlanClick -Action "remove" }
}

function Update-WinToolSystemView {
    $adapters = @()
    try {
        $adapters = @(Get-WinToolDnsAdapter)
    }
    catch {
        Write-WinToolLog -Message ("Could not read network adapters. " + $_.Exception.Message) -Level "warn"
    }
    $script:WinToolState.DnsAdapters = $adapters
    $box = Get-WinToolUi -Name "DnsAdapter"
    $box.Items.Clear()
    if ($adapters.Count -gt 1) {
        $all = New-Object System.Windows.Controls.ComboBoxItem
        $all.Content = "All connected adapters"
        $all.Tag = -1
        [void]$box.Items.Add($all)
    }
    foreach ($adapter in $adapters) {
        $item = New-Object System.Windows.Controls.ComboBoxItem
        $item.Content = ("{0}  -  {1}" -f [string]$adapter.Name, [string]$adapter.Description)
        $item.Tag = [int]$adapter.Index
        [void]$box.Items.Add($item)
    }
    if ($box.Items.Count -gt 0) {
        $box.SelectedIndex = 0
    }
    Sync-WinToolDnsSummary
    Sync-WinToolPowerPlanStatus
}

function Get-WinToolSelectedDnsAdapter {
    $item = (Get-WinToolUi -Name "DnsAdapter").SelectedItem
    if ($null -eq $item) {
        return @()
    }
    $index = [int]$item.Tag
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($adapter in @($script:WinToolState.DnsAdapters)) {
        if ($index -eq -1 -or [int]$adapter.Index -eq $index) {
            $list.Add($adapter)
        }
    }
    return $list.ToArray()
}

function Sync-WinToolDnsSummary {
    $selected = @(Get-WinToolSelectedDnsAdapter)
    $text = "No connected network adapter found."
    if ($selected.Count -gt 0) {
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($adapter in $selected) {
            $lines.Add((Format-WinToolDnsSummary -Adapter $adapter))
        }
        $text = "Now: " + ($lines -join [Environment]::NewLine)
    }
    (Get-WinToolUi -Name "DnsCurrent").Text = $text
}

function Sync-WinToolPowerPlanStatus {
    $text = "Power plans are only on Windows."
    if (Test-WinToolWindows) {
        try {
            $schemes = ConvertFrom-WinToolPowerList -Text ((& powercfg.exe /list) | Out-String)
            $catalog = Get-WinToolSystemCatalog
            $state = Get-WinToolPowerPlanState -Scheme $schemes -Catalog $catalog
            $text = Format-WinToolPowerPlanStatus -State $state -Name ([string]$catalog.powerPlan.name)
            (Get-WinToolUi -Name "RemoveUltimatePlan").IsEnabled = [bool]$state.Added
        }
        catch {
            $text = "Could not read power plans. " + $_.Exception.Message
        }
    }
    (Get-WinToolUi -Name "PowerPlanStatus").Text = $text
}

function Invoke-WinToolDnsClick {
    $adapters = @(Get-WinToolSelectedDnsAdapter)
    if ($adapters.Count -eq 0) {
        Write-WinToolLog -Message "Pick a network adapter first." -Level "warn"
        return
    }
    $item = (Get-WinToolUi -Name "DnsProvider").SelectedItem
    if ($null -eq $item) {
        Write-WinToolLog -Message "Pick a DNS provider first." -Level "warn"
        return
    }
    $provider = Find-WinToolDnsProvider -Id ([string]$item.Tag)
    $ipv6 = ((Get-WinToolUi -Name "DnsIncludeIpv6").IsChecked -eq $true)
    $servers = @(Get-WinToolDnsServerList -Provider $provider -IncludeIpv6 $ipv6)
    $what = "automatic (DHCP)"
    if ($servers.Count -gt 0) {
        $what = [string]$provider.name + " (" + ($servers -join ", ") + ")"
    }
    $names = (@($adapters | ForEach-Object { [string]$_.Name })) -join ", "
    $ok = Request-WinToolConfirmation -Message ("Set DNS on {0} to {1}?" -f $names, $what) -Title "DNS servers"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolDnsPlan -Adapter $adapters -Provider $provider -IncludeIpv6 $ipv6)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "DNS servers changed." -AfterDone "Update-WinToolSystemView"
}

function Invoke-WinToolPowerPlanClick {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("add", "remove")][string]$Action
    )
    $message = "Add the Ultimate Performance power plan and switch to it?"
    if ($Action -eq "remove") {
        $message = "Remove the Ultimate Performance plan WinTool added? If it is active, Windows goes back to Balanced."
    }
    $ok = Request-WinToolConfirmation -Message $message -Title "Power plan"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolPowerPlanPlan -Action $Action)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "Power plan updated." -AfterDone "Sync-WinToolPowerPlanStatus"
}
# endregion

# region src/UI/Shell.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Request-WinToolConfirmation {
    param(
        [Parameter(Mandatory = $true)][string]$Message,
        [Parameter(Mandatory = $true)][string]$Title
    )
    $answer = [System.Windows.MessageBox]::Show(
        $Message,
        $Title,
        [System.Windows.MessageBoxButton]::YesNo,
        [System.Windows.MessageBoxImage]::Question)
    return ($answer -eq [System.Windows.MessageBoxResult]::Yes)
}

function Get-WinToolViewName {
    return @("Install", "Tweaks", "Terminal", "Updates", "Fixes", "Features", "Config")
}

function Add-WinToolBusyControl {
    param(
        [Parameter(Mandatory = $true)]$Control
    )
    if ($null -eq $script:WinToolState.BusyControls) {
        $script:WinToolState.BusyControls = New-Object System.Collections.Generic.List[object]
    }
    $script:WinToolState.BusyControls.Add($Control)
}

function Switch-WinToolView {
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )
    foreach ($view in @(Get-WinToolViewName)) {
        $element = Get-WinToolUi -Name ("View" + $view)
        if ($view -eq $Name) {
            $element.Visibility = "Visible"
        }
        else {
            $element.Visibility = "Collapsed"
        }
    }
    if ($Name -eq "Config") {
        Update-WinToolProfileSummary
        if (-not $script:WinToolState.SystemChecked) {
            $script:WinToolState.SystemChecked = $true
            Update-WinToolSystemView
        }
    }
    if ($Name -eq "Features" -and -not $script:WinToolState.FeaturesChecked) {
        $script:WinToolState.FeaturesChecked = $true
        Start-WinToolFeatureDetection
    }
}

function Sync-WinToolStatus {
    param(
        [Parameter(Mandatory = $true)][string]$Text
    )
    (Get-WinToolUi -Name "StatusText").Text = $Text
}

function Sync-WinToolProgress {
    param(
        [int]$Value,
        [string]$Text,
        [bool]$Indeterminate = $false
    )
    $bar = Get-WinToolUi -Name "MainProgress"
    $bar.IsIndeterminate = $Indeterminate
    if (-not $Indeterminate) {
        $bar.Value = $Value
    }
    if (-not [string]::IsNullOrWhiteSpace($Text)) {
        Sync-WinToolStatus -Text $Text
    }
}

function Sync-WinToolLogPanel {
    $expanded = $false
    if ($script:WinToolState.LogExpanded) {
        $expanded = $true
    }
    $busy = $false
    if ($script:WinToolState.Busy) {
        $busy = $true
    }
    $log = Get-WinToolUi -Name "LogPanel"
    $bar = Get-WinToolUi -Name "MainProgress"
    $toggle = Get-WinToolUi -Name "ToggleLogButton"
    $clear = Get-WinToolUi -Name "ClearLogButton"
    if ($expanded) {
        $log.Visibility = "Visible"
        $toggle.Content = "Hide log"
        $clear.Visibility = "Visible"
    }
    else {
        $log.Visibility = "Collapsed"
        $toggle.Content = "Show log"
        $clear.Visibility = "Collapsed"
    }
    if ($busy) {
        $bar.Visibility = "Visible"
    }
    else {
        $bar.Visibility = "Collapsed"
        $bar.IsIndeterminate = $false
    }
}

function Switch-WinToolLogPanel {
    if ($script:WinToolState.LogExpanded) {
        $script:WinToolState.LogExpanded = $false
        $script:WinToolState.LogPinned = $false
    }
    else {
        $script:WinToolState.LogExpanded = $true
        $script:WinToolState.LogPinned = $true
    }
    Sync-WinToolLogPanel
}

function Sync-WinToolBusyState {
    param(
        [bool]$Busy
    )
    $wasBusy = $false
    if ($script:WinToolState.Busy) {
        $wasBusy = $true
    }
    $script:WinToolState.Busy = $Busy
    if ($Busy -and -not $wasBusy) {
        $script:WinToolState.LogExpanded = $true
    }
    elseif (-not $Busy -and $wasBusy -and -not $script:WinToolState.LogPinned) {
        $script:WinToolState.LogExpanded = $false
    }
    Sync-WinToolLogPanel
    $names = @(
        "AppInstall", "AppSelectVisible", "AppClear",
        "AppSelectInstalled", "AppRefreshInstalled", "AppUpdate", "AppUninstall", "AppUpgradeAll",
        "FeatureApply",
        "TweakApply", "TweakUndo", "TweakClear",
        "TerminalSetup", "ScanDrivers",
        "SaveProfile", "LoadProfile", "ExportWinget", "ImportWinget"
    )
    foreach ($name in $names) {
        (Get-WinToolUi -Name $name).IsEnabled = -not $Busy
    }
    if ($null -ne $script:WinToolState.BusyControls) {
        foreach ($control in $script:WinToolState.BusyControls.ToArray()) {
            $control.IsEnabled = -not $Busy
        }
    }
    $installUpdates = Get-WinToolUi -Name "InstallScannedUpdates"
    if ($Busy) {
        $installUpdates.IsEnabled = $false
    }
    else {
        $installUpdates.IsEnabled = (@($script:WinToolState.Updates).Count -gt 0)
    }
    $cancel = Get-WinToolUi -Name "CancelRun"
    if ($Busy) {
        $cancel.Visibility = "Visible"
    }
    else {
        $cancel.Visibility = "Collapsed"
    }
}

function Enable-WinToolLogPump {
    if ($null -ne $script:WinToolState.Pump) {
        return
    }
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(200)
    Register-WinToolUiEvent -Control $timer -EventName "Tick" -Name "Log refresh" -Action { Update-WinToolLogPump }
    $timer.Start()
    $script:WinToolState.Pump = $timer
}

function Invoke-WinToolPlanAsync {
    param(
        $Step,
        [Parameter(Mandatory = $true)][string]$DoneMessage,
        [string]$AfterDone
    )
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $queue = New-Object System.Collections.Concurrent.ConcurrentQueue[string]
    $script:WinToolState.Run = @{
        Steps = @($Step)
        Index = -1
        Process = $null
        Queue = $queue
        StepLog = New-Object System.Collections.Generic.List[string]
        ExitHandled = $false
        Cancel = $false
        DoneMessage = $DoneMessage
        AfterDone = $AfterDone
        SkipZsh = $false
    }
    Sync-WinToolBusyState -Busy $true
    Enable-WinToolLogPump
    Move-WinToolPlanForward
}

function Move-WinToolPlanForward {
    $run = $script:WinToolState.Run
    if ($null -eq $run) {
        return
    }
    if ($run.Cancel) {
        Complete-WinToolPlan -Message "Cancelled."
        return
    }
    $run.Index = [int]$run.Index + 1
    $steps = @($run.Steps)
    if ($run.Index -ge $steps.Count) {
        Complete-WinToolPlan -Message ([string]$run.DoneMessage)
        return
    }
    $step = $steps[$run.Index]
    $total = $steps.Count
    $percent = 0
    if ($total -gt 0) {
        $percent = [int]((100.0 * $run.Index) / $total)
    }
    Sync-WinToolProgress -Value $percent -Text ("{0} ({1} of {2})" -f [string]$step.Label, ($run.Index + 1), $total) -Indeterminate $false
    Write-WinToolLog -Message ([string]$step.Label) -Level "info"

    if ([string]$step.Type -eq "wsl-shell" -and $run.SkipZsh) {
        Write-WinToolLog -Message "Zsh setup is waiting on a reboot. Run terminal setup again after Windows restarts." -Level "warn"
        Move-WinToolPlanForward
        return
    }

    $command = Get-WinToolPlanCommand -Step $step
    if ($null -eq $command) {
        try {
            Invoke-WinToolLocalStep -Step $step
        }
        catch {
            Write-WinToolLog -Message ("{0} failed. {1}" -f [string]$step.Label, $_.Exception.Message) -Level "error"
        }
        Move-WinToolPlanForward
        return
    }

    $filePath = [string]$command.FilePath
    if ([string]::IsNullOrWhiteSpace($filePath) -or -not (Test-Path -LiteralPath $filePath)) {
        Write-WinToolLog -Message ("Skipped {0} because the program was not found." -f [string]$step.Label) -Level "warn"
        if ([string]$step.Type -eq "winget") {
            Write-WinToolLog -Message "Install App Installer from the Microsoft Store, then try again." -Level "warn"
        }
        Move-WinToolPlanForward
        return
    }

    $run.StepLog = New-Object System.Collections.Generic.List[string]
    $run.ExitHandled = $false
    try {
        $run.Process = Start-WinToolAsyncProcess -FilePath $filePath -ArgumentList @($command.ArgumentList) -LineQueue $run.Queue
    }
    catch {
        Write-WinToolLog -Message ("Could not start {0}. {1}" -f [string]$step.Label, $_.Exception.Message) -Level "error"
        $run.Process = $null
        Move-WinToolPlanForward
    }
}

function Complete-WinToolPlanStep {
    $run = $script:WinToolState.Run
    if ($null -eq $run -or $null -eq $run.Process) {
        return
    }
    $code = -1
    try {
        $code = [int]$run.Process.ExitCode
    }
    catch {
        $code = -1
    }
    $output = ""
    if ($null -ne $run.StepLog -and $run.StepLog.Count -gt 0) {
        $output = ($run.StepLog -join "`n")
    }
    $steps = @($run.Steps)
    $step = $steps[$run.Index]
    $run.Process = $null
    if ($run.Cancel) {
        Complete-WinToolPlan -Message "Cancelled."
        return
    }
    if ([string]$step.Type -eq "winget") {
        $result = ConvertTo-WinToolWingetResult -ExitCode $code -Output $output
        if ($result.Status -eq "Failed") {
            Write-WinToolLog -Message ("{0} failed (exit {1})." -f [string]$step.Label, $code) -Level "error"
        }
        elseif ($result.Status -eq "AlreadyInstalled") {
            Write-WinToolLog -Message ("{0}: {1}." -f [string]$step.Label, (Get-WinToolWingetOutcomeText -Action (Get-WinToolWingetStepAction -Step $step) -Status $result.Status)) -Level "ok"
        }
        else {
            Write-WinToolLog -Message ("{0}: done." -f [string]$step.Label) -Level "ok"
        }
    }
    elseif (-not (Test-WinToolStepSuccess -Step $step -ExitCode $code)) {
        Write-WinToolLog -Message ("{0} exited with code {1}." -f [string]$step.Label, $code) -Level "error"
    }
    else {
        Write-WinToolLog -Message ("{0}: done." -f [string]$step.Label) -Level "ok"
    }
    if ([string]$step.Type -eq "wsl-install" -and $output -match "(?i)reboot") {
        $run.SkipZsh = $true
        Write-WinToolLog -Message "Windows asked for a reboot before WSL can finish." -Level "warn"
    }
    Move-WinToolPlanForward
}

function Complete-WinToolPlan {
    param(
        [Parameter(Mandatory = $true)][string]$Message
    )
    $run = $script:WinToolState.Run
    if ($null -ne $run -and $null -ne $run.Process) {
        try {
            if (-not $run.Process.HasExited) {
                $run.Process.Kill()
            }
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    $afterDone = $null
    if ($null -ne $run) {
        $afterDone = [string]$run.AfterDone
    }
    $script:WinToolState.Run = $null
    Sync-WinToolBusyState -Busy $false
    if ($Message -eq "Cancelled.") {
        Sync-WinToolProgress -Value 0 -Text "Cancelled" -Indeterminate $false
        Write-WinToolLog -Message $Message -Level "warn"
    }
    else {
        Sync-WinToolProgress -Value 100 -Text "Ready" -Indeterminate $false
        Write-WinToolLog -Message $Message -Level "ok"
    }
    if (-not [string]::IsNullOrWhiteSpace($afterDone)) {
        try {
            & $afterDone
        }
        catch {
            Write-WinToolLog -Message ("Follow-up step failed. {0}" -f $_.Exception.Message) -Level "warn"
        }
    }
}

function Stop-WinToolRun {
    $run = $script:WinToolState.Run
    if ($null -ne $run) {
        $run.Cancel = $true
        if ($null -ne $run.Process) {
            try {
                if (-not $run.Process.HasExited) {
                    $run.Process.Kill()
                }
            }
            catch {
                Complete-WinToolPlan -Message "Cancelled."
            }
        }
        else {
            Complete-WinToolPlan -Message "Cancelled."
        }
        return
    }
    foreach ($name in @("RestoreJob", "UpdateJob", "InstallJob")) {
        $job = $script:WinToolState[$name]
        if ($null -ne $job) {
            Stop-WinToolThread -Job $job
            $script:WinToolState[$name] = $null
        }
    }
    Sync-WinToolBusyState -Busy $false
    Sync-WinToolProgress -Value 0 -Text "Cancelled" -Indeterminate $false
    Write-WinToolLog -Message "Cancelled." -Level "warn"
}

function Update-WinToolLogPump {
    $run = $script:WinToolState.Run
    if ($null -ne $run -and $null -ne $run.Queue) {
        $line = $null
        while ($run.Queue.TryDequeue([ref]$line)) {
            if (-not [string]::IsNullOrWhiteSpace($line)) {
                # sfc.exe writes UTF-16, which arrives with NUL characters.
                $clean = $line.Replace([string][char]0, "").Trim()
                if ($null -ne $run.StepLog) {
                    $run.StepLog.Add($clean)
                }
                Add-WinToolLogLine -Line ("           " + $clean)
            }
        }
        if ($null -ne $run.Process -and $run.Process.HasExited -and -not $run.ExitHandled) {
            $run.ExitHandled = $true
            Complete-WinToolPlanStep
        }
    }

    $restore = $script:WinToolState.RestoreJob
    if ($null -ne $restore -and $restore.Sync.Done) {
        $ok = [bool]$restore.Sync.Ok
        $errorMessage = [string]$restore.Sync.Error
        Stop-WinToolThread -Job $restore
        $script:WinToolState.RestoreJob = $null
        Complete-WinToolRestorePoint -Ok $ok -ErrorMessage $errorMessage
    }

    $update = $script:WinToolState.UpdateJob
    if ($null -ne $update -and $update.Sync.Done) {
        Complete-WinToolUpdateScan
    }

    $featureJob = $script:WinToolState.FeatureJob
    if ($null -ne $featureJob -and $featureJob.Sync.Done) {
        Complete-WinToolFeatureDetection
    }

    $detect = $script:WinToolState.DetectJob
    if ($null -ne $detect -and $detect.Sync.Done) {
        Complete-WinToolAppDetection
    }
    else {
        Test-WinToolAppDetectionTimeout
    }

    $install = $script:WinToolState.InstallJob
    if ($null -ne $install -and $install.Sync.Done) {
        Complete-WinToolUpdateInstall
    }
}

function Initialize-WinToolShellEvent {
    (Get-WinToolUi -Name "VersionText").Text = "Version " + $script:WinToolVersion
    foreach ($view in @(Get-WinToolViewName)) {
        Register-WinToolUiEvent -Control (Get-WinToolUi -Name ("Nav" + $view)) -EventName "Checked" -Name ("Open the " + $view + " tab") -Data $view -Action {
            param($source, $eventData, $viewName)
            $null = $source, $eventData
            Switch-WinToolView -Name $viewName
        }
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ClearLogButton") -EventName "Click" -Name "Clear log" -Action {
        (Get-WinToolUi -Name "LogBox").Clear()
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ToggleLogButton") -EventName "Click" -Name "Show log" -Action {
        Switch-WinToolLogPanel
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "CancelRun") -EventName "Click" -Name "Cancel" -Action {
        Stop-WinToolRun
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ProjectLink") -EventName "RequestNavigate" -Name "Open project link" -Action {
        $uiEvent = $args[1]
        if ($null -ne $uiEvent -and $null -ne $uiEvent.Uri) {
            Open-WinToolUri -Uri $uiEvent.Uri.AbsoluteUri
            $uiEvent.Handled = $true
        }
    }
    Register-WinToolUiEvent -Control $script:WinToolWindow -EventName "PreviewKeyDown" -Name "Keyboard shortcut" -Action {
        $uiEvent = $args[1]
        $modifiers = [System.Windows.Input.Keyboard]::Modifiers
        $control = [System.Windows.Input.ModifierKeys]::Control
        if (($modifiers -band $control) -eq $control -and $uiEvent.Key -eq "F") {
            if ((Get-WinToolUi -Name "ViewInstall").Visibility -eq "Visible") {
                (Get-WinToolUi -Name "AppSearch").Focus() | Out-Null
            }
            elseif ((Get-WinToolUi -Name "ViewTweaks").Visibility -eq "Visible") {
                (Get-WinToolUi -Name "TweakSearch").Focus() | Out-Null
            }
            $uiEvent.Handled = $true
        }
    }
    Register-WinToolUiEvent -Control $script:WinToolWindow -EventName "Closing" -Name "Close WinTool" -Action {
        $uiEvent = $args[1]
        if ($script:WinToolState.Busy) {
            $ok = Request-WinToolConfirmation -Message "A task is still running. Stop it and close WinTool?" -Title "WinTool is busy"
            if (-not $ok) {
                $uiEvent.Cancel = $true
                return
            }
            Stop-WinToolRun
        }
    }
    Register-WinToolUiEvent -Control $script:WinToolWindow -EventName "Closed" -Name "Window closed" -Action {
        if ($null -ne $script:WinToolState.Pump) {
            $script:WinToolState.Pump.Stop()
        }
    }
    Register-WinToolUiEvent -Control $script:WinToolWindow -EventName "Loaded" -Name "Window loaded" -Action {
        Write-WinToolLog -Message "Welcome to WinTool. Choose what you want, then run it when you are ready." -Level "info"
        $winget = Get-WinToolWingetPath
        if ([string]::IsNullOrWhiteSpace($winget)) {
            Write-WinToolLog -Message "winget was not found. Install App Installer from the Microsoft Store before installing apps." -Level "warn"
            Sync-WinToolStatus -Text "winget not found"
        }
        else {
            Write-WinToolLog -Message "winget is available." -Level "ok"
            Sync-WinToolStatus -Text "Ready"
        }
    }
    Register-WinToolUiEvent -Control $script:WinToolWindow -EventName "Loaded" -Name "Check installed apps" -Action {
        Start-WinToolAppDetection
    }
}

function New-WinToolWindow {
    Add-Type -AssemblyName PresentationFramework
    Add-Type -AssemblyName PresentationCore
    Add-Type -AssemblyName WindowsBase

    $script:WinToolState = @{
        Busy = $false
        AppRows = @()
        CategoryRows = @()
        TweakRows = @()
        TweakGroups = @()
        Updates = @()
        UpdateMode = ""
        UpdateModeCurrent = ""
        UpdateModeRadios = @()
        DnsAdapters = @()
        SystemChecked = $false
        Run = $null
        Pump = $null
        RestoreJob = $null
        UpdateJob = $null
        InstallJob = $null
        DetectJob = $null
        BusyControls = $null
        FeatureJob = $null
        FeatureRows = @()
        PendingTweaks = @()
        PendingDirection = "Apply"
        PendingRestart = $true
        LogExpanded = $false
        LogPinned = $false
    }

    $xaml = Get-WinToolPayloadText -Name "Xaml"
    [xml]$document = $xaml
    $reader = New-Object System.Xml.XmlNodeReader $document
    $window = [System.Windows.Markup.XamlReader]::Load($reader)
    $script:WinToolWindow = $window
    $script:WinToolLogBox = $window.FindName("LogBox")

    Initialize-WinToolAppearance
    Initialize-WinToolInstallView
    Initialize-WinToolTweakView
    Initialize-WinToolTerminalView
    Initialize-WinToolUpdateView
    Initialize-WinToolFixView
    Initialize-WinToolFeatureView
    Initialize-WinToolConfigView
    Initialize-WinToolShellEvent
    Sync-WinToolLogPanel
    Register-WinToolUiEvent -Control $window -EventName "Activated" -Name "Follow the Windows theme" -Action {
        if ($null -eq $script:WinToolSetting) { return }
        if ([string]$script:WinToolSetting.theme -ne "system") { return }
        $want = "dark"
        if (Test-WinToolSystemLightTheme) { $want = "light" }
        if ([string]$script:WinToolResolvedTheme -ne $want) {
            Set-WinToolTheme -Theme "system" -Accent ([string]$script:WinToolSetting.accent)
        }
    }

    if (-not [string]::IsNullOrWhiteSpace($script:WinToolApplyProfile)) {
        try {
            Import-WinToolProfileToUi -Path $script:WinToolApplyProfile
        }
        catch {
            Write-WinToolLog -Message ("Could not load the profile. {0}" -f $_.Exception.Message) -Level "error"
        }
    }

    return $window
}

function Show-WinToolWindow {
    $window = New-WinToolWindow
    Enable-WinToolLogPump
    Register-WinToolUiEvent -Control $window -EventName "ContentRendered" -Name "Hide the console" -Action { Hide-WinToolConsole }
    try {
        $null = $window.ShowDialog()
    }
    finally {
        # Give a console the user opened back to them. A hidden relaunch just exits.
        if ($script:WinToolConsoleHidden -and $env:WINTOOL_HIDDEN -ne "1") {
            $null = Set-WinToolConsoleVisible -Visible $true
        }
    }
}
